pub fn build_issue_counts(rows: &[Value], checks: &[Value]) -> Value {
    let mut counts = zero_counts(ISSUE_TYPES);
    for row in rows {
        if let Some(issue_type) = row.get("issueType").filter(|value| js_truthy(Some(value))) {
            increment_known_count(&mut counts, issue_type, ISSUE_TYPES);
        }
        if let Some(issue) = row
            .get("issue")
            .filter(|value| js_truthy(Some(value)) && *value != &json!("none"))
        {
            increment_known_count(&mut counts, issue, ISSUE_TYPES);
        }
    }
    for check in checks {
        if check.get("status") == Some(&json!("failed")) {
            if let Some(issue_type) = check
                .get("issueType")
                .filter(|value| js_truthy(Some(value)))
            {
                increment_known_count(&mut counts, issue_type, ISSUE_TYPES);
            }
        }
    }
    Value::Object(counts)
}

pub fn build_source_scope_issue_counts(rows: &[Value]) -> Value {
    let mut counts = zero_counts(SCOPE_ISSUE_TYPES);
    for row in rows {
        if let Some(issue) = row
            .get("issue")
            .filter(|value| js_truthy(Some(value)) && *value != &json!("none"))
        {
            increment_known_count(&mut counts, issue, SCOPE_ISSUE_TYPES);
        }
    }
    Value::Object(counts)
}

pub fn build_generated_registry_issue_counts(rows: &[Value]) -> Value {
    let mut counts = zero_counts(GENERATED_REGISTRY_ISSUE_TYPES);
    for row in rows {
        if let Some(issue) = row
            .get("issue")
            .filter(|value| js_truthy(Some(value)) && *value != &json!("none"))
        {
            increment_known_count(&mut counts, issue, GENERATED_REGISTRY_ISSUE_TYPES);
        }
    }
    Value::Object(counts)
}

pub fn build_mapping_issue_counts(rows: &[Value]) -> Value {
    build_issue_counts(rows, &[])
}

