fn audit_first_non_nullish(values: &[Option<&Value>], fallback: &str) -> String {
    values
        .iter()
        .filter_map(|value| *value)
        .find(|value| !value.is_null())
        .map(js_string)
        .unwrap_or_else(|| fallback.to_string())
}

fn audit_object_entry_lines(value: Option<&Value>) -> Vec<String> {
    value
        .and_then(Value::as_object)
        .map(|entries| {
            entries
                .iter()
                .map(|(key, count)| format!("- {key}: {}", js_string(count)))
                .collect()
        })
        .unwrap_or_default()
}

pub fn append_source_backed_coverage_markdown_gate_sections(
    report: &Value,
    lines: &mut Vec<String>,
) {
    let summary = report.get("summary").unwrap_or(&Value::Null);
    if summary
        .get("highRiskAuditCategories")
        .is_some_and(|categories| js_truthy(Some(categories)))
    {
        lines.extend(["## Blocking Gate Scope".to_string(), String::new()]);
        if let Some(categories) = summary
            .get("highRiskAuditCategories")
            .and_then(Value::as_array)
        {
            lines.extend(
                categories
                    .iter()
                    .map(|category| format!("- {}", audit_template_value(Some(category)))),
            );
        }
        lines.push(String::new());
    }
    if summary
        .get("issueCountsBySuspectedLayer")
        .is_some_and(|counts| js_truthy(Some(counts)))
    {
        lines.extend(["## Issues By Suspected Layer".to_string(), String::new()]);
        lines.extend(audit_object_entry_lines(
            summary.get("issueCountsBySuspectedLayer"),
        ));
        lines.push(String::new());
    }
    if summary
        .get("issueCountsByActionableClass")
        .is_some_and(|counts| js_truthy(Some(counts)))
    {
        lines.extend(["## Issues By Actionable Class".to_string(), String::new()]);
        lines.extend(audit_object_entry_lines(
            summary.get("issueCountsByActionableClass"),
        ));
        lines.push(String::new());
    }

    let actionable_rows = collect_actionable_issue_rows(report);
    if !actionable_rows.is_empty() {
        lines.extend([
            "## Blocking Gate Issue Triage".to_string(),
            String::new(),
            "| Layer | Class | Owner | Major | Source role | Source URL | Evidence | Generated row | Runtime visibility | Recommended fix |".to_string(),
            "| --- | --- | --- | --- | --- | --- | --- | --- | --- | --- |".to_string(),
        ]);
        for row in actionable_rows.iter().take(80) {
            let plan_context = row.get("planContext");
            let row_type = get_row_issue_type(row);
            let class = audit_first_non_nullish(
                &[
                    row.get("actionableIssueClass"),
                    row.get("issueTypeNormalized"),
                    (!row_type.is_null()).then_some(&row_type),
                ],
                "unknown",
            );
            let cells = [
                audit_first_non_nullish(&[row.get("suspectedLayer")], "audit expectation"),
                class,
                audit_first_non_nullish(
                    &[
                        plan_context.and_then(|context| context.get("ownerId")),
                        row.get("ownerId"),
                    ],
                    "unknown",
                ),
                audit_first_non_nullish(
                    &[
                        plan_context.and_then(|context| context.get("majorTitle")),
                        row.get("majorTitle"),
                        row.get("planId"),
                        row.get("majorId"),
                    ],
                    "unknown",
                ),
                audit_first_non_nullish(&[row.get("auditSourceRole")], "none"),
                audit_first_non_nullish(&[row.get("auditSourceUrl")], "none"),
                audit_first_non_nullish(&[row.get("parsedSourceEvidence")], "not reported"),
                audit_first_non_nullish(&[row.get("generatedRowId")], "none"),
                audit_first_non_nullish(&[row.get("runtimeVisibilityStatus")], "not reported"),
                audit_first_non_nullish(
                    &[row.get("recommendedFixPath")],
                    "source/scripts/planner/audit-transfer-planner-source-backed-coverage.cjs",
                ),
            ];
            lines.push(format!(
                "| {} |",
                cells
                    .iter()
                    .map(|cell| escape_audit_markdown(Some(&json!(cell))))
                    .collect::<Vec<_>>()
                    .join(" | ")
            ));
        }
        if actionable_rows.len() > 80 {
            lines.push(format!(
                "| ... | ... | ... | ... | ... | ... | ... | ... | ... | {} additional blocking gate issues omitted from markdown sample. |",
                actionable_rows.len() - 80
            ));
        }
        lines.push(String::new());
    }

    if summary
        .get("sourceScopeIssueCountsByType")
        .is_some_and(|counts| js_truthy(Some(counts)))
    {
        lines.extend(["## Source Scope Issue Counts".to_string(), String::new()]);
        lines.extend(audit_object_entry_lines(
            summary.get("sourceScopeIssueCountsByType"),
        ));
        lines.push(String::new());
    }

    let failed_checks = rows(report, "regressionChecks")
        .iter()
        .filter(|check| check.get("status").and_then(Value::as_str) == Some("failed"))
        .collect::<Vec<_>>();
    if !failed_checks.is_empty() {
        lines.extend(["## Failed Regression Checks".to_string(), String::new()]);
        for check in failed_checks {
            lines.extend([
                format!("### {}", audit_template_value(check.get("label"))),
                String::new(),
                format!("- Id: {}", audit_template_value(check.get("id"))),
                format!(
                    "- Issue type: {}",
                    audit_first_non_nullish(&[check.get("issueType")], "none")
                ),
            ]);
            if let Some(details) = check.get("details").and_then(Value::as_array) {
                lines.extend(
                    details
                        .iter()
                        .map(|detail| format!("- Detail: {}", audit_template_value(Some(detail)))),
                );
            }
            lines.push(String::new());
        }
    }
}

fn truthy_audit_field_rows(rows: &[Value], field: &str) -> Vec<Value> {
    rows.iter()
        .filter(|row| row.get(field).is_some_and(|value| js_truthy(Some(value))))
        .cloned()
        .collect()
}

fn issue_audit_rows(report: &Value, collection: &str) -> Vec<Value> {
    issue_field_rows(rows(report, collection))
        .into_iter()
        .cloned()
        .collect()
}

