pub fn build_computer_science_prerequisite_filter_parser_extraction_regression_row(
    input: &Value,
) -> Option<Value> {
    const OWNER_ID: &str = "uw-seattle-computer-science";
    if !include_parser_extraction_target(
        input.get("targetPlanId").and_then(Value::as_str),
        OWNER_ID,
    ) {
        return None;
    }
    let fixture = input
        .get("computerScienceParserFixture")
        .unwrap_or(&Value::Null);
    let prerequisite_rows = rows(fixture, "sourceSectionFilterAuditRows")
        .iter()
        .map(|row| {
            let mut normalized_row = row.clone();
            if let Some(object) = normalized_row.as_object_mut() {
                object.insert(
                    "courseCodesExtracted".to_string(),
                    json!(normalized_course_list(row, "courseCodesExtracted")),
                );
                object.insert(
                    "issue".to_string(),
                    parser_prerequisite_filter_issue(fixture, row),
                );
            }
            normalized_row
        })
        .collect::<Vec<_>>();
    let blocked_course_codes = [
        "MATH 208", "PHYS 122", "CSE 403", "CSE 414", "CSE 421", "CSE 442",
    ];
    let blocked_rows = prerequisite_rows
        .iter()
        .filter(|row| {
            row.get("schedulable") == Some(&Value::Bool(false))
                && normalized_course_list(row, "courseCodesExtracted")
                    .iter()
                    .any(|code| blocked_course_codes.contains(&code.as_str()))
        })
        .collect::<Vec<_>>();
    let issue_rows = blocked_rows
        .iter()
        .filter(|row| row.get("issue").and_then(Value::as_str) != Some("none"))
        .copied()
        .collect::<Vec<_>>();
    let required_atoms = rows(fixture, "parsedRequirementAtomCandidates")
        .iter()
        .filter_map(|candidate| candidate.get("uwCourseCode"))
        .map(js_string)
        .collect::<Vec<_>>();
    let actual_shape = if blocked_rows.is_empty() {
        format!(
            "no blocked prerequisite/course-list audit rows found; requiredAtoms={}",
            if required_atoms.is_empty() {
                "none".to_string()
            } else {
                required_atoms.join(", ")
            }
        )
    } else {
        let blocked_summaries = blocked_rows
            .iter()
            .map(|row| {
                format!(
                    "{}:{}:{}",
                    row.get("detectedSectionRole")
                        .map(js_string)
                        .unwrap_or_else(|| "undefined".to_string()),
                    if normalized_course_list(row, "courseCodesExtracted").is_empty() {
                        "none".to_string()
                    } else {
                        normalized_course_list(row, "courseCodesExtracted").join(", ")
                    },
                    row.get("issue")
                        .map(js_string)
                        .unwrap_or_else(|| "undefined".to_string())
                )
            })
            .collect::<Vec<_>>();
        format!(
            "{}; requiredAtoms={}",
            blocked_summaries.join(" | "),
            if required_atoms.is_empty() {
                "none".to_string()
            } else {
                required_atoms.join(", ")
            }
        )
    };
    let passed = !blocked_rows.is_empty()
        && issue_rows.is_empty()
        && required_atoms.len() == 1
        && required_atoms[0] == "CSE 123";
    let issue = issue_rows
        .first()
        .and_then(|row| row.get("issue"))
        .cloned()
        .unwrap_or_else(|| json!("prerequisite-table-emitted-requirement"));
    let source_url = input
        .get("primarySourcesByOwner")
        .and_then(|sources| sources.get(OWNER_ID))
        .and_then(|source| {
            if source.is_object() {
                source.get("url")
            } else {
                Some(source)
            }
        });
    let mut row_input = json!({
        "ownerId": OWNER_ID,
        "protectedPattern": "Computer Science broad prerequisite/course-list sections are non-schedulable",
        "expectedParserShape": "upper-division prerequisite and course-list rows have Schedulable=no and Issue=none",
        "actualParserShape": actual_shape,
        "passed": passed,
        "issue": issue,
        "suggestedFileFunction": "source/scripts/planner/parse-transfer-planner-requirement-sources.cjs::classifySourceSectionRoleForLine"
    });
    if let (Some(object), Some(source_url)) = (row_input.as_object_mut(), source_url) {
        object.insert("sourceUrl".to_string(), source_url.clone());
    }
    Some(build_parser_extraction_regression_row(&row_input))
}

pub fn build_computer_engineering_parser_extraction_regression_rows(input: &Value) -> Vec<Value> {
    const OWNER_ID: &str = "uw-seattle-computer-engineering";
    if !include_parser_extraction_target(
        input.get("targetPlanId").and_then(Value::as_str),
        OWNER_ID,
    ) {
        return Vec::new();
    }
    let fixture = input
        .get("computerEngineeringParserFixture")
        .unwrap_or(&Value::Null);
    let groups = rows(fixture, "parsedRequirementGroups");
    let natural_science_group = groups.iter().find(|group| {
        group.get("approvedListKey").and_then(Value::as_str)
            == Some("computer-engineering-natural-science")
    });
    let math_science_group = groups.iter().find(|group| {
        group.get("approvedListKey").and_then(Value::as_str)
            == Some("computer-engineering-math-science")
    });
    let primary_source = input
        .get("primarySourcesByOwner")
        .and_then(|sources| sources.get(OWNER_ID))
        .and_then(|source| {
            if source.is_object() {
                source.get("url")
            } else {
                Some(source)
            }
        });
    let approved_list_block = input
        .get("parsedBlocksByOwner")
        .and_then(|blocks| blocks.get(OWNER_ID))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .find(|block| {
            block.get("sourceRole").and_then(Value::as_str) == Some("approved-course-list")
        });
    let required_surface_count = approved_list_block.map_or(0, |block| {
        rows(block, "parsedRequirementAtomCandidates").len()
            + rows(block, "parsedRequirementGroups").len()
    });
    let approved_code_count = approved_list_block
        .map(|block| rows(block, "approvedFilterUwCourseCodes").len())
        .unwrap_or(0);
    let support_code_count = approved_list_block
        .map(|block| rows(block, "supportOnlyUwCourseCodes").len())
        .unwrap_or(0);
    let natural_science_passed = natural_science_group.is_some_and(|group| {
        group.get("requirementType").and_then(Value::as_str) == Some("choose_credits")
            && group.get("minCredits") == Some(&json!(10))
            && group.get("maxCredits") == Some(&json!(10))
    });
    let math_science_passed = math_science_group.is_some_and(|group| {
        group.get("requirementType").and_then(Value::as_str) == Some("choose_credits")
            && group.get("minCredits") == Some(&json!(3))
            && group.get("maxCredits") == Some(&json!(6))
    });
    let mut output = Vec::new();
    for (protected_pattern, expected_shape, group, passed) in [
        (
            "Computer Engineering 10-credit approved Natural Science bucket",
            "choose_credits bucket with minCredits=10 maxCredits=10 and CE approved filter",
            natural_science_group,
            natural_science_passed,
        ),
        (
            "Computer Engineering 3-6 credit approved Math/Science bucket",
            "choose_credits bucket with minCredits=3 maxCredits=6 and CE approved filter",
            math_science_group,
            math_science_passed,
        ),
    ] {
        output.push(build_parser_extraction_regression_row(&json!({
            "ownerId": OWNER_ID,
            "protectedPattern": protected_pattern,
            "sourceUrl": primary_source,
            "expectedParserShape": expected_shape,
            "actualParserShape": group_shape_summary(group),
            "passed": passed,
            "issue": "missing-credit-bucket",
            "suggestedFileFunction": "source/scripts/planner/parse-transfer-planner-requirement-sources.cjs::buildCreditBucketRequirementGroups"
        })));
    }
    let mut approved_list_input = json!({
        "ownerId": OWNER_ID,
        "protectedPattern": "Computer Engineering approved science list remains support metadata",
        "expectedParserShape": "approved-course-list source emits approved/support codes with no required rows or groups",
        "actualParserShape": if approved_list_block.is_some() {
            format!(
                "approved={approved_code_count}; support={support_code_count}; requiredSurface={required_surface_count}"
            )
        } else {
            "missing approved-course-list block".to_string()
        },
        "passed": approved_list_block.is_some() && approved_code_count > 0 && required_surface_count == 0,
        "issue": "support-source-emitted-required-row",
        "suggestedFileFunction": "source/scripts/planner/parse-transfer-planner-requirement-sources.cjs::buildManifestParseSuccess"
    });
    if let (Some(object), Some(source_url)) = (
        approved_list_input.as_object_mut(),
        approved_list_block.and_then(|block| block.get("sourceUrl")),
    ) {
        object.insert("sourceUrl".to_string(), source_url.clone());
    }
    output.push(build_parser_extraction_regression_row(&approved_list_input));
    output
}

pub fn build_aeronautics_mixed_category_parser_extraction_regression_row(
    input: &Value,
) -> Option<Value> {
    const OWNER_ID: &str = "uw-seattle-aeronautics-astronautics";
    if !include_parser_extraction_target(
        input.get("targetPlanId").and_then(Value::as_str),
        OWNER_ID,
    ) {
        return None;
    }
    let blocks = input
        .get("parsedBlocksByOwner")
        .and_then(|blocks| blocks.get(OWNER_ID))
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or_default();
    let matching_entry = blocks.iter().find_map(|block| {
        block
            .get("parsedRequirementGroups")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .find(|group| {
                rows(group, "options").iter().any(|option| {
                    option
                        .get("categoryOption")
                        .and_then(|category| category.get("category"))
                        .and_then(Value::as_str)
                        == Some("NSC")
                })
            })
            .map(|group| (block, group))
    });
    let mixed_group = matching_entry.map(|(_, group)| group);
    let option_courses = mixed_group
        .into_iter()
        .flat_map(|group| rows(group, "options"))
        .flat_map(|option| rows(option, "uwCourses"))
        .map(|code| normalize_audit_course_code(Some(code)))
        .filter(|code| !code.is_empty())
        .collect::<HashSet<_>>();
    let category_option = mixed_group
        .into_iter()
        .flat_map(|group| rows(group, "options"))
        .filter_map(|option| option.get("categoryOption"))
        .find(|category| category.get("category").and_then(Value::as_str) == Some("NSC"));
    let passed = mixed_group.is_some_and(|group| {
        group.get("requirementType").and_then(Value::as_str) == Some("choose_one")
    }) && option_courses.contains("CSE 160")
        && option_courses.contains("ME 123")
        && category_option.is_some_and(|category| rows(category, "uwCourses").is_empty());
    let issue = if category_option.is_some() {
        "fake-course-invented"
    } else {
        "missing-category-option"
    };
    let source_url = matching_entry
        .and_then(|(block, _)| block.get("sourceUrl"))
        .cloned();
    let mut row_input = json!({
        "ownerId": OWNER_ID,
        "protectedPattern": "A&A mixed CSE 160 / ME 123 / NSc category option",
        "expectedParserShape": "choose_one group with CSE 160, ME 123, and non-concrete NSc category option",
        "actualParserShape": group_shape_summary(mixed_group),
        "passed": passed,
        "issue": issue,
        "suggestedFileFunction": "source/scripts/planner/parse-transfer-planner-requirement-sources.cjs::buildCategoryCreditRequirementGroups"
    });
    if let (Some(object), Some(source_url)) = (row_input.as_object_mut(), source_url) {
        object.insert("sourceUrl".to_string(), source_url);
    }
    Some(build_parser_extraction_regression_row(&row_input))
}

pub fn build_protected_sequence_parser_extraction_regression_rows(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let mut output = Vec::new();
    for owner_id in PROTECTED_SEQUENCE_EXPECTATION_OWNER_IDS.iter().copied() {
        if !include_parser_extraction_target(
            input.get("targetPlanId").and_then(Value::as_str),
            owner_id,
        ) {
            continue;
        }
        let expected_paths: Vec<Vec<&str>> = if owner_id == "uw-seattle-biology" {
            vec![
                vec!["PHYS 114", "PHYS 115"],
                vec!["PHYS 121", "PHYS 122"],
                vec!["PHYS 141", "PHYS 142"],
            ]
        } else {
            vec![
                vec!["PHYS 121", "PHYS 122", "PHYS 123"],
                vec!["PHYS 114", "PHYS 115", "PHYS 116"],
            ]
        };
        let blocks = input
            .get("parsedBlocksByOwner")
            .and_then(|blocks| blocks.get(owner_id))
            .and_then(Value::as_array)
            .map(Vec::as_slice)
            .unwrap_or_default();
        let (applies, reason) =
            parser_sequence_expectation_for_blocks(blocks, &expected_paths, course_parser);
        let matching_entry = blocks.iter().find_map(|block| {
            block
                .get("parsedRequirementGroups")
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .find(|group| parser_sequence_group_matches(group, &expected_paths))
                .map(|group| (block, group))
        });
        let sequence_group = matching_entry.map(|(_, group)| group);
        let flattened = blocks
            .iter()
            .flat_map(|block| {
                block
                    .get("parserSequenceChoiceAuditRows")
                    .and_then(Value::as_array)
                    .into_iter()
                    .flatten()
            })
            .any(|row| {
                row.get("emittedIndependentRequiredRows") == Some(&Value::Bool(true))
                    || row.get("issue").and_then(Value::as_str) == Some("flattened-sequence-paths")
            });
        let primary_source_url = input
            .get("primarySourcesByOwner")
            .and_then(|sources| sources.get(owner_id))
            .and_then(|source| {
                if source.is_object() {
                    source.get("url")
                } else {
                    Some(source)
                }
            });
        let source_url = matching_entry
            .and_then(|(block, _)| block.get("sourceUrl"))
            .or(primary_source_url)
            .cloned()
            .unwrap_or_else(|| json!("n/a"));
        let expected_shape = if !applies {
            "not applicable when the scoped official source explicitly says Physics is not required"
                .to_string()
        } else if owner_id == "uw-seattle-biology" {
            "sequence_choice paths PHYS 114/115, PHYS 121/122, PHYS 141/142".to_string()
        } else {
            "sequence_choice paths PHYS 121/122/123 and PHYS 114/115/116".to_string()
        };
        let actual_shape = if !applies {
            reason
        } else {
            group_shape_summary(sequence_group)
        };
        let passed = !applies || (sequence_group.is_some() && !flattened);
        let issue = if sequence_group.is_some() {
            "flattened-sequence-paths"
        } else {
            "missed-sequence-choice"
        };
        output.push(build_parser_extraction_regression_row(&json!({
            "ownerId": owner_id,
            "protectedPattern": format!(
                "{} physics alternatives parse as sequence_choice",
                owner_id.strip_prefix("uw-seattle-").unwrap_or(owner_id)
            ),
            "sourceUrl": source_url,
            "expectedParserShape": expected_shape,
            "actualParserShape": actual_shape,
            "passed": passed,
            "issue": issue,
            "suggestedFileFunction": if !applies {
                "source/scripts/planner/audit-transfer-planner-source-backed-coverage.cjs::buildParserExtractionRegressionRows"
            } else {
                "source/scripts/planner/parse-transfer-planner-requirement-sources.cjs::buildGenericSequenceChoiceRequirementGroups"
            }
        })));
    }
    output
}

pub fn filter_parser_extraction_regression_rows_for_target(
    rows: &[Value],

    target_plan_id: Option<&str>,
) -> Vec<Value> {
    rows.iter()
        .filter(|row| {
            let Some(owner_id) = row.get("ownerId") else {
                return target_plan_id.filter(|target| !target.is_empty()).is_none();
            };
            let owner_id = js_string(owner_id);
            let plan_id = owner_id
                .split_once(":pathway:")
                .map(|(plan_id, _)| plan_id)
                .unwrap_or(&owner_id);
            include_parser_extraction_target(target_plan_id, plan_id)
        })
        .cloned()
        .collect()
}

pub fn build_parser_extraction_regression_row(input: &Value) -> Value {
    let passed = input
        .get("passed")
        .is_some_and(|value| js_truthy(Some(value)));
    let issue = if passed {
        Some(json!("none"))
    } else {
        input.get("issue").cloned()
    };
    let suggested_file_function = input
        .get("suggestedFileFunction")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| {
            let issue_value = issue.clone().unwrap_or(Value::Null);
            json!(format!(
                "{}::buildParsedRequirementGroups",
                get_suggested_file_for_issue(&issue_value)
            ))
        });
    let source_url = input
        .get("sourceUrl")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!("n/a"));
    let owner_id = input
        .get("ownerId")
        .map(js_string)
        .unwrap_or_else(|| "undefined".to_string());
    let protected_pattern = input
        .get("protectedPattern")
        .map(js_string)
        .unwrap_or_else(|| "undefined".to_string());
    let expected_shape = input
        .get("expectedParserShape")
        .map(js_string)
        .unwrap_or_else(|| "undefined".to_string());
    let actual_shape = input
        .get("actualParserShape")
        .map(js_string)
        .unwrap_or_else(|| "undefined".to_string());
    let source_url_text = js_string(&source_url);
    let issue_text = issue
        .as_ref()
        .map(js_string)
        .unwrap_or_else(|| "undefined".to_string());
    let passed_text = if input
        .get("passed")
        .is_some_and(|value| js_truthy(Some(value)))
    {
        "yes"
    } else {
        "no"
    };
    let suggested_file_function_text = js_string(&suggested_file_function);
    let debug_text = format!(
        "[parser extraction regression report] Owner id: {owner_id} Protected pattern: {protected_pattern} Source URL: {source_url_text} Expected parser shape: {expected_shape} Actual parser shape: {actual_shape} Passed: {passed_text} Issue: {issue_text} Suggested file/function: {suggested_file_function_text}"
    );
    let mut row = Map::new();
    for field in [
        "ownerId",
        "protectedPattern",
        "expectedParserShape",
        "actualParserShape",
        "passed",
    ] {
        if let Some(value) = input.get(field) {
            row.insert(field.to_string(), value.clone());
        }
    }
    row.insert("sourceUrl".to_string(), source_url);
    if let Some(issue) = issue {
        row.insert("issue".to_string(), issue);
    }
    row.insert("suggestedFileFunction".to_string(), suggested_file_function);
    row.insert("copyOnlyDebugText".to_string(), json!(debug_text));
    Value::Object(row)
}

pub fn build_requirement_shape_audit_row(input: &Value) -> Value {
    let group = input.get("group");
    let item = input.get("item");
    let block = input.get("block");
    let schedulable = input.get("schedulable").and_then(Value::as_bool) == Some(true);
    let issue = input
        .get("issue")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| requirement_shape_audit_issue(group, item, block, schedulable));
    let requirement_id = first_non_nullish([
        input.get("requirementId"),
        group.and_then(|group| group.get("id")),
        item.and_then(|item| item.get("id")),
        block.and_then(|block| block.get("id")),
    ])
    .cloned()
    .unwrap_or_else(|| json!("unknown-requirement"));
    let requirement_title = first_non_nullish([
        input.get("requirementTitle"),
        group.and_then(|group| group.get("label")),
        item.and_then(|item| item.get("title")),
        block.and_then(|block| block.get("sourceLabel")),
        block.and_then(|block| block.get("sourceUrl")),
    ])
    .cloned()
    .unwrap_or_else(|| json!("unknown requirement"));
    let source_role = first_non_nullish([
        input.get("sourceRole"),
        group.and_then(|group| group.get("sourceRole")),
        item.and_then(|item| item.get("sourceRole")),
        block.and_then(|block| block.get("sourceRole")),
    ])
    .cloned()
    .unwrap_or(Value::Null);
    let current_shape = input
        .get("currentShape")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| requirement_audit_current_shape(group, item, block));
    let expected_shape = input
        .get("expectedShape")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| requirement_audit_expected_shape(group, item, block));
    let copy_text = format!(
        "[requirement shape audit] Owner id: {} Requirement id: {} Requirement title: {} Source role: {} Current shape: {} Expected shape: {} Schedulable: {} Issue: {}",
        field_string(input, "ownerId"),
        js_string(&requirement_id),
        js_string(&requirement_title),
        if source_role.is_null() {
            "none".to_string()
        } else {
            js_string(&source_role)
        },
        js_string(&current_shape),
        js_string(&expected_shape),
        if schedulable { "yes" } else { "no" },
        js_string(&issue),
    );
    let mut row = Map::new();
    if let Some(owner_id) = input.get("ownerId") {
        row.insert("ownerId".to_string(), owner_id.clone());
    }
    row.insert("requirementId".to_string(), requirement_id);
    row.insert("requirementTitle".to_string(), requirement_title);
    row.insert("sourceRole".to_string(), source_role);
    row.insert("currentShape".to_string(), current_shape);
    row.insert("expectedShape".to_string(), expected_shape);
    row.insert("schedulable".to_string(), json!(schedulable));
    row.insert("issue".to_string(), issue);
    row.insert("copyOnlyDebugText".to_string(), json!(copy_text));
    Value::Object(row)
}

pub fn build_requirement_shape_rows_for_plan(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(&null);
    let plan = input.get("plan").unwrap_or(&null);
    if !js_truthy(Some(plan)) {
        return Vec::new();
    }
    let checklist_items = runtime_checklist_items(plan);
    let mut output = Vec::new();
    for group in collect_generated_requirement_groups_by_id(plan) {
        let group_id = group.get("id").unwrap_or(&null);
        let schedulable = checklist_items.iter().any(|item| {
            item.get("requirementGroup")
                .and_then(|item_group| item_group.get("id"))
                .is_some_and(|item_group_id| js_strict_equal_audit_values(item_group_id, group_id))
                && item.get("canCreateScheduleRow").and_then(Value::as_bool) != Some(false)
                && !checklist_item_grc_course_codes(item, course_parser).is_empty()
        });
        let mut row_input = json!({"group": group, "schedulable": schedulable});
        if let Some(owner_id) = owner.get("ownerId") {
            row_input
                .as_object_mut()
                .expect("shape row input is an object")
                .insert("ownerId".to_string(), owner_id.clone());
        }
        output.push(build_requirement_shape_audit_row(&row_input));
    }
    for item in checklist_items {
        if item
            .get("requirementGroup")
            .is_some_and(|group| js_truthy(Some(group)))
        {
            continue;
        }
        let schedulable = item.get("canCreateScheduleRow").and_then(Value::as_bool) != Some(false)
            && !checklist_item_grc_course_codes(item, course_parser).is_empty();
        let mut row_input = json!({"item": item, "schedulable": schedulable});
        if let Some(owner_id) = owner.get("ownerId") {
            row_input
                .as_object_mut()
                .expect("shape row input is an object")
                .insert("ownerId".to_string(), owner_id.clone());
        }
        output.push(build_requirement_shape_audit_row(&row_input));
    }
    output
}

pub fn build_requirement_shape_rows_for_source_blocks(input: &Value) -> Vec<Value> {
    let owner = input.get("owner");
    let mut output = Vec::new();
    for block in rows(input, "parsedBlocks") {
        let can_create_schedule_rows =
            block.get("canCreateScheduleRows").and_then(Value::as_bool) == Some(true);
        let parsed_groups = rows(block, "parsedRequirementGroups");
        let parsed_atoms = rows(block, "parsedRequirementAtomCandidates");
        let has_parsed_schedulable_surface =
            can_create_schedule_rows && (!parsed_groups.is_empty() || !parsed_atoms.is_empty());
        let source_role = nullish_field_string(block, "sourceRole", "");
        let elective_codes = rows(block, "electiveListUwCourseCodes");
        let approved_codes = rows(block, "approvedFilterUwCourseCodes");
        let support_codes = rows(block, "supportOnlyUwCourseCodes");
        let has_list_codes = !approved_codes.is_empty() || !elective_codes.is_empty();
        let support_like = block.get("supportOnly").and_then(Value::as_bool) == Some(true)
            || block.get("canCreateScheduleRows").and_then(Value::as_bool) == Some(false)
            || matches!(
                source_role.as_str(),
                "approved-course-list" | "elective-list" | "support-source"
            );
        let selected = support_like
            || (!support_codes.is_empty() && !has_parsed_schedulable_surface)
            || (has_list_codes && (!has_parsed_schedulable_surface || support_like));
        if !selected {
            continue;
        }
        let schedulable =
            can_create_schedule_rows && (!parsed_groups.is_empty() || !parsed_atoms.is_empty());
        let mut row_input = json!({"block": block, "schedulable": schedulable});
        if let Some(owner_id) = owner.and_then(|owner| owner.get("ownerId")) {
            row_input
                .as_object_mut()
                .expect("shape row input is an object")
                .insert("ownerId".to_string(), owner_id.clone());
        }
        output.push(build_requirement_shape_audit_row(&row_input));
    }
    output
}

pub fn build_requirement_shape_audit_rows_for_owner(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(input);
    let mut output = Vec::new();
    for (plan_key, artifact) in [
        (
            "sourcePlan",
            "source/constants/transfer-planner-source/generated-major-plans.ts",
        ),
        (
            "runtimePlan",
            "source/constants/transfer-planner-source/student-runtime.generated.ts",
        ),
    ] {
        let plan = input.get(plan_key).unwrap_or(&null);
        let plan_input = json!({"owner": owner, "plan": plan, "generatedArtifact": artifact});
        output.extend(build_requirement_shape_rows_for_plan(
            &plan_input,
            course_parser,
        ));
    }
    let mut parsed_blocks = rows(input, "sourceParsedBlocks").to_vec();
    parsed_blocks.extend_from_slice(rows(input, "runtimeParsedBlocks"));
    output.extend(build_requirement_shape_rows_for_source_blocks(&json!({
        "owner": owner,
        "parsedBlocks": parsed_blocks
    })));
    output
}

pub fn build_requirement_shape_audit_rows_for_owners(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let mut output = Vec::new();
    for owner in rows(input, "owners") {
        let owner_key = owner
            .get("ownerId")
            .map(js_string)
            .unwrap_or_else(|| "undefined".to_string());
        let owner_input = json!({
            "owner": owner,
            "sourcePlan": input.get("sourcePlansByOwner").and_then(|plans| plans.get(owner_key.as_str())),
            "runtimePlan": input.get("runtimePlansByOwner").and_then(|plans| plans.get(owner_key.as_str())),
            "sourceParsedBlocks": input.get("sourceParsedBlocksByOwner").and_then(|blocks| blocks.get(owner_key.as_str())),
            "runtimeParsedBlocks": input.get("runtimeParsedBlocksByOwner").and_then(|blocks| blocks.get(owner_key.as_str()))
        });
        output.extend(build_requirement_shape_audit_rows_for_owner(
            &owner_input,
            course_parser,
        ));
    }
    output
}

fn credit_category_audit_category_options(group: &Value) -> Vec<(&Value, Option<&Value>)> {
    group
        .get("options")
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .filter_map(|option| {
            let category_option = option
                .get("categoryOption")
                .filter(|value| js_truthy(Some(value)));
            (option.get("optionKind").and_then(Value::as_str) == Some("category-option")
                || category_option.is_some())
            .then_some((option, category_option))
        })
        .collect()
}

fn credit_category_audit_concrete_options(group: &Value) -> Vec<String> {
    unique_sorted_source_values(
        group
            .get("options")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .filter(|option| {
                option.get("optionKind").and_then(Value::as_str) != Some("category-option")
                    && !option
                        .get("categoryOption")
                        .is_some_and(|value| js_truthy(Some(value)))
            })
            .flat_map(|option| {
                [
                    "uwCourses",
                    "equivalentUwCourseCodes",
                    "displayCourseCodes",
                    "grcMatches",
                ]
                .into_iter()
                .flat_map(|field| {
                    option
                        .get(field)
                        .and_then(Value::as_array)
                        .into_iter()
                        .flatten()
                        .cloned()
                        .map(Some)
                })
            }),
    )
}

fn credit_category_shape_issue(
    owner: &Value,
    group: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> &'static str {
    let null = Value::Null;
    let raw_text = parser_group_raw_text(group);
    let is_credit_bucket = group.get("requirementType").and_then(Value::as_str)
        == Some("choose_credits")
        || group.get("requirementShape").and_then(Value::as_str) == Some("credit-bucket");
    if is_credit_bucket
        && (group.get("requirementType").and_then(Value::as_str) != Some("choose_credits")
            || group.get("requirementShape").and_then(Value::as_str) != Some("credit-bucket")
            || [
                "requiredCount",
                "selectionCount",
                "minCourses",
                "maxCourses",
            ]
            .iter()
            .any(|field| group.get(*field).is_some_and(|value| !value.is_null()))
            || group.get("minCredits").is_none_or(Value::is_null)
            || group.get("satisfactionMode").and_then(Value::as_str) != Some("credit-based"))
    {
        return "credit-bucket-as-count";
    }
    let category_options = credit_category_audit_category_options(group);
    if group_looks_like_category_option_requirement(&raw_text, group, owner, course_parser)
        && category_options.is_empty()
    {
        return "missing-category-option";
    }
    if category_options
        .iter()
        .any(|(option, _)| option_has_concrete_courses(option, course_parser))
    {
        return "fake-category-course";
    }
    if category_options.iter().any(|(_, category_option)| {
        category_option_looks_generic_for_program_specific(
            owner,
            &raw_text,
            group,
            category_option.unwrap_or(&null),
        )
    }) {
        return "generic-category-used-for-program-specific";
    }
    "none"
}

fn build_credit_category_shape_audit_row(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Value {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(&null);
    let group = input.get("group").unwrap_or(&null);
    let category_options = credit_category_audit_category_options(group);
    let concrete_options = credit_category_audit_concrete_options(group);
    let category_option_text = if category_options.is_empty() {
        "none".to_string()
    } else {
        category_options
            .iter()
            .map(|(option, category_option)| {
                let category_option = category_option.unwrap_or(&null);
                let category = first_non_nullish([
                    category_option.get("sourceCategoryCode"),
                    category_option.get("category"),
                    option.get("sourceCategory"),
                    option.get("category"),
                ])
                .map(js_string)
                .unwrap_or_else(|| "unknown".to_string());
                let min_credits = first_non_nullish([
                    category_option.get("creditMin"),
                    category_option.get("credits"),
                    option.get("creditMin"),
                    option.get("credits"),
                ]);
                let max_credits = first_non_nullish([
                    category_option.get("creditMax"),
                    option.get("creditMax"),
                    option.get("maxCredits"),
                ]);
                format!(
                    "{category} ({})",
                    format_audit_credit_range(min_credits, max_credits)
                )
            })
            .collect::<Vec<_>>()
            .join(", ")
    };
    let issue = credit_category_shape_issue(owner, group, course_parser);
    let requirement_shape = [
        group
            .get("requirementType")
            .filter(|value| !value.is_null())
            .map(js_string)
            .unwrap_or_else(|| "unknown".to_string()),
        group
            .get("requirementShape")
            .filter(|value| !value.is_null())
            .map(js_string)
            .unwrap_or_else(|| "none".to_string()),
        group
            .get("satisfactionMode")
            .filter(|value| !value.is_null())
            .map(js_string)
            .unwrap_or_else(|| "none".to_string()),
    ]
    .join(" / ");
    let program_specific_filter = group_program_specific_filter(group);
    let concrete_options_text = if concrete_options.is_empty() {
        "none".to_string()
    } else {
        concrete_options.join(", ")
    };
    let min_credits = group
        .get("minCredits")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let max_credits = group
        .get("maxCredits")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let owner_id_text = property_string(owner.get("ownerId"));
    let requirement_id = group
        .get("id")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!("unknown-requirement"));
    let requirement_title = group
        .get("label")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!("unknown requirement"));
    let artifact = input.get("generatedArtifact").cloned();
    let debug_text = format!(
        "[credit/category shape audit] Owner id: {owner_id_text} Requirement title: {} Requirement shape: {} Min credits: {} Max credits: {} Category option: {} Program-specific filter: {} Concrete options: {} Issue: {}",
        js_string(&requirement_title),
        requirement_shape,
        if min_credits.is_null() {
            "none".to_string()
        } else {
            js_string(&min_credits)
        },
        if max_credits.is_null() {
            "none".to_string()
        } else {
            js_string(&max_credits)
        },
        category_option_text,
        js_string(&program_specific_filter),
        concrete_options_text,
        issue
    );
    let mut row = Map::new();
    if let Some(owner_id) = owner.get("ownerId") {
        row.insert("ownerId".to_string(), owner_id.clone());
    }
    if let Some(artifact) = artifact {
        row.insert("generatedArtifact".to_string(), artifact);
    }
    row.insert("requirementId".to_string(), requirement_id);
    row.insert("requirementTitle".to_string(), requirement_title);
    row.insert("requirementShape".to_string(), json!(requirement_shape));
    row.insert("minCredits".to_string(), min_credits);
    row.insert("maxCredits".to_string(), max_credits);
    row.insert("categoryOption".to_string(), json!(category_option_text));
    row.insert("programSpecificFilter".to_string(), program_specific_filter);
    row.insert("concreteOptions".to_string(), json!(concrete_options_text));
    row.insert("issue".to_string(), json!(issue));
    row.insert("copyOnlyDebugText".to_string(), json!(debug_text));
    Value::Object(row)
}

pub fn build_credit_category_shape_rows_for_plan(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(&null);
    let plan = input.get("plan").unwrap_or(&null);
    if !js_truthy(Some(plan)) {
        return Vec::new();
    }
    collect_generated_requirement_groups_by_id(plan)
        .into_iter()
        .filter(|group| {
            let raw_text = parser_group_raw_text(group);
            group.get("requirementType").and_then(Value::as_str) == Some("choose_credits")
                || group.get("requirementShape").and_then(Value::as_str) == Some("credit-bucket")
                || !credit_category_audit_category_options(group).is_empty()
                || group_looks_like_credit_bucket(&raw_text, owner, group, course_parser)
                || group_looks_like_category_option_requirement(
                    &raw_text,
                    group,
                    owner,
                    course_parser,
                )
        })
        .map(|group| {
            let mut row_input = json!({"owner": owner, "group": group});
            if let Some(artifact) = input.get("generatedArtifact") {
                row_input
                    .as_object_mut()
                    .expect("credit/category input is an object")
                    .insert("generatedArtifact".to_string(), artifact.clone());
            }
            build_credit_category_shape_audit_row(&row_input, course_parser)
        })
        .collect()
}

pub fn build_credit_category_shape_audit_rows_for_owner(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(input);
    let mut output = Vec::new();
    for (plan_key, artifact) in [
        (
            "sourcePlan",
            "source/constants/transfer-planner-source/generated-major-plans.ts",
        ),
        (
            "runtimePlan",
            "source/constants/transfer-planner-source/student-runtime.generated.ts",
        ),
    ] {
        let plan_input = json!({
            "owner": owner,
            "plan": input.get(plan_key).unwrap_or(&null),
            "generatedArtifact": artifact
        });
        output.extend(build_credit_category_shape_rows_for_plan(
            &plan_input,
            course_parser,
        ));
    }
    output
}

pub fn build_credit_category_shape_audit_rows_for_owners(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let mut output = Vec::new();
    for owner in rows(input, "owners") {
        let owner_key = owner
            .get("ownerId")
            .map(js_string)
            .unwrap_or_else(|| "undefined".to_string());
        let owner_input = json!({
            "owner": owner,
            "sourcePlan": input.get("sourcePlansByOwner").and_then(|plans| plans.get(owner_key.as_str())),
            "runtimePlan": input.get("runtimePlansByOwner").and_then(|plans| plans.get(owner_key.as_str()))
        });
        output.extend(build_credit_category_shape_audit_rows_for_owner(
            &owner_input,
            course_parser,
        ));
    }
    output
}

fn normalize_audit_pathway_token(value: &str) -> String {
    let expanded = trim_js_whitespace(value)
        .to_lowercase()
        .replace('&', " and ");
    let mut token = String::new();
    let mut in_separator = false;
    for character in expanded.chars() {
        if character.is_ascii_alphanumeric() {
            token.push(character);
            in_separator = false;
        } else if !in_separator {
            token.push('-');
            in_separator = true;
        }
    }
    token.trim_matches('-').to_string()
}

fn normalize_audit_transfer_pathway_id(
    plan_id: Option<&Value>,
    pathway_id: Option<&Value>,
) -> Option<Value> {
    let pathway_id = pathway_id
        .filter(|value| !value.is_null())
        .map(js_string)
        .unwrap_or_default();
    let trimmed_pathway_id = trim_js_whitespace(&pathway_id).to_string();
    if trimmed_pathway_id.is_empty() {
        return None;
    }
    let plan_id = plan_id
        .filter(|value| !value.is_null())
        .map(js_string)
        .unwrap_or_default();
    let normalized_plan_id = trim_js_whitespace(&plan_id).to_string();
    let token = normalize_audit_pathway_token(&trimmed_pathway_id);
    let alias = match (normalized_plan_id.as_str(), token.as_str()) {
        ("uw-seattle-cinema-and-media-studies", "ba-option-family-cinema-studies") => {
            Some("cinema-studies")
        }
        ("uw-seattle-construction-management", "early-admission-option") => {
            Some("early-admission-pathway")
        }
        ("uw-seattle-construction-management", "freshmen-direct-option") => {
            Some("freshmen-direct-pathway")
        }
        ("uw-seattle-construction-management", "upper-division-admission-option") => {
            Some("upper-division-admission-pathway")
        }
        ("uw-seattle-economics", "strategy")
        | ("uw-seattle-economics", "bs-option-family-strategy") => {
            Some("bs-option-family:strategy")
        }
        ("uw-seattle-geography", "ba-option-family-in-geography-data-science")
        | ("uw-seattle-geography", "ba-option-family-in-geography-with-data-science")
        | ("uw-seattle-geography", "data-science-option")
        | (
            "uw-seattle-geography",
            "the-requirements-for-geography-majors-with-the-option-in-data-science-are-as-follows",
        ) => Some("geography-major-data-science-option"),
        ("uw-seattle-geography", "ccm-track")
        | ("uw-seattle-geography", "citizenship-and-migration-ccm-track")
        | ("uw-seattle-geography", "citizenship-and-migration-track") => {
            Some("cities-citizenship-and-migration-track")
        }
        ("uw-seattle-geography", "economy-and-sustainability-ees-track")
        | ("uw-seattle-geography", "economy-and-sustainability-track") => {
            Some("environment-economy-and-sustainability-track")
        }
        ("uw-seattle-geography", "health-and-development-track") => {
            Some("globalization-health-and-development-track")
        }
        ("uw-seattle-geography", "mapping-and-society-gms-track")
        | ("uw-seattle-geography", "mapping-and-society-track") => {
            Some("gis-mapping-and-society-track")
        }
        ("uw-seattle-biology", "bs-option-family-general") => {
            Some("bs-option-family:general-biology")
        }
        ("uw-seattle-biology", "bs-option-family-plant") => Some("bs-option-family:plant-biology"),
        ("uw-seattle-chemical-engineering", "nanoscience-and-molecular-engineering-nme-option")
        | ("uw-seattle-chemical-engineering", "nanoscience-and-molecular-engineering-option")
        | (
            "uw-seattle-materials-science-engineering",
            "nanoscience-and-molecular-engineering-nme-option",
        )
        | (
            "uw-seattle-materials-science-engineering",
            "nanoscience-and-molecular-engineering-option",
        ) => Some("nme-option"),
        ("uw-bothell-business-administration", "business-analytics-ai-concentration")
        | (
            "uw-bothell-business-administration",
            "business-analytics-and-artificial-intelligence-concentration",
        ) => Some("business-analytics-and-ai-concentration"),
        ("uw-bothell-business-administration", "management-information-systems-concentration")
        | (
            "uw-bothell-business-administration",
            "management-information-systems-mis-concentration",
        ) => Some("mis-concentration"),
        (
            "uw-bothell-business-administration",
            "technology-and-innovation-management-concentration",
        )
        | (
            "uw-bothell-business-administration",
            "technology-and-innovation-management-tim-concentration",
        ) => Some("tim-concentration"),
        ("uw-tacoma-history", "culture-and-society-option") => {
            Some("arts-culture-and-society-option")
        }
        ("uw-tacoma-history", "gender-and-identity-option") => {
            Some("power-gender-and-identity-option")
        }
        (
            "uw-tacoma-writing-studies",
            "grassroots-activism-and-community-organizing-this-track-centers-integrative-and-inclusive-pedagogy",
        )
        | ("uw-tacoma-writing-studies", "rhetoric-writing-and-social-change-track") => {
            Some("writing-and-social-change-track")
        }
        ("uw-tacoma-writing-studies", "to-complete-a-ba-in-the-technical-communication-track")
        | (
            "uw-tacoma-writing-studies",
            "to-complete-a-ba-in-the-technical-communication-track-of-writing-studies",
        ) => Some("technical-communication-track"),
        _ => None,
    };
    Some(json!(alias.unwrap_or(&trimmed_pathway_id)))
}

fn js_optional_strict_equal(left: Option<&Value>, right: Option<&Value>) -> bool {
    match (left, right) {
        (None, None) => true,
        (Some(left), Some(right)) => js_strict_equal_audit_values(left, right),
        _ => false,
    }
}

fn audit_normalized_course_codes_from_values(
    values: impl IntoIterator<Item = Option<Value>>,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<String> {
    unique_sorted_source_values(values.into_iter().flatten().flat_map(|value| {
        course_parser
            .extract_from_line(&js_string(&value))
            .into_iter()
            .map(|code| {
                Some(json!(
                    super::requirement_course_codes::normalize_course_code(&code)
                ))
            })
            .collect::<Vec<_>>()
    }))
}

fn sequence_shape_path_summaries(
    group: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<String> {
    rows(group, "sequencePaths")
        .iter()
        .map(|path| {
            let uw_courses =
                shape_course_set_from_values(rows(path, "uwCourses").iter().cloned().map(Some));
            let mut grc_values = rows(path, "mappedGrcCourseCodes").to_vec();
            grc_values.extend(
                rows(group, "options")
                    .iter()
                    .filter(|option| {
                        js_optional_strict_equal(option.get("sequencePathId"), path.get("id"))
                    })
                    .flat_map(|option| rows(option, "grcMatches").iter().cloned()),
            );
            let grc_courses = audit_normalized_course_codes_from_values(
                grc_values.into_iter().map(Some),
                course_parser,
            );
            let label = first_non_nullish([path.get("label"), path.get("id")]);
            let uw_course_summary = if uw_courses.is_empty() {
                "none".to_string()
            } else {
                uw_courses.join(", ")
            };
            let grc_course_summary = if grc_courses.is_empty() {
                "none".to_string()
            } else {
                grc_courses.join(", ")
            };
            format!(
                "{}: UW {} -> GRC {}",
                label
                    .map(js_string)
                    .unwrap_or_else(|| "undefined".to_string()),
                uw_course_summary,
                grc_course_summary
            )
        })
        .collect()
}

fn sequence_path_scoped_notes_summary(group: &Value) -> Vec<String> {
    rows(group, "sequencePaths")
        .iter()
        .filter_map(|path| {
            let labs = shape_course_set_from_values(
                rows(path, "conditionalLabCourses")
                    .iter()
                    .cloned()
                    .map(Some),
            );
            let notes = rows(path, "notes");
            if rows(path, "conditionalLabCourses").is_empty() && notes.is_empty() {
                return None;
            }
            let label = first_non_nullish([path.get("label"), path.get("id")])
                .map(js_string)
                .unwrap_or_else(|| "undefined".to_string());
            let joined_notes = notes
                .iter()
                .map(|note| {
                    if note.is_null() {
                        String::new()
                    } else {
                        js_string(note)
                    }
                })
                .collect::<Vec<_>>()
                .join(" | ");
            let lab_summary = if labs.is_empty() {
                "none".to_string()
            } else {
                labs.join(", ")
            };
            let note_summary = if joined_notes.is_empty() {
                "none".to_string()
            } else {
                joined_notes
            };
            Some(format!("{label}: labs {lab_summary}; notes {note_summary}"))
        })
        .collect()
}

fn sequence_shape_selected_path(group: &Value, item: Option<&Value>) -> String {
    let selected_ids = rows(item.unwrap_or(&Value::Null), "selectedRequirementOptionIds")
        .iter()
        .filter(|value| js_truthy(Some(value)))
        .collect::<Vec<_>>();
    let options = rows(group, "options");
    let selected_option = options
        .iter()
        .find(|option| {
            option
                .get("id")
                .filter(|id| js_truthy(Some(id)))
                .is_some_and(|id| {
                    selected_ids
                        .iter()
                        .any(|selected| js_strict_equal_audit_values(selected, id))
                })
        })
        .or_else(|| options.first());
    let Some(selected_option) = selected_option else {
        return "none".to_string();
    };
    rows(group, "sequencePaths")
        .iter()
        .find(|path| {
            js_optional_strict_equal(path.get("id"), selected_option.get("sequencePathId"))
        })
        .and_then(|path| path.get("label").filter(|value| !value.is_null()))
        .or_else(|| {
            selected_option
                .get("pathLabel")
                .filter(|value| !value.is_null())
        })
        .or_else(|| {
            selected_option
                .get("label")
                .filter(|value| !value.is_null())
        })
        .or_else(|| selected_option.get("id").filter(|value| !value.is_null()))
        .map(js_string)
        .unwrap_or_else(|| "none".to_string())
}

fn sequence_choice_has_flattened_independent_rows(
    group: &Value,
    item: Option<&Value>,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> bool {
    if group.get("requirementType").and_then(Value::as_str) != Some("sequence_choice") {
        return false;
    }
    let paths = rows(group, "sequencePaths");
    let options = rows(group, "options");
    let selected_ids = rows(item.unwrap_or(&Value::Null), "selectedRequirementOptionIds")
        .iter()
        .filter(|value| js_truthy(Some(value)))
        .collect::<Vec<_>>();
    let is_one = |field: &str| {
        group
            .get(field)
            .and_then(Value::as_f64)
            .is_some_and(|value| value == 1.0)
    };
    if group.get("requirementShape").and_then(Value::as_str) != Some("sequence-choice")
        || !is_one("requiredCount")
        || !is_one("selectionCount")
        || !is_one("minCourses")
        || !is_one("maxCourses")
        || paths.len() < 2
        || options.len() != paths.len()
        || selected_ids.len() > 1
    {
        return true;
    }
    let option_ids = options
        .iter()
        .filter_map(|option| option.get("id").filter(|value| js_truthy(Some(value))))
        .collect::<Vec<_>>();
    if selected_ids.iter().any(|selected| {
        !option_ids
            .iter()
            .any(|option_id| js_strict_equal_audit_values(selected, option_id))
    }) {
        return true;
    }
    let selected_option = options.iter().find(|option| {
        option
            .get("id")
            .filter(|value| js_truthy(Some(value)))
            .is_some_and(|option_id| {
                selected_ids
                    .iter()
                    .any(|selected| js_strict_equal_audit_values(selected, option_id))
            })
    });
    let selected_course_codes = audit_normalized_course_codes_from_values(
        selected_option
            .into_iter()
            .flat_map(|option| rows(option, "grcMatches").iter().cloned())
            .map(Some),
        course_parser,
    )
    .into_iter()
    .collect::<HashSet<_>>();
    let item_course_codes = audit_normalized_course_codes_from_values(
        rows(item.unwrap_or(&Value::Null), "grcCourses")
            .iter()
            .cloned()
            .map(Some),
        course_parser,
    );
    !selected_course_codes.is_empty()
        && item_course_codes
            .iter()
            .any(|course| !selected_course_codes.contains(course))
}

fn sequence_choice_has_unscoped_path_notes(group: &Value) -> bool {
    if group.get("requirementType").and_then(Value::as_str) != Some("sequence_choice") {
        return false;
    }
    let options = rows(group, "options");
    for path in rows(group, "sequencePaths") {
        let path_labs = shape_course_set_from_values(
            rows(path, "conditionalLabCourses")
                .iter()
                .cloned()
                .map(Some),
        );
        if path_labs.is_empty() && rows(path, "notes").is_empty() {
            continue;
        }
        let matching_option = options
            .iter()
            .find(|option| js_optional_strict_equal(option.get("sequencePathId"), path.get("id")));
        if !path_labs.is_empty()
            && !path_labs.iter().all(|lab| {
                rows(
                    matching_option.unwrap_or(&Value::Null),
                    "conditionalLabCourses",
                )
                .iter()
                .map(|course| normalize_audit_course_code(Some(course)))
                .any(|course| course == *lab)
            })
        {
            return true;
        }
        if path_labs.iter().any(|lab| {
            options
                .iter()
                .filter(|option| {
                    !js_optional_strict_equal(option.get("sequencePathId"), path.get("id"))
                })
                .any(|option| {
                    rows(option, "conditionalLabCourses")
                        .iter()
                        .map(|course| normalize_audit_course_code(Some(course)))
                        .any(|course| course == *lab)
                })
        }) {
            return true;
        }
    }
    false
}

fn sequence_pathway_shape_issue(
    owner: &Value,
    plan: &Value,
    group: &Value,
    item: Option<&Value>,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> &'static str {
    let effective_pathway_id =
        first_non_nullish([owner.get("pathwayId"), plan.get("selectedPathwayId")]);
    let group_pathway_id = group.get("pathwayId").filter(|value| !value.is_null());
    let plan_id = owner.get("planId");
    let normalized_effective = if effective_pathway_id.is_some_and(|value| js_truthy(Some(value)))
        && plan_id.is_some_and(|value| js_truthy(Some(value)))
    {
        normalize_audit_transfer_pathway_id(plan_id, effective_pathway_id).unwrap_or(Value::Null)
    } else {
        effective_pathway_id.cloned().unwrap_or(Value::Null)
    };
    let normalized_group = if group_pathway_id.is_some_and(|value| js_truthy(Some(value)))
        && plan_id.is_some_and(|value| js_truthy(Some(value)))
    {
        normalize_audit_transfer_pathway_id(plan_id, group_pathway_id).unwrap_or(Value::Null)
    } else {
        group_pathway_id.cloned().unwrap_or(Value::Null)
    };
    if group_pathway_id.is_some_and(|value| js_truthy(Some(value)))
        && effective_pathway_id.is_some_and(|value| js_truthy(Some(value)))
        && !js_strict_equal_audit_values(&normalized_group, &normalized_effective)
    {
        return "pathway-leak";
    }
    if group_pathway_id.is_some_and(|value| js_truthy(Some(value)))
        && effective_pathway_id.is_none_or(|value| !js_truthy(Some(value)))
    {
        return "pathway-leak";
    }
    if sequence_choice_has_unscoped_path_notes(group) {
        return "path-note-unscoped";
    }
    if sequence_choice_has_flattened_independent_rows(group, item, course_parser) {
        return "sequence-choice-flattened";
    }
    "none"
}

fn group_has_sequence_pathway_audit_surface(group: &Value) -> bool {
    static SEQUENCE_SCOPE_PATTERNS: OnceLock<[regex::Regex; 2]> = OnceLock::new();
    let patterns = SEQUENCE_SCOPE_PATTERNS.get_or_init(|| {
        [
            regex::Regex::new(r"(?i-u:\b:pathway:)").expect("static pathway regex is valid"),
            regex::Regex::new(r"(?i-u:\bpathway\b)").expect("static pathway regex is valid"),
        ]
    });
    group.get("requirementType").and_then(Value::as_str) == Some("sequence_choice")
        || group.get("requirementShape").and_then(Value::as_str) == Some("sequence-choice")
        || group
            .get("pathwayId")
            .is_some_and(|value| js_truthy(Some(value)))
        || patterns[0].is_match(&js_string_or(group.get("id"), ""))
        || patterns[1].is_match(&js_string_or(group.get("sourceScope"), ""))
}

pub fn build_sequence_pathway_shape_rows_for_plan(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(&null);
    let plan = input.get("plan").unwrap_or(&null);
    if plan.is_null() {
        return Vec::new();
    }
    let mut items_by_group_id: Vec<(Value, Value)> = Vec::new();
    for item in runtime_checklist_items(plan) {
        let Some(group_id) = item
            .get("requirementGroup")
            .and_then(|group| group.get("id"))
            .filter(|value| js_truthy(Some(value)))
        else {
            continue;
        };
        if let Some((_, existing)) = items_by_group_id
            .iter_mut()
            .find(|(existing_id, _)| js_strict_equal_audit_values(existing_id, group_id))
        {
            *existing = (*item).clone();
        } else {
            items_by_group_id.push((group_id.clone(), (*item).clone()));
        }
    }
    collect_generated_requirement_groups_by_id(plan)
        .into_iter()
        .filter(group_has_sequence_pathway_audit_surface)
        .map(|group| {
            let item = group.get("id").and_then(|id| {
                items_by_group_id
                    .iter()
                    .find(|(existing_id, _)| js_strict_equal_audit_values(existing_id, id))
                    .map(|(_, item)| item)
            });
            let sequence_paths = sequence_shape_path_summaries(&group, course_parser);
            let path_scoped_notes = sequence_path_scoped_notes_summary(&group);
            let flattened = sequence_choice_has_flattened_independent_rows(&group, item, course_parser);
            let issue = sequence_pathway_shape_issue(owner, plan, &group, item, course_parser);
            let effective_pathway_id = first_non_nullish([
                owner.get("pathwayId"),
                plan.get("selectedPathwayId"),
            ])
            .cloned()
            .unwrap_or(Value::Null);
            let group_pathway_id = group
                .get("pathwayId")
                .filter(|value| js_truthy(Some(value)))
                .map(|pathway| format!("pathway:{}", js_string(pathway)))
                .unwrap_or_else(|| "base".to_string());
            let requirement_shape = format!(
                "{} / {} / {}",
                js_string_or(group.get("requirementType"), "unknown"),
                js_string_or(group.get("requirementShape"), "none"),
                group_pathway_id
            );
            let selected_default_path = if group.get("requirementType").and_then(Value::as_str)
                == Some("sequence_choice")
            {
                sequence_shape_selected_path(&group, item)
            } else {
                "none".to_string()
            };
            let pathway_display = if effective_pathway_id.is_null() {
                "none".to_string()
            } else {
                js_string(&effective_pathway_id)
            };
            let requirement_title = group
                .get("label")
                .filter(|value| !value.is_null())
                .cloned()
                .unwrap_or_else(|| json!("unknown requirement"));
            let sequence_path_summary = if sequence_paths.is_empty() {
                "none".to_string()
            } else {
                sequence_paths.join(" | ")
            };
            let path_note_summary = if path_scoped_notes.is_empty() {
                "none".to_string()
            } else {
                path_scoped_notes.join(" | ")
            };
            let debug_text = format!(
                "[sequence/pathway shape audit] Owner id: {} Pathway id: {} Requirement title: {} Requirement shape: {} Sequence paths: {} Selected/default path: {} Path-scoped notes: {} Flattened independent rows: {} Issue: {}",
                js_string_for_template(owner.get("ownerId")),
                pathway_display,
                js_string(&requirement_title),
                requirement_shape,
                sequence_path_summary,
                selected_default_path,
                path_note_summary,
                if flattened { "yes" } else { "no" },
                issue
            );
            let mut row = Map::new();
            if let Some(owner_id) = owner.get("ownerId") {
                row.insert("ownerId".to_string(), owner_id.clone());
            }
            if let Some(pathway_id) = owner
                .get("pathwayId")
                .filter(|value| !value.is_null())
                .or_else(|| plan.get("selectedPathwayId").filter(|value| !value.is_null()))
            {
                row.insert("pathwayId".to_string(), pathway_id.clone());
            } else {
                row.insert("pathwayId".to_string(), Value::Null);
            }
            if let Some(artifact) = input.get("generatedArtifact") {
                row.insert("generatedArtifact".to_string(), artifact.clone());
            }
            if let Some(requirement_id) = group.get("id") {
                row.insert("requirementId".to_string(), requirement_id.clone());
            }
            row.insert("requirementTitle".to_string(), requirement_title);
            row.insert("requirementShape".to_string(), json!(requirement_shape));
            row.insert("sequencePaths".to_string(), json!(sequence_paths));
            row.insert("selectedDefaultPath".to_string(), json!(selected_default_path));
            row.insert("pathScopedNotes".to_string(), json!(path_scoped_notes));
            row.insert("flattenedIndependentRows".to_string(), json!(flattened));
            row.insert("issue".to_string(), json!(issue));
            row.insert("copyOnlyDebugText".to_string(), json!(debug_text));
            Value::Object(row)
        })
        .collect()
}

pub fn build_sequence_pathway_shape_audit_rows_for_owner(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(input);
    let source_artifact = input
        .get("sourceGeneratedArtifact")
        .cloned()
        .unwrap_or_else(|| {
            json!("source/constants/transfer-planner-source/generated-major-plans.ts")
        });
    let runtime_artifact = input
        .get("runtimeGeneratedArtifact")
        .cloned()
        .unwrap_or_else(|| {
            json!("source/constants/transfer-planner-source/student-runtime.generated.ts")
        });
    let mut rows = build_sequence_pathway_shape_rows_for_plan(
        &json!({"owner": owner, "plan": input.get("sourcePlan").unwrap_or(&null), "generatedArtifact": source_artifact}),
        course_parser,
    );
    rows.extend(build_sequence_pathway_shape_rows_for_plan(
        &json!({"owner": owner, "plan": input.get("runtimePlan").unwrap_or(&null), "generatedArtifact": runtime_artifact}),
        course_parser,
    ));
    rows
}

pub fn build_sequence_pathway_shape_audit_rows_for_owners(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let mut output = Vec::new();
    for owner in rows(input, "owners") {
        let owner_key = owner
            .get("ownerId")
            .map(js_string)
            .unwrap_or_else(|| "undefined".to_string());
        let owner_input = json!({
            "owner": owner,
            "sourcePlan": input.get("sourcePlansByOwner").and_then(|plans| plans.get(owner_key.as_str())),
            "runtimePlan": input.get("runtimePlansByOwner").and_then(|plans| plans.get(owner_key.as_str()))
        });
        output.extend(build_sequence_pathway_shape_audit_rows_for_owner(
            &owner_input,
            course_parser,
        ));
    }
    output
}

fn slugify_audit_id(value: &str) -> String {
    let mut slug = String::new();
    let mut in_separator = false;
    for character in value.to_lowercase().chars() {
        if character.is_ascii_alphanumeric() {
            slug.push(character);
            in_separator = false;
        } else if !in_separator {
            slug.push('-');
            in_separator = true;
        }
    }
    slug.trim_matches('-').to_string()
}

fn contains_audit_word_sequence(context: &str, phrase: &str) -> bool {
    let is_word_character = |character: char| character.is_ascii_alphanumeric() || character == '_';
    context.match_indices(phrase).any(|(start, matched)| {
        let end = start + matched.len();
        let left_boundary = context[..start]
            .chars()
            .next_back()
            .is_none_or(|character| !is_word_character(character));
        let right_boundary = context[end..]
            .chars()
            .next()
            .is_none_or(|character| !is_word_character(character));
        left_boundary && right_boundary
    })
}

fn js_string_for_template(value: Option<&Value>) -> String {
    value
        .map(js_string)
        .unwrap_or_else(|| "undefined".to_string())
}

fn support_list_audit_context(block: &Value) -> String {
    [
        "planId",
        "ownerId",
        "ownerTitle",
        "sourceLabel",
        "sourceUrl",
        "primarySourceLabel",
        "primarySourceUrl",
    ]
    .iter()
    .filter_map(|field| block.get(*field).filter(|value| js_truthy(Some(value))))
    .map(js_string)
    .collect::<Vec<_>>()
    .join(" ")
    .to_lowercase()
}

fn infer_support_list_audit_approved_key(block: &Value) -> Option<Value> {
    let context = support_list_audit_context(block);
    let plan_id = nullish_field_string(block, "planId", "");
    let science_context = contains_audit_word_sequence(&context, "natural science")
        || contains_audit_word_sequence(&context, "science");
    if (plan_id == "uw-seattle-computer-engineering"
        || contains_audit_word_sequence(&context, "computer engineering"))
        && science_context
    {
        return Some(json!("computer-engineering-natural-science"));
    }
    if (plan_id == "uw-seattle-computer-science"
        || ["computer science", "allen school", "data science"]
            .iter()
            .any(|needle| contains_audit_word_sequence(&context, needle)))
        && science_context
    {
        return Some(json!("computer-science-approved-science"));
    }
    if contains_audit_word_sequence(&context, "approved")
        && (contains_audit_word_sequence(&context, "elective")
            || contains_audit_word_sequence(&context, "electives"))
    {
        let slug_source = if js_truthy(block.get("planId")) {
            js_string(block.get("planId").unwrap())
        } else if js_truthy(block.get("ownerId")) {
            js_string(block.get("ownerId").unwrap())
        } else {
            "unknown-owner".to_string()
        };
        return Some(json!(format!(
            "{}-approved-electives",
            slugify_audit_id(&slug_source)
        )));
    }
    None
}

fn normalized_support_list_course_codes(block: &Value, field: &str) -> Vec<String> {
    unique_sorted_source_values(
        rows(block, field)
            .iter()
            .map(|course| Some(json!(normalize_audit_course_code(Some(course))))),
    )
}

fn build_support_list_audit_entry(
    block: &Value,
    shape: &str,
    accepted_codes: &[String],
    approved_list_key: Option<&Value>,
) -> Value {
    let source_url = first_non_nullish([block.get("sourceUrl"), block.get("primarySourceUrl")])
        .cloned()
        .unwrap_or(Value::Null);
    let id_source = if let Some(block_id) = block.get("id").filter(|value| !value.is_null()) {
        js_string(block_id)
    } else {
        let fallback = first_non_nullish([Some(&source_url), block.get("sourceLabel")])
            .map(js_string)
            .unwrap_or_else(|| "support-list".to_string());
        slugify_audit_id(&fallback)
    };
    let default_title = if shape == "elective-list" {
        "Elective list"
    } else {
        "Approved course list"
    };
    let list_title = first_non_nullish([block.get("sourceLabel"), block.get("primarySourceLabel")])
        .cloned()
        .unwrap_or_else(|| json!(default_title));
    json!({
        "id": format!("{}:support-list:{shape}", id_source),
        "shape": shape,
        "sourceUrl": source_url,
        "sourceRole": first_non_nullish([block.get("sourceRole")]).cloned().unwrap_or(Value::Null),
        "listTitle": list_title,
        "acceptedUwCourseCodes": accepted_codes,
        "approvedListKey": approved_list_key.filter(|value| !value.is_null()).cloned().unwrap_or(Value::Null),
        "supportOnly": true,
        "canCreateRequiredRow": false,
        "canCreateScheduleRow": false,
        "linkedPrimaryRequirementIds": []
    })
}

fn get_support_lists_for_audit_block(block: &Value) -> Vec<Value> {
    let explicit = rows(block, "supportLists");
    if !explicit.is_empty() {
        return explicit
            .iter()
            .map(|support_list| {
                let mut normalized = support_list.as_object().cloned().unwrap_or_default();
                let accepted_codes = unique_sorted_source_values(
                    rows(support_list, "acceptedUwCourseCodes")
                        .iter()
                        .map(|code| Some(json!(normalize_audit_course_code(Some(code))))),
                );
                normalized.insert("acceptedUwCourseCodes".to_string(), json!(accepted_codes));
                normalized.insert(
                    "supportOnly".to_string(),
                    json!(support_list.get("supportOnly").and_then(Value::as_bool) != Some(false)),
                );
                normalized.insert(
                    "canCreateRequiredRow".to_string(),
                    json!(
                        support_list
                            .get("canCreateRequiredRow")
                            .and_then(Value::as_bool)
                            == Some(true)
                    ),
                );
                normalized.insert(
                    "canCreateScheduleRow".to_string(),
                    json!(
                        support_list
                            .get("canCreateScheduleRow")
                            .and_then(Value::as_bool)
                            == Some(true)
                    ),
                );
                if support_list
                    .get("linkedPrimaryRequirementIds")
                    .is_none_or(Value::is_null)
                {
                    normalized.insert("linkedPrimaryRequirementIds".to_string(), json!([]));
                }
                Value::Object(normalized)
            })
            .collect();
    }
    let approved_codes = normalized_support_list_course_codes(block, "approvedFilterUwCourseCodes");
    let elective_codes = normalized_support_list_course_codes(block, "electiveListUwCourseCodes");
    let support_codes = normalized_support_list_course_codes(block, "supportOnlyUwCourseCodes");
    let used_codes = approved_codes
        .iter()
        .chain(elective_codes.iter())
        .cloned()
        .collect::<HashSet<_>>();
    let remaining_support_codes = support_codes
        .into_iter()
        .filter(|course| !used_codes.contains(course))
        .collect::<Vec<_>>();
    let approved_list_key = infer_support_list_audit_approved_key(block);
    let mut output = Vec::new();
    if !approved_codes.is_empty() {
        output.push(build_support_list_audit_entry(
            block,
            "approved-filter-list",
            &approved_codes,
            approved_list_key.as_ref(),
        ));
    }
    if !elective_codes.is_empty() {
        output.push(build_support_list_audit_entry(
            block,
            "elective-list",
            &elective_codes,
            None,
        ));
    }
    if !remaining_support_codes.is_empty() {
        let source_role = nullish_field_string(block, "sourceRole", "");
        let shape = match source_role.as_str() {
            "elective-list" => Some("elective-list"),
            "approved-course-list" => Some("approved-course-list"),
            _ => None,
        };
        if let Some(shape) = shape {
            output.push(build_support_list_audit_entry(
                block,
                shape,
                &remaining_support_codes,
                if shape == "approved-course-list" {
                    approved_list_key.as_ref()
                } else {
                    None
                },
            ));
        }
    }
    output
}

fn support_list_linked_primary_requirement_ids(
    support_list: &Value,
    source_plan: &Value,
    runtime_plan: &Value,
) -> Vec<String> {
    let Some(approved_key) = support_list
        .get("approvedListKey")
        .filter(|value| js_truthy(Some(value)))
    else {
        return Vec::new();
    };
    let mut ids = Vec::new();
    for plan in [source_plan, runtime_plan] {
        ids.extend(
            collect_generated_requirement_groups_by_id(plan)
                .iter()
                .filter(|group| {
                    group
                        .get("approvedListKey")
                        .is_some_and(|key| js_strict_equal_audit_values(key, approved_key))
                })
                .filter_map(|group| group.get("id").cloned()),
        );
    }
    unique_sorted_source_values(ids.into_iter().map(Some))
}

fn build_elective_approved_list_shape_audit_rows_for_block_context(input: &Value) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(&null);
    let source_plan = input.get("sourcePlan").unwrap_or(&null);
    let runtime_plan = input.get("runtimePlan").unwrap_or(&null);
    let mut output = Vec::new();
    let mut seen = HashSet::new();
    for block in rows(input, "parsedBlocks") {
        for support_list in get_support_lists_for_audit_block(block) {
            let linked_ids = support_list_linked_primary_requirement_ids(
                &support_list,
                source_plan,
                runtime_plan,
            );
            let linked_primary_requirement = if linked_ids.is_empty() {
                "none".to_string()
            } else {
                linked_ids.join(", ")
            };
            let shape = js_string_or(support_list.get("shape"), "");
            let issue = if ![
                "elective-list",
                "approved-course-list",
                "approved-filter-list",
            ]
            .contains(&shape.as_str())
            {
                "missing-list-shape"
            } else if support_list.get("supportOnly").and_then(Value::as_bool) != Some(true)
                || support_list
                    .get("canCreateRequiredRow")
                    .and_then(Value::as_bool)
                    == Some(true)
            {
                "list-promoted-to-required"
            } else if support_list
                .get("canCreateScheduleRow")
                .and_then(Value::as_bool)
                == Some(true)
            {
                "support-list-scheduled"
            } else {
                "none"
            };
            let key = [
                js_string_for_template(owner.get("ownerId")),
                js_string_for_template(support_list.get("id")),
                js_string_for_template(support_list.get("shape")),
                js_string_for_template(support_list.get("sourceUrl")),
            ]
            .join(":");
            if !seen.insert(key) {
                continue;
            }
            let list_title = support_list.get("listTitle");
            let source_url = support_list
                .get("sourceUrl")
                .filter(|value| !value.is_null())
                .cloned()
                .unwrap_or_else(|| json!("none"));
            let shape_value = support_list
                .get("shape")
                .filter(|value| !value.is_null())
                .cloned()
                .unwrap_or_else(|| json!("unknown"));
            let support_only =
                support_list.get("supportOnly").and_then(Value::as_bool) == Some(true);
            let can_create_schedule_row = support_list
                .get("canCreateScheduleRow")
                .and_then(Value::as_bool)
                == Some(true);
            let accepted_codes = support_list
                .get("acceptedUwCourseCodes")
                .filter(|value| !value.is_null())
                .cloned()
                .unwrap_or_else(|| json!([]));
            let approved_list_key = support_list
                .get("approvedListKey")
                .filter(|value| !value.is_null())
                .cloned()
                .unwrap_or(Value::Null);
            let debug_text = format!(
                "[elective/approved list shape audit] Owner id: {} List title: {} Source URL: {} Shape: {} Support-only: {} Can create schedule row: {} Linked primary requirement: {} Issue: {}",
                js_string_for_template(owner.get("ownerId")),
                js_string_for_template(list_title),
                js_string(&source_url),
                js_string(&shape_value),
                if support_only { "yes" } else { "no" },
                if can_create_schedule_row { "yes" } else { "no" },
                linked_primary_requirement,
                issue
            );
            let mut row = Map::new();
            if let Some(owner_id) = owner.get("ownerId") {
                row.insert("ownerId".to_string(), owner_id.clone());
            }
            if let Some(list_title) = list_title {
                row.insert("listTitle".to_string(), list_title.clone());
            }
            row.insert("sourceUrl".to_string(), source_url);
            row.insert("shape".to_string(), shape_value);
            row.insert("supportOnly".to_string(), json!(support_only));
            row.insert(
                "canCreateScheduleRow".to_string(),
                json!(can_create_schedule_row),
            );
            row.insert(
                "linkedPrimaryRequirement".to_string(),
                json!(linked_primary_requirement),
            );
            row.insert("acceptedUwCourseCodes".to_string(), accepted_codes);
            row.insert("approvedListKey".to_string(), approved_list_key);
            row.insert("issue".to_string(), json!(issue));
            row.insert("copyOnlyDebugText".to_string(), json!(debug_text));
            output.push(Value::Object(row));
        }
    }
    output
}

pub fn build_elective_approved_list_shape_audit_rows_for_owner(input: &Value) -> Vec<Value> {
    let null = Value::Null;
    let mut blocks = rows(input, "sourceParsedBlocks").to_vec();
    blocks.extend_from_slice(rows(input, "runtimeParsedBlocks"));
    build_elective_approved_list_shape_audit_rows_for_block_context(&json!({
        "owner": input.get("owner").unwrap_or(input),
        "sourcePlan": input.get("sourcePlan").unwrap_or(&null),
        "runtimePlan": input.get("runtimePlan").unwrap_or(&null),
        "parsedBlocks": blocks
    }))
}

pub fn build_elective_approved_list_shape_audit_rows_for_owners(input: &Value) -> Vec<Value> {
    let null = Value::Null;
    let mut output = Vec::new();
    for owner in rows(input, "owners") {
        let owner_key = owner
            .get("ownerId")
            .map(js_string)
            .unwrap_or_else(|| "undefined".to_string());
        let mut blocks = rows(
            input.get("sourceParsedBlocksByOwner").unwrap_or(&null),
            &owner_key,
        )
        .to_vec();
        blocks.extend_from_slice(rows(
            input.get("runtimeParsedBlocksByOwner").unwrap_or(&null),
            &owner_key,
        ));
        let owner_context = json!({
            "owner": owner,
            "sourcePlan": input.get("sourcePlansByOwner").and_then(|plans| plans.get(owner_key.as_str())),
            "runtimePlan": input.get("runtimePlansByOwner").and_then(|plans| plans.get(owner_key.as_str())),
            "parsedBlocks": blocks
        });
        output.extend(
            build_elective_approved_list_shape_audit_rows_for_block_context(&owner_context),
        );
    }
    output
}

pub fn build_mapping_regression_row(input: &Value) -> Value {
    let issue = input
        .get("issue")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!("none"));
    let suggested_file = input
        .get("suggestedFileFunction")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!(get_suggested_file_for_issue(&issue)));
    let eligible = input.get("eligible").and_then(Value::as_bool) == Some(true);
    let debug_text = format!(
        "[mapping regression report] Owner id: {} Requirement: {} Mapping type: {} Expected mapping: {} Actual mapping: {} Eligible: {} Issue: {} Suggested file/function: {}",
        field_string(input, "ownerId"),
        field_string(input, "requirement"),
        field_string(input, "mappingType"),
        field_string(input, "expectedMapping"),
        field_string(input, "actualMapping"),
        if eligible { "yes" } else { "no" },
        js_string(&issue),
        js_string(&suggested_file),
    );
    let mut row = Map::new();
    for field in [
        "ownerId",
        "requirement",
        "mappingType",
        "expectedMapping",
        "actualMapping",
    ] {
        if let Some(value) = input.get(field) {
            row.insert(field.to_string(), value.clone());
        }
    }
    row.insert("eligible".to_string(), json!(eligible));
    row.insert("issue".to_string(), issue);
    row.insert("suggestedFileFunction".to_string(), suggested_file);
    row.insert("copyOnlyDebugText".to_string(), json!(debug_text));
    Value::Object(row)
}

pub fn build_compound_equivalency_mapping_regression_rows(
    equivalency_rules: &[Value],
) -> Vec<Value> {
    const WATCHLIST: &[(&[&str], &[&str])] = &[
        (&["CHEM& 162", "CHEM& 163"], &["CHEM 152", "CHEM 162"]),
        (
            &["BIOL& 211", "BIOL& 212", "BIOL& 213"],
            &["BIOL 180", "BIOL 200", "BIOL 220"],
        ),
        (&["PHYS& 114", "PHYS& 154"], &["PHYS 114", "PHYS 117"]),
        (&["PHYS& 115", "PHYS& 155"], &["PHYS 115", "PHYS 118"]),
        (&["PHYS& 116", "PHYS& 156"], &["PHYS 116", "PHYS 119"]),
        (
            &["CHEM& 261", "CHEM& 262"],
            &["CHEM 237", "CHEM 238", "CHEM 241"],
        ),
        (
            &["CHEM& 261", "CHEM& 262", "CHEM& 263"],
            &["CHEM 237", "CHEM 238", "CHEM 239", "CHEM 241", "CHEM 242"],
        ),
    ];

    WATCHLIST
        .iter()
        .map(|(source_set, expected_targets)| {
            let normalized_source = source_set
                .iter()
                .map(|course| json!(normalize_audit_course_code(Some(&json!(course)))))
                .collect::<Vec<_>>();
            let expected_source_set = normalized_source
                .iter()
                .map(js_string)
                .collect::<Vec<_>>();
            let expected_targets = expected_targets
                .iter()
                .map(|course| normalize_audit_course_code(Some(&json!(course))))
                .collect::<Vec<_>>();
            let rules =
                get_official_compound_equivalency_rules(&normalized_source, equivalency_rules);
            let normalized_rule_targets = |rule: &Value| {
                rows(rule, "targetCourseCodes")
                    .iter()
                    .map(|course| normalize_audit_course_code(Some(course)))
                    .filter(|course| !course.is_empty())
                    .collect::<Vec<_>>()
            };
            let matching_rules = rules
                .iter()
                .filter(|rule| {
                    let targets = normalized_rule_targets(rule);
                    expected_targets
                        .iter()
                        .all(|target| targets.iter().any(|candidate| candidate == target))
                })
                .collect::<Vec<_>>();
            let partial_rules = rules
                .iter()
                .filter(|rule| {
                    let targets = normalized_rule_targets(rule);
                    expected_targets
                        .iter()
                        .any(|target| targets.iter().any(|candidate| candidate == target))
                })
                .collect::<Vec<_>>();
            let issue = if !matching_rules.is_empty() {
                "none"
            } else if !partial_rules.is_empty() {
                "partial-compound-path"
            } else {
                "missing-compound-path"
            };
            let selected_rules = if matching_rules.is_empty() {
                &partial_rules
            } else {
                &matching_rules
            };
            let actual_mapping = selected_rules
                .iter()
                .map(|rule| {
                    let targets = unique_sorted_source_values(
                        normalized_rule_targets(rule)
                            .into_iter()
                            .map(|course| Some(json!(course))),
                    );
                    let rendered_targets = if targets.is_empty() {
                        audit_template_value(rule.get("targetOutcome"))
                    } else {
                        targets.join(", ")
                    };
                    format!(
                        "{}: {} -> {}",
                        audit_template_value(rule.get("id")),
                        expected_source_set.join(" + "),
                        rendered_targets
                    )
                })
                .collect::<Vec<_>>()
                .join(" | ");
            let actual_mapping = if actual_mapping.is_empty() {
                "none".to_string()
            } else {
                actual_mapping
            };
            let expected_target_text = expected_targets.join(", ");
            let input = json!({
                "ownerId": "uw-green-river-equivalency-guide",
                "requirement": format!("compound watchlist: {expected_target_text}"),
                "mappingType": "compound",
                "expectedMapping": format!("{} -> {expected_target_text}", expected_source_set.join(" + ")),
                "actualMapping": actual_mapping,
                "eligible": issue == "none",
                "issue": issue,
                "suggestedFileFunction": "source/scripts/planner/parse-transfer-planner-equivalency-guide.cjs:buildRule"
            });
            build_mapping_regression_row(&input)
        })
        .collect()
}

pub fn build_program_filter_mapping_regression_rows(
    computer_engineering_audit_rows: &[Value],
    computer_engineering_source_blocks: &[Value],
    computer_science_audit_rows: &[Value],
    computer_science_source_blocks: &[Value],
) -> Vec<Value> {
    const FILTER_AUDIT: &str =
        "source/services/planning/transfer-planner.service.ts:auditProgramApprovedCourseFilters";
    let mut output = Vec::new();
    for (filter_key, owner_id, audit_rows, source_blocks) in [
        (
            "computer-engineering-natural-science",
            "uw-seattle-computer-engineering",
            computer_engineering_audit_rows,
            computer_engineering_source_blocks,
        ),
        (
            "computer-science-approved-science",
            "uw-seattle-computer-science:pathway:data-science-option",
            computer_science_audit_rows,
            computer_science_source_blocks,
        ),
    ] {
        let included_rows = audit_rows
            .iter()
            .filter(|row| {
                row.get("included")
                    .is_some_and(|value| js_truthy(Some(value)))
            })
            .collect::<Vec<_>>();
        let support_blocks = source_blocks
            .iter()
            .filter(|block| {
                rows(block, "supportLists").iter().any(|support| {
                    support.get("approvedListKey").and_then(Value::as_str) == Some(filter_key)
                })
            })
            .collect::<Vec<_>>();
        let unsafe_support_block = support_blocks.iter().any(|block| {
            block.get("supportOnly").and_then(Value::as_bool) != Some(true)
                || block.get("canCreateRequiredRows").and_then(Value::as_bool) == Some(true)
                || block.get("canCreateScheduleRows").and_then(Value::as_bool) == Some(true)
                || !rows(block, "parsedRequirementGroups").is_empty()
                || !rows(block, "parsedRequirementAtomCandidates").is_empty()
        });
        let issue = if included_rows.is_empty() {
            "missing-program-approved-filter"
        } else if unsafe_support_block {
            "approved-list-source-created-required-row"
        } else {
            "none"
        };
        let sample = included_rows
            .iter()
            .take(3)
            .map(|row| {
                format!(
                    "{}->{}",
                    audit_template_value(row.get("approvedUwCode")),
                    js_join_values(rows(row, "grcEquivalentPath"), "+")
                )
            })
            .collect::<Vec<_>>()
            .join(" | ");
        let summary_input = json!({
            "ownerId": owner_id,
            "requirement": format!("{filter_key} approved filter"),
            "mappingType": "program-filter",
            "expectedMapping": "official UW approved codes cross-checked against GRC equivalency rules; support list cannot create rows",
            "actualMapping": format!("included={}; supportBlocks={}; sample={}", included_rows.len(), support_blocks.len(), if sample.is_empty() { "none" } else { &sample }),
            "eligible": issue == "none",
            "issue": issue,
            "suggestedFileFunction": FILTER_AUDIT
        });
        let summary_row = build_mapping_regression_row(&summary_input);
        output.push(summary_row.clone());

        for row in audit_rows
            .iter()
            .filter(|row| {
                row.get("included")
                    .is_some_and(|value| js_truthy(Some(value)))
                    || row.get("reason").and_then(Value::as_str) == Some("generic-category-only")
            })
            .take(8)
        {
            let path = js_join_values(rows(row, "grcEquivalentPath"), " + ");
            let actual_path = if path.is_empty() { "none" } else { &path };
            let reason = audit_template_value(row.get("reason"));
            let expected_mapping =
                if row.get("reason").and_then(Value::as_str) == Some("generic-category-only") {
                    "generic category-only GRC course is excluded from program-approved filter"
                } else {
                    "approved UW equivalent maps through official GRC path"
                };
            let mut representative_input = json!({
                "requirement": format!("{filter_key}: {}", audit_template_value(row.get("approvedUwCode"))),
                "mappingType": "program-filter",
                "expectedMapping": expected_mapping,
                "actualMapping": format!("{actual_path}; included={}; reason={reason}", if row.get("included").is_some_and(|value| js_truthy(Some(value))) { "yes" } else { "no" }),
                "eligible": row.get("issue").is_none_or(Value::is_null),
                "issue": row.get("issue").filter(|value| !value.is_null()).cloned().unwrap_or_else(|| json!("none")),
                "suggestedFileFunction": FILTER_AUDIT
            });
            if let Some(object) = representative_input.as_object_mut() {
                if let Some(row_owner) = row
                    .get("ownerId")
                    .filter(|value| !value.is_null())
                    .or_else(|| summary_row.get("ownerId"))
                {
                    object.insert("ownerId".to_string(), row_owner.clone());
                }
            }
            output.push(build_mapping_regression_row(&representative_input));
        }
    }
    output
}

pub fn build_hidden_unmapped_mapping_regression_rows(
    environmental_plan_exists: bool,
    environmental_cee347_coverage: Option<&Value>,
    informatics_plan_exists: bool,
    informatics_suspicious_visible_labels: &[String],
) -> Vec<Value> {
    let mut output = Vec::new();
    if environmental_plan_exists {
        let coverage_row = environmental_cee347_coverage;
        let actual_mapping = coverage_row.map_or_else(
            || "missing coverage row".to_string(),
            |row| {
                format!(
                    "type={}; visible={}; mapped={}",
                    audit_template_value(row.get("requirementType")),
                    if row
                        .get("visibleInPlan")
                        .is_some_and(|value| js_truthy(Some(value)))
                    {
                        "yes"
                    } else {
                        "no"
                    },
                    join_audit_markdown_list(rows(row, "mappedGrcEquivalentPath"))
                )
            },
        );
        let eligible = coverage_row.is_some_and(|row| {
            row.get("requirementType").and_then(Value::as_str) == Some("hidden-unmapped")
                && row.get("visibleInPlan").and_then(Value::as_bool) == Some(false)
                && rows(row, "mappedGrcEquivalentPath").is_empty()
        });
        let input = json!({
            "ownerId": "uw-seattle-environmental-engineering",
            "requirement": "CEE 347",
            "mappingType": "hidden-unmapped",
            "expectedMapping": "CEE 347 has no fake GRC replacement and stays hidden/unmapped",
            "actualMapping": actual_mapping,
            "eligible": eligible,
            "issue": if eligible { "none" } else { "fake-equivalency" },
            "suggestedFileFunction": "source/services/planning/transfer-planner.service.ts:auditRequiredMappedCourseCoverage"
        });
        output.push(build_mapping_regression_row(&input));
    }

    if informatics_plan_exists {
        let suspicious = !informatics_suspicious_visible_labels.is_empty();
        let input = json!({
            "ownerId": "uw-seattle-informatics",
            "requirement": "INFO-only and upper-division rows",
            "mappingType": "hidden-unmapped",
            "expectedMapping": "unmapped INFO/upper-division requirements stay hidden without engineering/science spillover",
            "actualMapping": if suspicious {
                informatics_suspicious_visible_labels.join(", ")
            } else {
                "no suspicious visible GRC rows".to_string()
            },
            "eligible": !suspicious,
            "issue": if suspicious { "fake-equivalency" } else { "none" },
            "suggestedFileFunction": "source/services/planning/transfer-planner.service.ts:auditVisibleGrcQuarterPlanScope"
        });
        output.push(build_mapping_regression_row(&input));
    }
    output
}

pub fn build_category_mapping_regression_rows_from_audit_rows(
    aeronautics_nsc: Option<&Value>,
    computer_engineering_science: Option<&Value>,
    computer_science_science: Option<&Value>,
) -> Vec<Value> {
    const CATEGORY_AUDIT: &str =
        "source/services/planning/transfer-planner.service.ts:auditCategoryMapping";
    let aeronautics_owner = "uw-seattle-aeronautics-astronautics";
    let aeronautics_requirement = aeronautics_nsc
        .and_then(|row| row.get("requirement"))
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!("A&A generic NSc category option"));
    let aeronautics_actual = aeronautics_nsc.map_or_else(
        || "missing category audit row".to_string(),
        |row| {
            format!(
                "category={}; tags={}; eligible={}",
                audit_template_value(row.get("category")),
                join_audit_markdown_list(rows(row, "genericCategoryTags")),
                if row
                    .get("eligible")
                    .is_some_and(|value| js_truthy(Some(value)))
                {
                    "yes"
                } else {
                    "no"
                }
            )
        },
    );
    let aeronautics_eligible = aeronautics_nsc.is_some_and(|row| {
        row.get("eligible").and_then(Value::as_bool) == Some(true)
            && row.get("issue").is_none_or(Value::is_null)
    });
    let aeronautics_issue = match aeronautics_nsc {
        None => json!("missing-category-option"),
        Some(row) if row.get("issue").and_then(Value::as_str) == Some("fake-category-course") => {
            json!("category-option-invented-course")
        }
        Some(row) => row
            .get("issue")
            .filter(|issue| !issue.is_null())
            .cloned()
            .unwrap_or_else(|| json!("none")),
    };
    let aeronautics_input = json!({
        "ownerId": aeronautics_owner,
        "requirement": aeronautics_requirement,
        "mappingType": "category",
        "expectedMapping": "ANTH& 205 can satisfy generic NSc only through category tags; no concrete course invented",
        "actualMapping": aeronautics_actual,
        "eligible": aeronautics_eligible,
        "issue": aeronautics_issue,
        "suggestedFileFunction": CATEGORY_AUDIT
    });
    let mut output = vec![build_mapping_regression_row(&aeronautics_input)];

    for (owner_id, audit_row) in [
        (
            "uw-seattle-computer-engineering",
            computer_engineering_science,
        ),
        (
            "uw-seattle-computer-science:pathway:data-science-option",
            computer_science_science,
        ),
    ] {
        let requirement = audit_row
            .and_then(|row| row.get("requirement"))
            .filter(|value| !value.is_null())
            .cloned()
            .unwrap_or_else(|| json!("program-specific science category"));
        let actual = audit_row.map_or_else(
            || "missing category audit row".to_string(),
            |row| {
                let program_filter = row
                    .get("programSpecificFilter")
                    .filter(|value| !value.is_null())
                    .map(js_string)
                    .unwrap_or_else(|| "none".to_string());
                format!(
                    "filter={program_filter}; tags={}; programApproved={}; eligible={}",
                    join_audit_markdown_list(rows(row, "genericCategoryTags")),
                    if row
                        .get("programApproved")
                        .is_some_and(|value| js_truthy(Some(value)))
                    {
                        "yes"
                    } else {
                        "no"
                    },
                    if row
                        .get("eligible")
                        .is_some_and(|value| js_truthy(Some(value)))
                    {
                        "yes"
                    } else {
                        "no"
                    }
                )
            },
        );
        let eligible = audit_row.is_some_and(|row| {
            row.get("eligible").and_then(Value::as_bool) == Some(false)
                && row.get("reason").and_then(Value::as_str) == Some("rejected-generic-only")
        });
        let issue = if eligible {
            "none"
        } else {
            "generic-category-used-as-program-approved"
        };
        let input = json!({
            "ownerId": owner_id,
            "requirement": requirement,
            "mappingType": "program-filter",
            "expectedMapping": "ANTH& 205 is generic NSc only and is rejected by program-approved science",
            "actualMapping": actual,
            "eligible": eligible,
            "issue": issue,
            "suggestedFileFunction": CATEGORY_AUDIT
        });
        output.push(build_mapping_regression_row(&input));
    }
    output
}

pub fn build_runtime_compound_mapping_regression_rows(
    runtime_plan_exists: bool,
    audit_rows: &[Value],
) -> Vec<Value> {
    const OWNER_ID: &str = "uw-seattle-civil-engineering";
    const SUGGESTED_FILE: &str =
        "source/services/planning/transfer-planner.service.ts:auditCompoundEquivalencyPaths";
    if !runtime_plan_exists {
        return vec![build_mapping_regression_row(&json!({
            "ownerId": OWNER_ID,
            "requirement": "CHEM 152 compound path",
            "mappingType": "compound",
            "expectedMapping": "CHEM 152 -> CHEM& 162 + CHEM& 163",
            "actualMapping": "runtime plan missing",
            "eligible": false,
            "issue": "missing-compound-path",
            "suggestedFileFunction": SUGGESTED_FILE
        }))];
    }

    audit_rows
        .iter()
        .filter(|row| row.get("uwCourse").and_then(Value::as_str) == Some("CHEM 152"))
        .map(|row| {
            let mut input = json!({
                "mappingType": "compound",
                "expectedMapping": "CHEM 152 schedules CHEM& 162 + CHEM& 163 atomically",
                "actualMapping": format!(
                    "path={}; scheduled={}; missing={}",
                    join_audit_markdown_list(rows(row, "grcCompoundPath")),
                    join_audit_markdown_list(rows(row, "scheduledComponents")),
                    join_audit_markdown_list(rows(row, "missingComponents"))
                ),
                "eligible": row.get("issue") == Some(&Value::Null)
                    && row.get("satisfied").and_then(Value::as_bool) == Some(true),
                "issue": row.get("issue").filter(|issue| !issue.is_null()).cloned()
                    .unwrap_or_else(|| json!("none")),
                "suggestedFileFunction": SUGGESTED_FILE
            });
            if let Some(object) = input.as_object_mut() {
                for (source, target) in [("ownerId", "ownerId"), ("uwRequirement", "requirement")] {
                    if let Some(value) = row.get(source) {
                        object.insert(target.to_string(), value.clone());
                    }
                }
            }
            build_mapping_regression_row(&input)
        })
        .collect()
}

pub fn build_single_equivalency_mapping_regression_rows(rows: &[Value]) -> Vec<Value> {
    rows.iter()
        .map(|row| {
            let grc_course = audit_template_value(row.get("grcCourse"));
            let uw_equivalent = audit_template_value(row.get("uwEquivalent"));
            let actual_mapping = if row
                .get("ruleId")
                .is_some_and(|rule_id| js_truthy(Some(rule_id)))
            {
                format!(
                    "{}; {}",
                    js_string(row.get("ruleId").unwrap()),
                    audit_template_value(row.get("sourceRow"))
                )
            } else {
                format!(
                    "no official Green River equivalency rule found for {grc_course} -> {uw_equivalent}"
                )
            };
            let mut input = json!({
                "mappingType": "single",
                "expectedMapping": format!("{grc_course} -> {uw_equivalent}"),
                "actualMapping": actual_mapping,
                "eligible": row.get("issue").and_then(Value::as_str) == Some("none"),
                "suggestedFileFunction": "source/scripts/planner/parse-transfer-planner-equivalency-guide.cjs:getOfficialSingleCourseEquivalencyRules"
            });
            if let Some(object) = input.as_object_mut() {
                if let Some(owner_id) = row.get("usedByOwnerId") {
                    object.insert("ownerId".to_string(), owner_id.clone());
                }
                if let Some(requirement) = row.get("usedByRequirement") {
                    object.insert("requirement".to_string(), requirement.clone());
                }
                if let Some(issue) = row.get("issue") {
                    object.insert("issue".to_string(), issue.clone());
                }
            }
            build_mapping_regression_row(&input)
        })
        .collect()
}

pub fn build_generated_registry_regression_row(input: &Value) -> Value {
    let issue = normalize_generated_registry_issue(input.get("issue"));
    let source_scope = input.get("sourceScope");
    let source_role = input.get("sourceRole");
    let support_only = input.get("supportOnly").and_then(Value::as_bool) == Some(true)
        || source_role_looks_support_only(source_role)
        || [
            "support",
            "non-schedulable",
            "hidden",
            "informational",
            "ignored",
        ]
        .iter()
        .any(|marker| source_scope_has_scope_marker(source_scope, marker, ""));
    let primary_source_backing = has_primary_source_backing(input);
    let can_create_schedule_row =
        input.get("canCreateScheduleRow").and_then(Value::as_bool) == Some(true);
    let source_role_value = source_role
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let source_scope_value = source_scope
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let protected_pattern = input
        .get("protectedPattern")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let source_role_text = nullish_field_string(input, "sourceRole", "none");
    let copy_only_debug_text = format!(
        "[generated registry regression audit] Owner id: {} Generated artifact: {} Requirement/group id: {} Expected shape: {} Actual shape: {} Source role: {} Support-only: {} Can create schedule row: {} Primary source backing: {} Issue: {}",
        field_string(input, "ownerId"),
        field_string(input, "generatedArtifact"),
        field_string(input, "requirementGroupId"),
        field_string(input, "expectedShape"),
        field_string(input, "actualShape"),
        source_role_text,
        if support_only { "yes" } else { "no" },
        if can_create_schedule_row { "yes" } else { "no" },
        if primary_source_backing { "yes" } else { "no" },
        js_string(&issue),
    );

    let mut row = Map::new();
    for field in [
        "ownerId",
        "generatedArtifact",
        "requirementGroupId",
        "expectedShape",
        "actualShape",
    ] {
        if let Some(value) = input.get(field) {
            row.insert(field.to_string(), value.clone());
        }
    }
    row.insert("sourceRole".to_string(), source_role_value);
    row.insert("sourceScope".to_string(), source_scope_value);
    row.insert("supportOnly".to_string(), json!(support_only));
    row.insert(
        "canCreateScheduleRow".to_string(),
        json!(can_create_schedule_row),
    );
    row.insert(
        "primarySourceBacking".to_string(),
        json!(primary_source_backing),
    );
    row.insert("protectedPattern".to_string(), protected_pattern);
    row.insert("issue".to_string(), issue);
    row.insert("copyOnlyDebugText".to_string(), json!(copy_only_debug_text));
    Value::Object(row)
}

fn join_course_labels(value: Option<&Value>) -> String {
    let Some(value) = value.filter(|value| !value.is_null()) else {
        return "none".to_string();
    };
    let Some(values) = value.as_array() else {
        return js_string(value);
    };
    if values.is_empty() {
        return "none".to_string();
    }
    values
        .iter()
        .map(|value| {
            if value.is_null() {
                String::new()
            } else {
                js_string(value)
            }
        })
        .collect::<Vec<_>>()
        .join(", ")
}

fn insert_if_present(output: &mut Map<String, Value>, target: &str, input: &Value, source: &str) {
    if let Some(value) = input.get(source) {
        output.insert(target.to_string(), value.clone());
    }
}

pub fn build_generated_registry_rows_from_seed_rows(seed_rows: &[Value]) -> Vec<Value> {
    seed_rows
        .iter()
        .map(|row| {
            let source_role = row.get("sourceRole");
            let can_create_schedule_row =
                row.get("canCreateScheduleRow").and_then(Value::as_bool) == Some(true);
            let primary_source_backing = row
                .get("sourceUrl")
                .is_some_and(|value| js_truthy(Some(value)))
                && can_create_schedule_row
                && !source_role_looks_support_only(source_role)
                && source_scope_has_scope_marker(row.get("sourceScope"), "primary-schedulable", "");
            let actual_shape = format!(
                "grc={}; uw={}; manualOverride={}; generatedFromParser={}",
                join_course_labels(row.get("generatedGrcCourseCodes")),
                nullish_field_string(row, "uwCourse", "none"),
                if row
                    .get("manualOverride")
                    .is_some_and(|value| js_truthy(Some(value)))
                {
                    "yes"
                } else {
                    "no"
                },
                if row
                    .get("generatedFromParser")
                    .is_some_and(|value| js_truthy(Some(value)))
                {
                    "yes"
                } else {
                    "no"
                },
            );
            let mut input = Map::new();
            insert_if_present(&mut input, "ownerId", row, "ownerId");
            insert_if_present(&mut input, "generatedArtifact", row, "generatedFile");
            insert_if_present(&mut input, "requirementGroupId", row, "requirementCourse");
            input.insert(
                "expectedShape".to_string(),
                json!("scoped generated checklist row with primary backing before scheduling"),
            );
            input.insert("actualShape".to_string(), json!(actual_shape));
            for field in ["sourceUrl", "sourceRole", "sourceScope", "issue"] {
                insert_if_present(&mut input, field, row, field);
            }
            input.insert(
                "supportOnly".to_string(),
                json!(source_role_looks_support_only(source_role)),
            );
            input.insert(
                "canCreateScheduleRow".to_string(),
                json!(can_create_schedule_row),
            );
            input.insert(
                "primarySourceBacking".to_string(),
                json!(primary_source_backing),
            );
            build_generated_registry_regression_row(&Value::Object(input))
        })
        .collect()
}

pub fn build_generated_registry_rows_from_shape_rows(shape_rows: &[Value]) -> Vec<Value> {
    shape_rows
        .iter()
        .map(|row| {
            let mut input = Map::new();
            insert_if_present(&mut input, "ownerId", row, "ownerId");
            input.insert(
                "generatedArtifact".to_string(),
                row.get("generatedArtifact")
                    .filter(|value| !value.is_null())
                    .cloned()
                    .unwrap_or_else(|| {
                        json!(
                            "source/constants/transfer-planner-source/student-runtime.generated.ts"
                        )
                    }),
            );
            insert_if_present(&mut input, "requirementGroupId", row, "requirementId");
            insert_if_present(&mut input, "expectedShape", row, "sourceParserShape");
            insert_if_present(&mut input, "actualShape", row, "generatedShape");
            for field in ["sourceUrl", "sourceRole", "issue"] {
                insert_if_present(&mut input, field, row, field);
            }
            input.insert(
                "supportOnly".to_string(),
                json!(row.get("supportOnly").and_then(Value::as_bool) == Some(true)),
            );
            input.insert(
                "canCreateScheduleRow".to_string(),
                json!(row.get("canCreateScheduleRow").and_then(Value::as_bool) == Some(true)),
            );
            input.insert(
                "primarySourceBacking".to_string(),
                json!(row.get("primarySourceBacking").and_then(Value::as_bool) == Some(true)),
            );
            build_generated_registry_regression_row(&Value::Object(input))
        })
        .collect()
}

fn generated_registry_owner_should_run(target_plan_id: Option<&Value>, plan_id: &str) -> bool {
    target_plan_id.is_none_or(|target| !js_truthy(Some(target)) || target == &json!(plan_id))
}

fn generated_registry_rows_for_owner<'a>(rows: &'a [Value], owner_id: &Value) -> Vec<&'a Value> {
    generated_registry_rows_for_optional_owner_id(rows, Some(owner_id))
}

fn generated_registry_rows_for_optional_owner_id<'a>(
    rows: &'a [Value],
    owner_id: Option<&Value>,
) -> Vec<&'a Value> {
    rows.iter()
        .filter(|row| match (row.get("ownerId"), owner_id) {
            (None, None) => true,
            (Some(row_owner_id), Some(owner_id)) => {
                js_strict_equal_audit_values(row_owner_id, owner_id)
            }
            _ => false,
        })
        .collect()
}

fn add_generated_registry_protected_row(rows: &mut Vec<Value>, input: Value) {
    let mut fields = input.as_object().cloned().unwrap_or_default();
    fields.insert(
        "generatedArtifact".to_string(),
        json!("protected-owner-generated-registry-regression"),
    );
    let source_role = fields
        .get("sourceRole")
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!("primary-degree-requirements"));
    fields.insert("sourceRole".to_string(), source_role);
    let support_only = fields.get("supportOnly").and_then(Value::as_bool) == Some(true);
    let can_create_schedule_row =
        fields.get("canCreateScheduleRow").and_then(Value::as_bool) == Some(true);
    let primary_source_backing =
        fields.get("primarySourceBacking").and_then(Value::as_bool) == Some(true);
    fields.insert("supportOnly".to_string(), json!(support_only));
    fields.insert(
        "canCreateScheduleRow".to_string(),
        json!(can_create_schedule_row),
    );
    fields.insert(
        "primarySourceBacking".to_string(),
        json!(primary_source_backing),
    );
    let passed = fields
        .get("passed")
        .is_some_and(|value| js_truthy(Some(value)));
    let issue = if passed {
        json!("none")
    } else {
        fields
            .get("issue")
            .filter(|value| !value.is_null())
            .cloned()
            .unwrap_or_else(|| json!("none"))
    };
    fields.insert("issue".to_string(), issue);
    rows.push(build_generated_registry_regression_row(&Value::Object(
        fields,
    )));
}

pub fn build_generated_source_seed_audit_rows_for_owners(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owners = rows(input, "owners");
    let seed_runtime_plans = input.get("seedRuntimePlansByOwner");
    let runtime_plans = input.get("runtimePlansByOwner");
    let parsed_blocks = input.get("parsedBlocksByOwner");
    let primary_sources = input.get("primarySourcesByOwner");
    let mut seed_rows = Vec::new();
    for owner in owners {
        let owner_key = owner
            .get("ownerId")
            .map(js_string)
            .unwrap_or_else(|| "undefined".to_string());
        let seed_plan = seed_runtime_plans
            .and_then(|plans| plans.get(&owner_key))
            .or_else(|| runtime_plans.and_then(|plans| plans.get(&owner_key)))
            .unwrap_or(&null);
        let parsed_blocks_for_owner = parsed_blocks
            .and_then(|blocks| blocks.get(&owner_key))
            .unwrap_or(&null);
        let primary_source = input
            .get("seedPrimarySourcesByOwner")
            .and_then(|sources| sources.get(&owner_key))
            .or_else(|| primary_sources.and_then(|sources| sources.get(&owner_key)))
            .unwrap_or(&null);
        let mut seed_input = json!({
            "owner": owner,
            "runtimePlan": seed_plan,
            "parsedBlocks": parsed_blocks_for_owner,
            "primarySource": primary_source,
            "equivalencyRules": input.get("equivalencyRules").unwrap_or(&null),
            "auditTargetAliases": input.get("auditTargetAliases").unwrap_or(&null),
            "canonicalGrcCourseCodes": input.get("canonicalGrcCourseCodes").unwrap_or(&null)
        });
        if let Some(runtime_codes) = input
            .get("runtimeGrcCourseListsByOwner")
            .and_then(|lists| lists.get(&owner_key))
        {
            seed_input
                .as_object_mut()
                .expect("seed input is an object")
                .insert("runtimeGrcCourseList".to_string(), runtime_codes.clone());
        }
        seed_rows.extend(build_generated_source_seed_audit_rows_for_owner(
            &seed_input,
            course_parser,
        ));
    }
    seed_rows
}

pub fn build_generated_shape_audit_rows_for_owners(
    input: &Value,
    seed_rows: &[Value],
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owners = rows(input, "owners");
    let runtime_plans = input.get("runtimePlansByOwner");
    let source_plans = input.get("sourcePlansByOwner");
    let parsed_blocks = input.get("parsedBlocksByOwner");
    let compact_parsed_blocks = input.get("compactParsedBlocksByOwner");
    let mut shape_rows = Vec::new();
    for owner in owners {
        let owner_key = owner
            .get("ownerId")
            .map(js_string)
            .unwrap_or_else(|| "undefined".to_string());
        let source_plan = source_plans
            .and_then(|plans| plans.get(&owner_key))
            .unwrap_or(&null);
        let runtime_plan = runtime_plans
            .and_then(|plans| plans.get(&owner_key))
            .unwrap_or(&null);
        let parsed_blocks_for_owner = parsed_blocks
            .and_then(|blocks| blocks.get(&owner_key))
            .unwrap_or(&null);
        let compact_blocks_for_owner = compact_parsed_blocks
            .and_then(|blocks| blocks.get(&owner_key))
            .unwrap_or(&null);
        let owner_seed_rows =
            generated_registry_rows_for_optional_owner_id(seed_rows, owner.get("ownerId"));
        let input_for_owner = json!({
            "owner": owner,
            "parsedBlocks": parsed_blocks_for_owner,
            "compactParsedBlocks": compact_blocks_for_owner,
            "sourcePlan": source_plan,
            "runtimePlan": runtime_plan,
            "seedRowsForOwner": owner_seed_rows
        });
        shape_rows.extend(build_generated_shape_audit_rows_for_owner(
            &input_for_owner,
            course_parser,
        ));
    }
    shape_rows
}

pub fn build_generated_registry_audit_rows_with_context(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Value {
    let owners = rows(input, "owners");
    let seed_rows = build_generated_source_seed_audit_rows_for_owners(input, course_parser);
    let shape_rows = build_generated_shape_audit_rows_for_owners(input, &seed_rows, course_parser);
    let mut assembled = input.clone();
    if let Some(object) = assembled.as_object_mut() {
        object.insert("generatedSourceSeedAuditRows".to_string(), json!(seed_rows));
        object.insert("generatedShapeAuditRows".to_string(), json!(shape_rows));
        for (context_key, plan_map_key) in [
            ("sourcePlansByOwner", "sourceGeneratedPlans"),
            ("runtimePlansByOwner", "runtimeGeneratedPlans"),
            ("primarySourcesByOwner", "primarySources"),
        ] {
            if object.contains_key(plan_map_key) {
                continue;
            }
            let mut plans_by_id = Map::new();
            for owner in owners {
                let Some(owner_id) = owner.get("ownerId").filter(|value| !value.is_null()) else {
                    continue;
                };
                let Some(plan_id) = owner.get("planId").filter(|value| !value.is_null()) else {
                    continue;
                };
                if !js_strict_equal_audit_values(owner_id, plan_id) {
                    continue;
                }
                let owner_key = js_string(owner_id);
                let plan_key = js_string(plan_id);
                if let Some(plan) = input
                    .get(context_key)
                    .and_then(|contexts| contexts.get(&owner_key))
                {
                    plans_by_id.insert(plan_key, plan.clone());
                }
            }
            object.insert(plan_map_key.to_string(), Value::Object(plans_by_id));
        }
    }
    build_generated_registry_audit_rows(&assembled)
}

pub fn build_generated_registry_audit_artifacts_with_context(
    generated_at: &str,
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> (Value, String) {
    let owners = rows(input, "owners");
    let registry_rows = build_generated_registry_audit_rows_with_context(input, course_parser);
    let requirement_shape_rows =
        build_requirement_shape_audit_rows_for_owners(input, course_parser);
    let elective_rows = build_elective_approved_list_shape_audit_rows_for_owners(input);
    let credit_category_rows =
        build_credit_category_shape_audit_rows_for_owners(input, course_parser);
    let sequence_pathway_rows =
        build_sequence_pathway_shape_audit_rows_for_owners(input, course_parser);
    let single_equivalency_rows =
        build_single_equivalency_audit_rows_for_owners(input, course_parser);
    let audit_rows = json!({
        "generatedRegistryRows": rows(&registry_rows, "generatedRegistryRows"),
        "generatedSourceSeedAuditRows": rows(&registry_rows, "generatedSourceSeedAuditRows"),
        "generatedShapeAuditRows": rows(&registry_rows, "generatedShapeAuditRows"),
        "requirementShapeAuditRows": requirement_shape_rows,
        "electiveApprovedListShapeAuditRows": elective_rows,
        "creditCategoryShapeAuditRows": credit_category_rows,
        "sequencePathwayShapeAuditRows": sequence_pathway_rows,
        "singleEquivalencyAuditRows": single_equivalency_rows
    });
    build_generated_registry_audit_artifacts(generated_at, owners, &audit_rows)
}

pub fn build_generated_registry_audit_rows(input: &Value) -> Value {
    let owner_rows = rows(input, "owners").to_vec();
    let seed_rows = rows(input, "generatedSourceSeedAuditRows").to_vec();
    let shape_rows = rows(input, "generatedShapeAuditRows").to_vec();
    let mut generated_registry_rows = build_generated_registry_rows_from_seed_rows(&seed_rows);
    generated_registry_rows.extend(build_generated_registry_rows_from_shape_rows(&shape_rows));
    let mut protected_input = input.clone();
    if let Some(object) = protected_input.as_object_mut() {
        object.insert("seedRows".to_string(), json!(seed_rows));
        object.insert("shapeRows".to_string(), json!(shape_rows));
    }
    generated_registry_rows.extend(build_generated_registry_protected_rows(&protected_input));
    json!({
        "owners": owner_rows,
        "generatedSourceSeedAuditRows": seed_rows,
        "generatedShapeAuditRows": shape_rows,
        "generatedRegistryRows": generated_registry_rows
    })
}

fn single_equivalency_option_uw_codes(option: &Value) -> Vec<String> {
    let read_codes = |fields: &[&str]| {
        unique_sorted_source_values(fields.iter().flat_map(|field| {
            option
                .get(*field)
                .and_then(Value::as_array)
                .into_iter()
                .flatten()
                .map(|value| Some(json!(normalize_audit_course_code(Some(value)))))
        }))
        .into_iter()
        .filter(|code| !is_audit_course_level_placeholder(code))
        .collect::<Vec<_>>()
    };
    let direct_codes = read_codes(&["uwCourses", "equivalentUwCourseCodes"]);
    if !direct_codes.is_empty() {
        return direct_codes;
    }
    read_codes(&["displayCourseCodes"])
}

fn single_equivalency_option_grc_codes(
    option: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<String> {
    unique_sorted_source_values(
        option
            .get("grcMatches")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .flat_map(|label| course_parser.extract_from_line(&js_string(label)))
            .map(|code| Some(json!(normalize_audit_course_code(Some(&json!(code))))))
            .filter(|code| {
                code.as_ref()
                    .is_some_and(|value| !is_audit_course_level_placeholder(&js_string(value)))
            }),
    )
}

fn single_equivalency_alias_targets(
    input: &Value,
    campus_id: Option<&Value>,
    uw_course_code: &str,
) -> Vec<String> {
    let alias_value = campus_id
        .filter(|value| !value.is_null())
        .and_then(|campus| {
            input
                .get("campusAliasTargetsByCampus")
                .and_then(|campuses| {
                    let campus_key = js_string(campus);
                    campuses.get(campus_key.as_str())
                })
                .and_then(|courses| courses.get(uw_course_code))
        })
        .or_else(|| {
            if campus_id.is_none_or(Value::is_null) {
                input
                    .get("bothellAliasTargetsByCourse")
                    .and_then(|courses| courses.get(uw_course_code))
            } else {
                None
            }
        });
    let values = match alias_value {
        Some(Value::Array(values)) => values.iter().map(Some).collect::<Vec<_>>(),
        Some(value) if !value.is_null() => vec![Some(value)],
        _ => Vec::new(),
    };
    unique_sorted_source_values(
        values
            .into_iter()
            .map(|value| value.map(|value| json!(normalize_audit_course_code(Some(value))))),
    )
}

fn official_single_equivalency_rules<'a>(
    rules: &'a [Value],
    grc_course_code: &str,
    uw_course_code: &str,
    alias_targets: &[String],
) -> Vec<&'a Value> {
    let target_codes = unique_sorted_source_values(
        std::iter::once(Some(json!(uw_course_code)))
            .chain(alias_targets.iter().map(|target| Some(json!(target)))),
    );
    let accepts_compound_alias_source_set =
        alias_targets.iter().any(|target| target != uw_course_code);
    let mut matching = rules
        .iter()
        .filter(|rule| {
            rule.get("sourceKind").and_then(Value::as_str)
                == Some("uw-green-river-equivalency-guide")
                && rule.get("sourceSchoolId").and_then(Value::as_str) == Some("grc")
                && rule
                    .get("targetSchoolIds")
                    .and_then(Value::as_array)
                    .is_some_and(|schools| {
                        schools.iter().any(|school| {
                            matches!(
                                school.as_str(),
                                Some("uw-seattle" | "uw-bothell" | "uw-tacoma")
                            )
                        })
                    })
                && rule.get("acceptanceCategory").and_then(Value::as_str) != Some("no-credit")
                && rule.get("type").and_then(Value::as_str) != Some("elective-credit")
                && rule
                    .get("sourceCourseSets")
                    .and_then(Value::as_array)
                    .is_some_and(|source_sets| {
                        source_sets.iter().any(|source_set| {
                            let normalized = source_set
                                .as_array()
                                .into_iter()
                                .flatten()
                                .map(|course| normalize_audit_course_code(Some(course)))
                                .filter(|course| !course.is_empty())
                                .collect::<Vec<_>>();
                            (normalized.len() == 1 && normalized[0] == grc_course_code)
                                || (accepts_compound_alias_source_set
                                    && normalized.iter().any(|course| course == grc_course_code))
                        })
                    })
                && rule
                    .get("targetCourseCodes")
                    .and_then(Value::as_array)
                    .is_some_and(|targets| {
                        targets.iter().any(|target| {
                            target_codes.contains(&normalize_audit_course_code(Some(target)))
                        })
                    })
        })
        .collect::<Vec<_>>();
    matching.sort_by(|left, right| {
        let status_rank = |rule: &Value| match rule.get("ruleStatus").and_then(Value::as_str) {
            Some("active") => 0,
            Some("legacy") => 1,
            _ => 2,
        };
        status_rank(left).cmp(&status_rank(right)).then_with(|| {
            let left_id = left.get("id").map(js_string).unwrap_or_default();
            let right_id = right.get("id").map(js_string).unwrap_or_default();
            left_id
                .to_lowercase()
                .cmp(&right_id.to_lowercase())
                .then_with(|| right_id.cmp(&left_id))
        })
    });
    matching
}

fn single_equivalency_source_row(rule: Option<&Value>) -> String {
    let Some(rule) = rule else {
        return "none".to_string();
    };
    let note_value = |prefix: &str| {
        rule.get("notes")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
            .find_map(|note| {
                let text = js_string(note);
                text.get(..prefix.len())
                    .filter(|start| start.eq_ignore_ascii_case(prefix))
                    .map(|_| {
                        let value = text[prefix.len()..].trim_start();
                        value.strip_suffix('.').unwrap_or(value).to_string()
                    })
            })
    };
    let grc_row = rule
        .get("sourceCourseLabel")
        .filter(|value| !value.is_null())
        .map(js_string)
        .or_else(|| note_value("Official Green River row:"))
        .unwrap_or_else(|| "unknown GRC row".to_string());
    let uw_row = rule
        .get("targetOutcome")
        .filter(|value| !value.is_null())
        .map(js_string)
        .or_else(|| note_value("Official UW equivalency row:"))
        .unwrap_or_else(|| "unknown UW row".to_string());
    format!("{grc_row} -> {uw_row}")
}

fn looks_like_unsupported_same_school_substitution(
    grc_course_code: &str,
    uw_course_code: &str,
) -> bool {
    if grc_course_code == uw_course_code {
        return true;
    }
    static COURSE_SUBJECT_SUFFIX: OnceLock<regex::Regex> = OnceLock::new();
    let suffix = COURSE_SUBJECT_SUFFIX.get_or_init(|| {
        regex::Regex::new(r"\s+\d{3}(?:\.\d+)?[A-Z]?$")
            .expect("static course-subject suffix regex is valid")
    });
    suffix.replace(grc_course_code, "") == suffix.replace(uw_course_code, "")
        && !grc_course_code.contains('&')
}

pub fn build_single_equivalency_audit_row(
    input: &Value,
    rules: &[Value],
    alias_targets: &[String],
) -> Value {
    let grc_course = normalize_audit_course_code(input.get("grcCourse"));
    let uw_equivalent = normalize_audit_course_code(input.get("uwEquivalent"));
    let matching_rules =
        official_single_equivalency_rules(rules, &grc_course, &uw_equivalent, alias_targets);
    let rule = matching_rules.first().copied();
    let issue = if matching_rules.is_empty() {
        if input.get("watchlist").and_then(Value::as_bool) == Some(true) {
            "missing-equivalency"
        } else if looks_like_unsupported_same_school_substitution(&grc_course, &uw_equivalent) {
            "unsupported-substitution"
        } else {
            "fake-equivalency"
        }
    } else if matching_rules.iter().any(|rule| {
        rule.get("ruleStatus").and_then(Value::as_str) != Some("legacy")
            && rule.get("isObsoleteSourceCourse").and_then(Value::as_bool) != Some(true)
    }) {
        "none"
    } else {
        "stale-equivalency"
    };
    let source_url = rule
        .and_then(|rule| rule.get("sourceLinks"))
        .and_then(Value::as_array)
        .into_iter()
        .flatten()
        .find(|link| link.get("url").is_some_and(|url| js_truthy(Some(url))))
        .and_then(|link| link.get("url"))
        .cloned()
        .unwrap_or(Value::Null);
    let warning = rule
        .and_then(|rule| rule.get("plannerWarnings"))
        .and_then(Value::as_array)
        .map(|warnings| {
            warnings
                .iter()
                .map(|warning| {
                    if warning.is_null() {
                        String::new()
                    } else {
                        js_string(warning)
                    }
                })
                .collect::<Vec<_>>()
                .join(" | ")
        })
        .filter(|warning| !warning.is_empty())
        .map(Value::String)
        .unwrap_or(Value::Null);
    let rule_type = rule
        .and_then(|rule| rule.get("type"))
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or_else(|| json!("single"));
    let rule_id = rule
        .and_then(|rule| rule.get("id"))
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let source_kind = rule
        .and_then(|rule| rule.get("sourceKind"))
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let effective_date_label = rule
        .and_then(|rule| rule.get("effectiveDateLabel"))
        .filter(|value| !value.is_null())
        .cloned()
        .unwrap_or(Value::Null);
    let source_row = single_equivalency_source_row(rule);
    let copy_only_debug_text = format!(
        "[single equivalency audit] GRC course: {grc_course} UW equivalent: {uw_equivalent} Rule type: single Source row: {source_row} Used by owner id: {} Used by requirement: {} Mapped as required/option/hidden: {} Issue: {issue}",
        audit_template_value(input.get("usedByOwnerId")),
        audit_template_value(input.get("usedByRequirement")),
        audit_template_value(input.get("mappedAs"))
    );
    let mut row = Map::new();
    row.insert("grcCourse".to_string(), json!(grc_course));
    row.insert("uwEquivalent".to_string(), json!(uw_equivalent));
    row.insert("ruleType".to_string(), rule_type);
    row.insert("ruleId".to_string(), rule_id);
    row.insert("sourceKind".to_string(), source_kind);
    row.insert("sourceRow".to_string(), json!(source_row));
    row.insert("sourceUrl".to_string(), source_url);
    row.insert("effectiveDateLabel".to_string(), effective_date_label);
    row.insert("warning".to_string(), warning);
    for field in ["usedByOwnerId", "usedByRequirement", "mappedAs"] {
        if let Some(value) = input.get(field) {
            row.insert(field.to_string(), value.clone());
        }
    }
    row.insert("issue".to_string(), json!(issue));
    row.insert("copyOnlyDebugText".to_string(), json!(copy_only_debug_text));
    Value::Object(row)
}

pub fn build_single_equivalency_audit_rows_for_plan(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(&null);
    let plan = input.get("plan").unwrap_or(&null);
    if !js_truthy(Some(plan)) {
        return Vec::new();
    }
    let rules = rows(input, "equivalencyRules");
    let artifact = js_string_or(input.get("generatedArtifact"), "undefined");
    let artifact_key = input
        .get("generatedArtifact")
        .filter(|value| !value.is_null())
        .map(js_string)
        .unwrap_or_default();
    let owner_id = owner.get("ownerId");
    let owner_id_key = owner_id
        .filter(|value| !value.is_null())
        .map(js_string)
        .unwrap_or_default();
    let campus_id = owner.get("campusId");
    let groups = collect_generated_requirement_groups_by_id(plan);
    let mut seen = HashSet::new();
    let mut output = Vec::new();
    for group in groups {
        for option in group
            .get("options")
            .and_then(Value::as_array)
            .into_iter()
            .flatten()
        {
            if option.get("optionKind").and_then(Value::as_str) == Some("category-option")
                || option
                    .get("categoryOption")
                    .is_some_and(|value| js_truthy(Some(value)))
            {
                continue;
            }
            let uw_codes = single_equivalency_option_uw_codes(option);
            let grc_codes = single_equivalency_option_grc_codes(option, course_parser);
            if uw_codes.len() != 1 || grc_codes.len() != 1 {
                continue;
            }
            let option_id = option
                .get("id")
                .filter(|value| !value.is_null())
                .or_else(|| option.get("label").filter(|value| !value.is_null()))
                .map(js_string)
                .unwrap_or_default();
            let key = [
                artifact_key.as_str(),
                &owner_id_key,
                &js_string_or(group.get("id"), "undefined"),
                option_id.as_str(),
                grc_codes[0].as_str(),
                uw_codes[0].as_str(),
            ]
            .join("|");
            if !seen.insert(key) {
                continue;
            }
            let mapped_as = if group.get("supportOnly").and_then(Value::as_bool) == Some(true)
                || group
                    .get("sourceSectionSchedulable")
                    .and_then(Value::as_bool)
                    == Some(false)
                || group.get("canCreateScheduleRow").and_then(Value::as_bool) == Some(false)
                || source_role_looks_support_only(group.get("sourceRole"))
            {
                "hidden"
            } else if group.get("requirementType").and_then(Value::as_str) == Some("all_required") {
                "required"
            } else {
                "option"
            };
            let label = group
                .get("label")
                .filter(|value| !value.is_null())
                .or_else(|| group.get("id"))
                .map(js_string)
                .unwrap_or_else(|| "undefined".to_string());
            let used_by_requirement = format!("{label} ({artifact})");
            let mut row_input = json!({
                "grcCourse": grc_codes[0],
                "uwEquivalent": uw_codes[0],
                "usedByRequirement": used_by_requirement,
                "mappedAs": mapped_as
            });
            if let Some(owner_id) = owner_id {
                row_input
                    .as_object_mut()
                    .expect("single-equivalency input is an object")
                    .insert("usedByOwnerId".to_string(), owner_id.clone());
            }
            let alias_targets = single_equivalency_alias_targets(input, campus_id, &uw_codes[0]);
            output.push(build_single_equivalency_audit_row(
                &row_input,
                rules,
                &alias_targets,
            ));
        }
    }
    output
}

pub fn build_single_equivalency_audit_rows_for_owner(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let owner = input.get("owner").unwrap_or(&null);
    let mut output = Vec::new();
    for (plan_key, artifact) in [
        (
            "sourcePlan",
            "source/constants/transfer-planner-source/generated-major-plans.ts",
        ),
        (
            "runtimePlan",
            "source/constants/transfer-planner-source/student-runtime.generated.ts",
        ),
    ] {
        let plan = input.get(plan_key).unwrap_or(&null);
        let mut plan_input = input.clone();
        if let Some(object) = plan_input.as_object_mut() {
            object.insert("owner".to_string(), owner.clone());
            object.insert("plan".to_string(), plan.clone());
            object.insert("generatedArtifact".to_string(), json!(artifact));
        }
        output.extend(build_single_equivalency_audit_rows_for_plan(
            &plan_input,
            course_parser,
        ));
    }
    output
}

pub fn build_known_single_equivalency_audit_rows(input: &Value) -> Vec<Value> {
    const REQUIRED_MAPPINGS: &[(&str, &str)] = &[
        ("CHEM& 161", "CHEM 142"),
        ("PHYS& 221", "PHYS 121"),
        ("PHYS& 222", "PHYS 122"),
        ("PHYS& 223", "PHYS 123"),
        ("ENGL& 101", "ENGL 131"),
        ("MATH& 151", "MATH 124"),
        ("MATH& 152", "MATH 125"),
        ("MATH& 163", "MATH 126"),
        ("MATH 240", "MATH 208"),
        ("MATH 238", "MATH 207"),
        ("ENGR& 204", "EE 215"),
    ];
    let rules = rows(input, "equivalencyRules");
    REQUIRED_MAPPINGS
        .iter()
        .map(|(grc_course, uw_course)| {
            let row_input = json!({
                "grcCourse": grc_course,
                "uwEquivalent": uw_course,
                "usedByOwnerId": "uw-green-river-equivalency-guide",
                "usedByRequirement": "official single-course equivalency watchlist",
                "mappedAs": "hidden",
                "watchlist": true
            });
            let alias_targets = single_equivalency_alias_targets(input, None, uw_course);
            build_single_equivalency_audit_row(&row_input, rules, &alias_targets)
        })
        .collect()
}

pub fn build_single_equivalency_audit_rows_for_owners(
    input: &Value,
    course_parser: &super::requirement_course_codes::CourseCodeParser,
) -> Vec<Value> {
    let null = Value::Null;
    let mut output = build_known_single_equivalency_audit_rows(input);
    for owner in rows(input, "owners") {
        let owner_key = owner
            .get("ownerId")
            .map(js_string)
            .unwrap_or_else(|| "undefined".to_string());
        let source_plan = input
            .get("sourcePlansByOwner")
            .and_then(|plans| plans.get(&owner_key))
            .unwrap_or(&null);
        let runtime_plan = input
            .get("runtimePlansByOwner")
            .and_then(|plans| plans.get(&owner_key))
            .unwrap_or(&null);
        let mut owner_input = input.clone();
        if let Some(object) = owner_input.as_object_mut() {
            object.insert("owner".to_string(), owner.clone());
            object.insert("sourcePlan".to_string(), source_plan.clone());
            object.insert("runtimePlan".to_string(), runtime_plan.clone());
        }
        output.extend(build_single_equivalency_audit_rows_for_owner(
            &owner_input,
            course_parser,
        ));
    }
    output
}

pub fn build_generated_registry_protected_rows(input: &Value) -> Vec<Value> {
    let null = Value::Null;
    let target_plan_id = input.get("targetPlanId");
    let seed_rows = rows(input, "seedRows");
    let shape_rows = rows(input, "shapeRows");
    let source_plans = input.get("sourceGeneratedPlans");
    let runtime_plans = input.get("runtimeGeneratedPlans");
    let primary_sources = input.get("primarySources");
    let mut output = Vec::new();

    if generated_registry_owner_should_run(target_plan_id, "uw-seattle-computer-science") {
        let owner_id = json!("uw-seattle-computer-science:pathway:data-science-option");
        let owner_seed_rows = generated_registry_rows_for_owner(seed_rows, &owner_id);
        let unsafe_seed_rows = owner_seed_rows
            .iter()
            .filter(|row| {
                ["MATH 240", "PHYS& 222"]
                    .contains(&normalize_audit_course_code(row.get("requirementCourse")).as_str())
                    || row
                        .get("generatedGrcCourseCodes")
                        .and_then(Value::as_array)
                        .into_iter()
                        .flatten()
                        .any(|course| {
                            ["MATH 240", "PHYS& 222"]
                                .contains(&normalize_audit_course_code(Some(course)).as_str())
                        })
            })
            .collect::<Vec<_>>();
        let science_support_rows = generated_registry_rows_for_owner(shape_rows, &owner_id)
            .into_iter()
            .filter(|row| {
                row.get("sourceRole").and_then(Value::as_str) == Some("approved-course-list")
            })
            .collect::<Vec<_>>();
        let unsafe_issue_count = unsafe_seed_rows
            .iter()
            .filter(|row| {
                row.get("issue")
                    .is_some_and(|issue| js_truthy(Some(issue)) && issue != &json!("none"))
            })
            .count();
        let support_issue_count = science_support_rows
            .iter()
            .filter(|row| {
                row.get("issue")
                    .is_some_and(|issue| js_truthy(Some(issue)) && issue != &json!("none"))
            })
            .count();
        let passed = unsafe_seed_rows.iter().all(|row| {
            row.get("issue")
                .is_none_or(|issue| !js_truthy(Some(issue)) || issue == &json!("none"))
        }) && !science_support_rows.is_empty()
            && science_support_rows.iter().all(|row| {
                row.get("issue").and_then(Value::as_str) == Some("none")
                    && row.get("supportOnly").and_then(Value::as_bool) == Some(true)
            });
        add_generated_registry_protected_row(
            &mut output,
            json!({
                "ownerId": owner_id,
                "requirementGroupId": "cs-data-science-source-scope",
                "protectedPattern": "Computer Science Data Science generated rows cannot bypass source scoping",
                "expectedShape": "no unscoped PHYS 122/MATH 208 generated seeds and approved science support metadata stays support-only",
                "actualShape": format!(
                    "watchlistRows={}; approvedSupportRows={}; approvedSupportIssues={}",
                    unsafe_seed_rows.len(),
                    science_support_rows.len(),
                    support_issue_count
                ),
                "sourceRole": "approved-course-list",
                "supportOnly": true,
                "canCreateScheduleRow": false,
                "primarySourceBacking": false,
                "passed": passed,
                "issue": if unsafe_issue_count > 0 {
                    "unscoped-generated-seed"
                } else {
                    "support-metadata-became-required"
                }
            }),
        );
    }

    if generated_registry_owner_should_run(target_plan_id, "uw-seattle-computer-engineering") {
        let owner_id = json!("uw-seattle-computer-engineering");
        let owner_shape_rows = generated_registry_rows_for_owner(shape_rows, &owner_id);
        let source_plan_groups = collect_generated_requirement_groups_by_id(
            source_plans
                .and_then(|plans| plans.get("uw-seattle-computer-engineering"))
                .unwrap_or(&null),
        );
        let runtime_plan_groups = collect_generated_requirement_groups_by_id(
            runtime_plans
                .and_then(|plans| plans.get("uw-seattle-computer-engineering"))
                .unwrap_or(&null),
        );
        let find_group = |id: &str| {
            source_plan_groups
                .iter()
                .find(|group| group.get("id").and_then(Value::as_str) == Some(id))
                .or_else(|| {
                    runtime_plan_groups
                        .iter()
                        .find(|group| group.get("id").and_then(Value::as_str) == Some(id))
                })
        };
        let natural_science_group = find_group(
            "uw-seattle-computer-engineering:requirement-group:approved-natural-science-10-credits",
        );
        let math_science_group = find_group(
            "uw-seattle-computer-engineering:requirement-group:additional-math-science-3-6-credits",
        );
        let approved_rows = owner_shape_rows
            .into_iter()
            .filter(|row| {
                row.get("sourceRole").and_then(Value::as_str) == Some("approved-course-list")
            })
            .collect::<Vec<_>>();
        let passed = natural_science_group.is_some_and(|group| {
            group.get("requirementType").and_then(Value::as_str) == Some("choose_credits")
                && group
                    .get("minCredits")
                    .is_some_and(|value| js_strict_equal_audit_values(value, &json!(10)))
                && group
                    .get("maxCredits")
                    .is_some_and(|value| js_strict_equal_audit_values(value, &json!(10)))
        }) && math_science_group.is_some_and(|group| {
            group.get("requirementType").and_then(Value::as_str) == Some("choose_credits")
                && group
                    .get("minCredits")
                    .is_some_and(|value| js_strict_equal_audit_values(value, &json!(3)))
                && group
                    .get("maxCredits")
                    .is_some_and(|value| js_strict_equal_audit_values(value, &json!(6)))
        }) && !approved_rows.is_empty()
            && approved_rows.iter().all(|row| {
                row.get("issue").and_then(Value::as_str) == Some("none")
                    && row.get("supportOnly").and_then(Value::as_bool) == Some(true)
            });
        add_generated_registry_protected_row(
            &mut output,
            json!({
                "ownerId": owner_id,
                "requirementGroupId": "ce-credit-buckets-and-approved-list",
                "protectedPattern": "Computer Engineering credit buckets remain choose_credits and approved list remains support-only",
                "expectedShape": "Natural Science choose_credits, Math/Science choose_credits, approved science support metadata",
                "actualShape": format!(
                    "naturalScience={}; mathScience={}; approvedSupportRows={}",
                    group_shape_summary(natural_science_group),
                    group_shape_summary(math_science_group),
                    approved_rows.len()
                ),
                "sourceRole": "primary-degree-requirements",
                "supportOnly": false,
                "canCreateScheduleRow": true,
                "primarySourceBacking": true,
                "passed": passed,
                "issue": if natural_science_group.is_some() && math_science_group.is_some() {
                    "support-metadata-became-required"
                } else {
                    "flattened-credit-bucket"
                }
            }),
        );
    }

    if generated_registry_owner_should_run(target_plan_id, "uw-seattle-environmental-engineering") {
        let owner_id = json!("uw-seattle-environmental-engineering");
        let earth_science_row = generated_registry_rows_for_owner(shape_rows, &owner_id)
            .into_iter()
            .find(|row| {
                let text = format!(
                    "{} {}",
                    nullish_field_string(row, "requirementTitle", ""),
                    nullish_field_string(row, "requirementId", "")
                )
                .to_lowercase();
                text.contains("earth science")
            });
        let generated_shape = earth_science_row
            .and_then(|row| row.get("generatedShape"))
            .cloned()
            .unwrap_or_else(|| json!("not emitted by generated registry"));
        let passed = earth_science_row.is_none_or(|row| {
            row.get("issue").and_then(Value::as_str) == Some("none")
                && nullish_field_string(row, "generatedShape", "").contains("type=choose_one")
        });
        let mut protected = json!({
            "ownerId": owner_id,
            "requirementGroupId": "environmental-engineering-earth-science",
            "protectedPattern": "Environmental Engineering Earth science elective remains one choose_one group",
            "expectedShape": "choose_one if emitted by parser/generated registry",
            "actualShape": generated_shape,
            "sourceRole": "primary-degree-requirements",
            "supportOnly": false,
            "canCreateScheduleRow": false,
            "primarySourceBacking": false,
            "passed": passed,
            "issue": "flattened-option-group"
        });
        if let Some(row) = earth_science_row {
            let object = protected
                .as_object_mut()
                .expect("protected row is an object");
            object.insert(
                "sourceRole".to_string(),
                row.get("sourceRole")
                    .filter(|value| !value.is_null())
                    .cloned()
                    .unwrap_or_else(|| json!("primary-degree-requirements")),
            );
            object.insert(
                "supportOnly".to_string(),
                json!(row.get("supportOnly").and_then(Value::as_bool) == Some(true)),
            );
            object.insert(
                "canCreateScheduleRow".to_string(),
                json!(row.get("canCreateScheduleRow").and_then(Value::as_bool) == Some(true)),
            );
            object.insert(
                "primarySourceBacking".to_string(),
                json!(row.get("primarySourceBacking").and_then(Value::as_bool) == Some(true)),
            );
        }
        add_generated_registry_protected_row(&mut output, protected);
    }

    if generated_registry_owner_should_run(target_plan_id, "uw-seattle-aeronautics-astronautics") {
        let owner_id = json!("uw-seattle-aeronautics-astronautics");
        let nsc_row = generated_registry_rows_for_owner(shape_rows, &owner_id)
            .into_iter()
            .find(|row| {
                let shape = nullish_field_string(row, "generatedShape", "").to_lowercase();
                shape.contains("categories=") && shape.contains("nsc")
            });
        let mut protected = json!({
            "ownerId": owner_id,
            "requirementGroupId": "aa-nsc-category-option",
            "protectedPattern": "A&A NSc mixed option remains a category-option",
            "expectedShape": "choose_one with non-concrete NSc category option",
            "actualShape": nsc_row
                .and_then(|row| row.get("generatedShape"))
                .cloned()
                .unwrap_or_else(|| json!("missing")),
            "sourceRole": "primary-degree-requirements",
            "supportOnly": false,
            "canCreateScheduleRow": false,
            "primarySourceBacking": false,
            "passed": nsc_row.is_some_and(|row| row.get("issue").and_then(Value::as_str) == Some("none")),
            "issue": if nsc_row.is_some() { "fake-course-invented" } else { "missing-category-option" }
        });
        if let Some(row) = nsc_row {
            let object = protected
                .as_object_mut()
                .expect("protected row is an object");
            object.insert(
                "sourceRole".to_string(),
                row.get("sourceRole")
                    .filter(|value| !value.is_null())
                    .cloned()
                    .unwrap_or_else(|| json!("primary-degree-requirements")),
            );
            for field in [
                "supportOnly",
                "canCreateScheduleRow",
                "primarySourceBacking",
            ] {
                object.insert(
                    field.to_string(),
                    json!(row.get(field).and_then(Value::as_bool) == Some(true)),
                );
            }
        }
        add_generated_registry_protected_row(&mut output, protected);
    }

    for plan_id in [
        "uw-seattle-biology",
        "uw-seattle-biochemistry",
        "uw-seattle-chemistry",
    ] {
        if !generated_registry_owner_should_run(target_plan_id, plan_id) {
            continue;
        }
        let owner_id = json!(plan_id);
        let sequence_rows = generated_registry_rows_for_owner(shape_rows, &owner_id)
            .into_iter()
            .filter(|row| {
                nullish_field_string(row, "sourceParserShape", "").contains("type=sequence_choice")
                    && nullish_field_string(row, "sourceParserShape", "").contains("PHYS 1")
            })
            .collect::<Vec<_>>();
        let actual_shape = if sequence_rows.is_empty() {
            "parser did not emit physics sequence_choice".to_string()
        } else {
            sequence_rows
                .iter()
                .map(|row| {
                    row.get("generatedShape")
                        .filter(|shape| !shape.is_null())
                        .map(js_string)
                        .unwrap_or_default()
                })
                .collect::<Vec<_>>()
                .join(" || ")
        };
        let first_row = sequence_rows.first().copied();
        let passed = sequence_rows
            .iter()
            .all(|row| row.get("issue").and_then(Value::as_str) == Some("none"));
        let mut protected = json!({
            "ownerId": owner_id,
            "requirementGroupId": format!("{plan_id}:physics-sequence-choice"),
            "protectedPattern": "Physics sequence alternatives stay sequence_choice if parser emits them",
            "expectedShape": "sequence_choice paths preserved from parser through generated registry",
            "actualShape": actual_shape,
            "sourceRole": "primary-degree-requirements",
            "supportOnly": false,
            "canCreateScheduleRow": false,
            "primarySourceBacking": false,
            "passed": passed,
            "issue": "flattened-sequence-choice"
        });
        if let Some(row) = first_row {
            let object = protected
                .as_object_mut()
                .expect("protected row is an object");
            object.insert(
                "sourceRole".to_string(),
                row.get("sourceRole")
                    .filter(|value| !value.is_null())
                    .cloned()
                    .unwrap_or_else(|| json!("primary-degree-requirements")),
            );
            for field in [
                "supportOnly",
                "canCreateScheduleRow",
                "primarySourceBacking",
            ] {
                object.insert(
                    field.to_string(),
                    json!(row.get(field).and_then(Value::as_bool) == Some(true)),
                );
            }
        }
        add_generated_registry_protected_row(&mut output, protected);
    }

    for owner_text in [
        "uw-seattle-chemical-engineering",
        "uw-seattle-materials-science-engineering:pathway:nme-option",
    ] {
        let (plan_id, _) = owner_text
            .split_once(":pathway:")
            .unwrap_or((owner_text, ""));
        if !generated_registry_owner_should_run(target_plan_id, plan_id) {
            continue;
        }
        let owner_id = json!(owner_text);
        let elective_rows = generated_registry_rows_for_owner(shape_rows, &owner_id)
            .into_iter()
            .filter(|row| row.get("sourceRole").and_then(Value::as_str) == Some("elective-list"))
            .collect::<Vec<_>>();
        let issue_count = elective_rows
            .iter()
            .filter(|row| row.get("issue").and_then(Value::as_str) != Some("none"))
            .count();
        let passed = elective_rows.is_empty() || issue_count == 0;
        add_generated_registry_protected_row(
            &mut output,
            json!({
                "ownerId": owner_id,
                "requirementGroupId": format!("{owner_text}:engineering-electives-support-only"),
                "protectedPattern": "ChemE/NME engineering electives remain elective-list support metadata",
                "expectedShape": "elective-list/support-only rows do not become generated required rows",
                "actualShape": format!("electiveRows={}; issues={issue_count}", elective_rows.len()),
                "sourceRole": "elective-list",
                "supportOnly": true,
                "canCreateScheduleRow": false,
                "primarySourceBacking": false,
                "passed": passed,
                "issue": "elective-list-generated-required-row"
            }),
        );
    }

    if generated_registry_owner_should_run(
        target_plan_id,
        "uw-seattle-sustainable-bioresource-systems-engineering",
    ) {
        let plan_id = "uw-seattle-sustainable-bioresource-systems-engineering";
        let primary_source = primary_sources
            .and_then(|sources| sources.get(plan_id))
            .unwrap_or(&null);
        let primary_url = primary_source
            .get("url")
            .filter(|url| !url.is_null())
            .cloned()
            .unwrap_or_else(|| json!(""));
        let primary_url_text = js_string(&primary_url);
        let url_lower = primary_url_text.to_lowercase();
        let is_catalog_url = url_lower.contains("washington.edu/students/gencat");
        static SBSE_ANCHOR: OnceLock<regex::Regex> = OnceLock::new();
        let has_anchor = SBSE_ANCHOR
            .get_or_init(|| {
                regex::Regex::new(r"#program-UG-SBSE-MAJOR\b")
                    .expect("static SBSE anchor regex is valid")
            })
            .is_match(&primary_url_text);
        let url_is_truthy = js_truthy(Some(&primary_url));
        let passed = url_is_truthy && (!is_catalog_url || has_anchor);
        let source_role = primary_source
            .get("role")
            .filter(|role| !role.is_null())
            .cloned()
            .unwrap_or_else(|| json!("official-catalog"));
        let mut protected = json!({
            "ownerId": plan_id,
            "requirementGroupId": "sbse-catalog-anchor",
            "protectedPattern": "SBSE catalog anchor section-scoping survives generation",
            "expectedShape": "catalog URL keeps #program-UG-SBSE-MAJOR anchor when a catalog source is generated; department primary remains source-scoped",
            "actualShape": if url_is_truthy { primary_url } else { json!("missing") },
            "sourceRole": source_role,
            "supportOnly": false,
            "canCreateScheduleRow": true,
            "primarySourceBacking": js_truthy(primary_source.get("url")),
            "passed": passed,
            "issue": "unscoped-generated-seed"
        });
        if let Some(url) = primary_source.get("url") {
            protected
                .as_object_mut()
                .expect("protected row is an object")
                .insert("sourceUrl".to_string(), url.clone());
        }
        add_generated_registry_protected_row(&mut output, protected);
    }

    if generated_registry_owner_should_run(target_plan_id, "uw-seattle-informatics") {
        let owner_id = json!("uw-seattle-informatics");
        let fake_info_count = generated_registry_rows_for_owner(seed_rows, &owner_id)
            .into_iter()
            .filter(|row| {
                let requirement_course = js_string_nullish(row.get("requirementCourse"));
                let uw_course = js_string_nullish(row.get("uwCourse"));
                let text = format!("{requirement_course} {uw_course}");
                let course_parser = super::requirement_course_codes::CourseCodeParser::default();
                let course_codes = course_parser.extract_from_line(&text);
                !course_codes.is_empty()
                    && course_codes.iter().all(|course_code| {
                        static INFO_COURSE: OnceLock<regex::Regex> = OnceLock::new();
                        INFO_COURSE
                            .get_or_init(|| {
                                regex::Regex::new(r"(?i)^INFO\s*\d{3}\b")
                                    .expect("static INFO course regex is valid")
                            })
                            .is_match(course_code)
                    })
                    && row
                        .get("generatedGrcCourseCodes")
                        .and_then(Value::as_array)
                        .is_some_and(|codes| !codes.is_empty())
            })
            .count();
        add_generated_registry_protected_row(
            &mut output,
            json!({
                "ownerId": owner_id,
                "requirementGroupId": "informatics-unmapped-info-hidden",
                "protectedPattern": "Informatics INFO-only requirements stay hidden/unmapped without fake GRC rows",
                "expectedShape": "INFO-only rows have no generated GRC schedule row unless primary-backed equivalent exists",
                "actualShape": format!("fakeInfoRows={fake_info_count}"),
                "sourceRole": "primary-degree-requirements",
                "supportOnly": false,
                "canCreateScheduleRow": false,
                "primarySourceBacking": false,
                "passed": fake_info_count == 0,
                "issue": "hidden-informational-row-scheduled"
            }),
        );
    }
    output
}

fn rows<'a>(input: &'a Value, key: &str) -> &'a [Value] {
    input
        .get(key)
        .and_then(Value::as_array)
        .map(Vec::as_slice)
        .unwrap_or(&[])
}

fn issue_field_rows(rows: &[Value]) -> Vec<&Value> {
    rows.iter()
        .filter(|row| {
            row.get("issue")
                .is_some_and(|issue| js_truthy(Some(issue)) && issue != &json!("none"))
        })
        .collect()
}

fn zero_counts(issue_types: &[&str]) -> Map<String, Value> {
    issue_types
        .iter()
        .map(|issue_type| ((*issue_type).to_string(), json!(0)))
        .collect()
}

fn increment_known_count(counts: &mut Map<String, Value>, issue: &Value, issue_types: &[&str]) {
    let key = js_string(issue);
    if issue_types.contains(&key.as_str()) {
        let count = counts.get(&key).and_then(Value::as_u64).unwrap_or_default();
        counts.insert(key, json!(count + 1));
    }
}

