    #[test]
    fn informatics_scope_check_rejects_science_and_upper_division_leaks() {
        let clean_labels = vec![json!("INFO 200"), json!("MATH 124")];
        let clean = build_informatics_scope_check(&clean_labels);
        assert_eq!(clean.get("status").and_then(Value::as_str), Some("passed"));
        assert_eq!(
            clean.get("id").and_then(Value::as_str),
            Some("uw-seattle-informatics:hidden-unmapped-info-only")
        );
        for leaked in ["PHYS& 222", "ENGR 140", "BIME 401", "CSE 350"] {
            let check = build_informatics_scope_check(&[json!("INFO 200"), json!(leaked)]);
            assert_eq!(
                check.get("status").and_then(Value::as_str),
                Some("failed"),
                "expected {leaked:?} to be rejected"
            );
        }
    }

