    #[test]
    fn matched_track_summary_parser_and_checks_preserve_parse_and_order_rules() {
        let parsed = parse_matched_track_summary(Some(&json!(
            "AST-2 is the best fit and matches 5 of the 6 tracked requirements"
        )))
        .unwrap();
        assert_eq!(parsed.track_code, "AST-2");
        assert_eq!(parsed.match_count, 5.0);
        assert_eq!(parsed.total_tracked, 6.0);
        assert!(parse_matched_track_summary(Some(&json!("stale summary"))).is_none());

        let plans = [
            ("uw-seattle-bioengineering", None),
            ("uw-seattle-mechanical-engineering", None),
            (
                "uw-seattle-materials-science-engineering",
                Some("nme-option"),
            ),
        ];
        let plan_values = plans
            .iter()
            .map(|(plan_id, _)| {
                json!({
                    "title": plan_id,
                    "bestTrackId": "track-ast2",
                    "recommendedTrackSummary": "AST-2 is the best fit and matches 5 of the 6 tracked requirements"
                })
            })
            .collect::<Vec<_>>();
        let track_values = (0..3)
            .map(|_| json!({"id": "track-ast2", "code": "AST-2"}))
            .collect::<Vec<_>>();
        let inputs = plans
            .iter()
            .enumerate()
            .map(
                |(index, (plan_id, pathway_id))| MatchedTrackSummaryAuditInput {
                    plan_id,
                    pathway_id: *pathway_id,
                    plan: Some(&plan_values[index]),
                    track: Some(&track_values[index]),
                    tracked_requirement_count: 7,
                },
            )
            .collect::<Vec<_>>();
        let checks = build_matched_track_summary_checks(&inputs);
        assert_eq!(checks.len(), 3);
        assert!(
            checks
                .iter()
                .all(|check| check.get("status").and_then(Value::as_str) == Some("passed"))
        );
        assert_eq!(
            checks
                .iter()
                .map(|check| check.get("id").and_then(Value::as_str).unwrap())
                .collect::<Vec<_>>(),
            vec![
                "matched-track-summary:uw-seattle-bioengineering",
                "matched-track-summary:uw-seattle-mechanical-engineering",
                "matched-track-summary:uw-seattle-materials-science-engineering:nme-option"
            ]
        );
    }

