    #[test]
    fn computer_science_data_science_check_keeps_pathway_scoped_and_programming_rows() {
        let parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let block = json!({
            "sourceUrl": "https://example.test/CS_DS_degreq_fall23.pdf",
            "sourceRole": "pathway-degree-sheet",
            "parsedUwCourseCodes": ["CSE 123", "CSE 143", "MATH 208"],
            "parsedRequirementGroups": [{
                "options": [{"uwCourses": ["CSE 123", "CSE 143"]}]
            }]
        });
        let labels = ["CS 121", "CS 122", "CS 123", "MATH 240"]
            .into_iter()
            .map(|course| json!(course))
            .collect::<Vec<_>>();
        let source_rows = vec![
            json!({"courseCode": "CSE 123", "emittedAs": "option-group", "scheduled": true, "issue": "none", "copyOnlyDebugText": "CSE 123 option"}),
            json!({"courseCode": "CSE 143", "emittedAs": "option-group", "scheduled": false, "issue": "none", "copyOnlyDebugText": "CSE 143 option"}),
            json!({"courseCode": "MATH 208", "emittedAs": "required-course", "scheduled": true, "issue": "none", "copyOnlyDebugText": "MATH 208 required"}),
        ];
        let required_coverage = Vec::new();
        let programming_audit = json!({
            "detectedAsTrueOption": true,
            "satisfiedBy": "planner-defaulted",
            "copyOnlyDebugText": "Programming option defaults unresolved"
        });
        let completed_programming_audit = json!({
            "satisfiedBy": "transcript-completed",
            "copyOnlyDebugText": "Completed CS 123"
        });
        let completed_labels = Vec::new();
        let input = ComputerScienceDataScienceRegressionInput {
            plan_exists: true,
            data_science_block: Some(&block),
            planned_labels: &labels,
            source_scope_rows: &source_rows,
            required_coverage_rows: &required_coverage,
            programming_audit: Some(&programming_audit),
            completed_programming_audit: Some(&completed_programming_audit),
            completed_programming_labels: &completed_labels,
            course_parser: &parser,
        };
        let check = build_computer_science_data_science_regression_check(&input);
        assert_eq!(check.get("status").and_then(Value::as_str), Some("passed"));
        assert_eq!(
            check.get("id").and_then(Value::as_str),
            Some("uw-computer-science:data-science-source-scope")
        );
        let approved_manifest_entries = vec![json!({
            "role": "approved-course-list",
            "url": "https://www.cs.washington.edu/degree-requirements/courses/#natural-science"
        })];
        let ordered_checks =
            build_computer_science_regression_checks(&input, &approved_manifest_entries, None);
        assert_eq!(ordered_checks.len(), 2);
        assert_eq!(
            ordered_checks
                .iter()
                .map(|check| check.get("id").and_then(Value::as_str).unwrap())
                .collect::<Vec<_>>(),
            vec![
                "uw-computer-science:data-science-source-scope",
                "uw-computer-science:approved-science-support-source"
            ]
        );

        let mut contaminated_rows = source_rows.clone();
        contaminated_rows[1]["scheduled"] = json!(true);
        let contaminated = build_computer_science_data_science_regression_check(
            &ComputerScienceDataScienceRegressionInput {
                source_scope_rows: &contaminated_rows,
                ..input
            },
        );
        assert_eq!(
            contaminated.get("status").and_then(Value::as_str),
            Some("failed")
        );
    }

