    #[test]
    fn computer_engineering_approved_filter_check_requires_inclusions_and_exclusions() {
        let natural_science_bucket = json!({
            "filterSource": "ce-approved-natural-science",
            "copyOnlyDebugText": "Approved Natural Science bucket"
        });
        let filter_rows = vec![
            json!({"included": true, "course": "CHEM& 161", "uwEquivalent": "CHEM 142", "copyOnlyDebugText": "CHEM 142 direct"}),
            json!({"included": true, "course": "CHEM& 162, CHEM& 163", "uwEquivalent": "CHEM 152 and CHEM 162", "copyOnlyDebugText": "CHEM 152 compound"}),
            json!({"included": true, "course": "PHYS& 223", "uwEquivalent": "PHYS 123", "copyOnlyDebugText": "PHYS 123"}),
            json!({"included": true, "course": "BIOL& 211, BIOL& 212, BIOL& 213", "uwEquivalent": "BIOL 180, BIOL 200, BIOL 220", "copyOnlyDebugText": "Biology sequence"}),
            json!({"included": false, "reason": "generic-category-only", "course": "ANTH& 205", "copyOnlyDebugText": "Excluded generic Anthropology"}),
        ];
        let source_rows = vec![
            json!({"uwApprovedCourse": "CHEM 142", "includedInFilter": true, "copyOnlyDebugText": "CHEM 142 approved"}),
            json!({"reason": "petition-only", "includedInFilter": false, "copyOnlyDebugText": "Excluded by petition-only rule"}),
        ];
        let check = build_computer_engineering_approved_filter_check(
            Some(&natural_science_bucket),
            &filter_rows,
            &source_rows,
        );
        assert_eq!(check.get("status").and_then(Value::as_str), Some("passed"));
        let details = check.get("details").and_then(Value::as_array).unwrap();
        assert_eq!(details.len(), 3);
        assert_eq!(details[0].as_str(), Some("Approved Natural Science bucket"));
        assert!(details[1].as_str().unwrap().contains("CHEM 152 compound"));
        assert!(details[2].as_str().unwrap().contains("CHEM 142 approved"));
        assert!(details[2].as_str().unwrap().contains("petition-only rule"));

        let missing_generic_exclusion = filter_rows
            .iter()
            .filter(|row| row.get("course").and_then(Value::as_str) != Some("ANTH& 205"))
            .cloned()
            .collect::<Vec<_>>();
        let failed = build_computer_engineering_approved_filter_check(
            Some(&natural_science_bucket),
            &missing_generic_exclusion,
            &source_rows,
        );
        assert_eq!(failed.get("status").and_then(Value::as_str), Some("failed"));
    }

