    #[test]
    fn programming_audit_helpers_prioritize_exact_rows_and_extract_option_labels() {
        let fallback_row = json!({
            "id": "fallback",
            "acceptedUwOptions": ["CSE 121", "CSE 122", "CSE 123"],
            "mappedGrcOptions": ["CS 121", "CS 122", "CS 123", "ENGR 250"]
        });
        let exact_row = json!({
            "id": "exact",
            "acceptedUwOptions": ["cse 123", "CSE 143"],
            "mappedGrcOptions": ["CS 123", "CS 145"]
        });
        assert_eq!(
            find_programming_audit_row(&[fallback_row.clone(), exact_row.clone()]),
            Some(exact_row)
        );
        assert_eq!(
            find_programming_audit_row(&[fallback_row.clone()]),
            Some(fallback_row)
        );
        assert_eq!(
            find_programming_audit_row(&[json!({"id": "unmatched"})]),
            None
        );

        let parser = super::super::requirement_course_codes::CourseCodeParser::with_known_subjects(
            ["CSE", "CS"].into_iter().map(str::to_string),
        );
        let group = json!({
            "options": [
                {"uwCourses": ["CSE 123"], "equivalentUwCourseCodes": ["CSE 143"]},
                {"displayCourseCodes": ["CSE 121"]}
            ]
        });
        assert!(parsed_requirement_group_contains_programming_options(
            Some(&group),
            &parser
        ));
        let incomplete_group = json!({"options": [{"uwCourses": ["CSE 123"]}]});
        assert!(!parsed_requirement_group_contains_programming_options(
            Some(&incomplete_group),
            &parser
        ));
        assert!(!parsed_requirement_group_contains_programming_options(
            None, &parser
        ));
    }

