    #[test]
    fn parser_option_extraction_rows_cover_comma_lists_and_elective_support() {
        let owner = json!({
            "ownerId": "plan-a:pathway:path-a",
            "planId": "plan-a",
            "pathwayId": "path-a"
        });
        let blocks = vec![
            json!({
                "sourceUrl": "https://primary.example/requirements",
                "sourceRole": "degree-requirements",
                "parsedRequirementGroups": [{
                    "id": "group-1",
                    "label": "Choose a chemistry or math course",
                    "sourceRowText": "Choose one: MATH 100, CHEM 100",
                    "detectedOptionCue": "none",
                    "requirementType": "choose_one",
                    "requiredCount": 1,
                    "options": [
                        {"uwCourses": ["MATH 100"]},
                        {"equivalentUwCourseCodes": ["CHEM 100"]}
                    ]
                }]
            }),
            json!({
                "sourceUrl": "https://support.example/electives",
                "sourceRole": "elective-list",
                "sourceRoleStatus": "support",
                "supportOnly": true,
                "canCreateRequiredRows": false,
                "electiveListUwCourseCodes": ["engl 101", "ENGL 101"]
            }),
        ];

        let rows = build_parser_option_extraction_audit_rows_for_owner(&owner, &blocks);

        assert_eq!(rows.len(), 2);
        assert_eq!(
            rows[0].get("issue").and_then(Value::as_str),
            Some("unsafe-comma-list")
        );
        assert_eq!(
            rows[0].get("acceptedUwOptions"),
            Some(&json!(["CHEM 100", "MATH 100"]))
        );
        assert_eq!(
            rows[0].get("requiredCount").and_then(Value::as_str),
            Some("1")
        );
        assert_eq!(
            rows[1].get("emittedAs").and_then(Value::as_str),
            Some("elective-list-entry")
        );
        assert_eq!(rows[1].get("issue").and_then(Value::as_str), Some("none"));
        assert_eq!(rows[1].get("acceptedUwOptions"), Some(&json!(["ENGL 101"])));
        assert_eq!(
            parser_option_required_count(&json!({"minCourses": 1, "maxCourses": 1.0})),
            "1"
        );
        assert_eq!(
            parser_option_required_count(&json!({"requiredCount": 0, "selectionCount": 3})),
            "0"
        );
        assert_eq!(
            parser_option_required_count(&json!({"requiredCount": null, "selectionCount": 0})),
            "0"
        );
        assert_eq!(
            group_accepted_option_count(&json!({
                "options": [
                    {"categoryOption": []},
                    {"categoryOption": 0}
                ]
            })),
            1
        );
        assert_eq!(
            format_audit_credit_range(Some(&json!(5)), Some(&json!(5.0))),
            "5"
        );
        assert_eq!(
            format_audit_credit_range(Some(&json!({"count": 5})), Some(&json!({"count": 5}))),
            "[object Object]-[object Object]"
        );
        assert_eq!(
            parser_option_required_count(&json!({
                "minCourses": {"count": 1},
                "maxCourses": {"count": 1}
            })),
            "unknown"
        );
        assert_eq!(
            parser_option_required_count(&json!({
                "minCredits": {"count": 5},
                "maxCredits": {"count": 5}
            })),
            "[object Object]-[object Object] credits"
        );
        assert_eq!(
            parser_option_required_count(&json!({"minCredits": 5, "maxCredits": 5.0})),
            "5 credits"
        );
        assert_eq!(
            parser_option_required_count(&json!({"minCredits": 5, "maxCredits": 0})),
            "5 credits"
        );
    }

    #[test]
    fn generated_shape_comparison_flags_flattening_and_preserves_supported_groups() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        assert_eq!(
            normalize_shape_label(Some(&json!("\u{feff} Electrical \u{feff} Engineering "))),
            "electrical engineering"
        );
        let parsed_credit = json!({
            "requirementType": "choose_credits",
            "minCredits": 5,
            "maxCredits": 10,
            "approvedListKey": "ce-bs-approved-courses"
        });
        let generated_credit = json!({
            "requirementType": "choose_credits",
            "minCredits": 5,
            "maxCredits": 10,
            "approvedListKey": "ce-approved-courses"
        });
        assert_eq!(
            generated_group_shape_issue(&parsed_credit, Some(&generated_credit), &course_parser),
            "none"
        );
        let flattened_credit = json!({
            "requirementType": "choose_credits",
            "minCredits": 5,
            "maxCredits": 10,
            "approvedListKey": "ce-approved-courses",
            "requiredCount": 1
        });
        assert_eq!(
            generated_group_shape_issue(&parsed_credit, Some(&flattened_credit), &course_parser),
            "flattened-credit-bucket"
        );

        let parsed_options = json!({
            "requirementType": "choose_n",
            "options": [{"uwCourses": ["CSE 142"]}, {"uwCourses": ["CSE 143"]}]
        });
        let flattened_options = json!({
            "requirementType": "choose_n",
            "options": [{"uwCourses": ["CSE 142"]}]
        });
        assert_eq!(
            generated_group_shape_issue(&parsed_options, Some(&flattened_options), &course_parser),
            "flattened-option-group"
        );
        let parsed_category = json!({
            "requirementType": "choose_credits",
            "options": [{
                "optionKind": "category-option",
                "category": "Natural Science",
                "creditMin": 5,
                "creditMax": 7
            }]
        });
        let generated_category = json!({
            "requirementType": "choose_credits",
            "options": [{
                "optionKind": "category-option",
                "sourceCategory": "Natural Science",
                "creditMin": 5,
                "creditMax": 7
            }]
        });
        assert_eq!(
            generated_group_shape_issue(
                &parsed_category,
                Some(&generated_category),
                &course_parser
            ),
            "none"
        );
        let parsed_sequence = json!({
            "requirementType": "sequence_choice",
            "sequencePaths": [{
                "label": "Path A",
                "uwCourses": ["MATH 124"],
                "conditionalLabCourses": ["CHEM 142"]
            }]
        });
        let generated_sequence = json!({
            "requirementType": "sequence_choice",
            "sequencePaths": [{
                "label": "path a",
                "uwCourses": ["math 124"],
                "conditionalLabCourses": ["chem 142"]
            }]
        });
        assert_eq!(
            generated_group_shape_issue(
                &parsed_sequence,
                Some(&generated_sequence),
                &course_parser
            ),
            "none"
        );
        assert_eq!(
            generated_group_shape_issue(
                &parsed_sequence,
                Some(&json!({
                    "requirementType": "sequence_choice",
                    "sequencePaths": []
                })),
                &course_parser
            ),
            "flattened-sequence-choice"
        );
        assert!(parsed_group_has_generated_shape_audit_surface(
            &parsed_options
        ));
        assert!(!parsed_group_has_generated_shape_audit_surface(&json!({
            "requirementType": "other"
        })));
    }

