    #[test]
    fn generated_shape_audit_rows_summarize_candidates_and_source_backing() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let parsed_group = json!({
            "id": "group-a",
            "label": "Choose a computer science course",
            "sourceUrl": "https://example.test/requirements",
            "sourceRole": "degree-requirements",
            "supportOnly": false,
            "sourceSectionSchedulable": true,
            "requirementType": "choose_one",
            "requiredCount": 1,
            "options": [{"uwCourses": ["CSE 142"]}, {"uwCourses": ["CSE 143"]}]
        });
        let input = json!({
            "owner": {"ownerId": "plan-a", "planId": "plan-a"},
            "parsedGroup": parsed_group.clone(),
            "compactBlockGroup": {
                "requirementType": "choose_one",
                "requiredCount": 1,
                "options": [{"uwCourses": ["CSE 142"]}, {"uwCourses": ["CSE 143"]}]
            },
            "sourcePlanGroup": null,
            "runtimePlanGroup": null
        });

        let row = build_generated_shape_audit_group_row(&input, &course_parser);

        assert_eq!(row.get("issue").and_then(Value::as_str), Some("none"));
        assert_eq!(
            row.get("preservedShape").and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            row.get("canCreateScheduleRow").and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(
            row.get("primarySourceBacking").and_then(Value::as_bool),
            Some(true)
        );
        assert_eq!(row.get("uwCourses"), Some(&json!(["CSE 142", "CSE 143"])));
        assert!(
            row.get("generatedShape")
                .and_then(Value::as_str)
                .unwrap()
                .contains("source-plan=missing")
        );

        let missing = build_generated_shape_audit_group_row(
            &json!({"owner": {"ownerId": "plan-a"}, "parsedGroup": parsed_group.clone()}),
            &course_parser,
        );
        assert_eq!(
            missing.get("issue").and_then(Value::as_str),
            Some("flattened-option-group")
        );
    }

