    #[test]
    fn protected_sequence_expectation_api_matches_cjs_test_helper_results() {
        let parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let expected_sets = json!([["PHYS 114", "PHYS 115"], ["PHYS 121", "PHYS 122"]]);
        let not_required_blocks = json!([{
            "sourceLabel": "Biology BA catalog section",
            "snapshotLines": [
                "Bachelor of Arts degree with a major in Biology",
                "Physics: not required"
            ]
        }]);
        let not_required = protected_sequence_expectation_applies_for_test(
            &not_required_blocks,
            &expected_sets,
            &parser,
            std::path::Path::new("unused-source-root"),
        )
        .unwrap();
        assert_eq!(
            not_required.get("applies").and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            not_required.get("reason").and_then(Value::as_str),
            Some("scoped official source explicitly says PHYS is not required")
        );
        let string_snapshot_lines = json!([{"snapshotLines": "PHYS not required"}]);
        let string_lines_expectation = protected_sequence_expectation_applies_for_test(
            &string_snapshot_lines,
            &expected_sets,
            &parser,
            std::path::Path::new("unused-source-root"),
        )
        .unwrap();
        assert_eq!(
            string_lines_expectation
                .get("reason")
                .and_then(Value::as_str),
            Some("no explicit source exemption found")
        );

        let required_blocks = json!([{
            "sourceLabel": "Biology BS catalog section",
            "snapshotLines": [
                "Two quarters of physics (8-10 credits): one of the following:",
                "PHYS 114, PHYS 115",
                "PHYS 121, PHYS 122"
            ]
        }]);
        let required = protected_sequence_expectation_applies_for_test(
            &required_blocks,
            &expected_sets,
            &parser,
            std::path::Path::new("unused-source-root"),
        )
        .unwrap();
        assert_eq!(required.get("applies").and_then(Value::as_bool), Some(true));
        let unbacked_snapshot_text = json!([{"snapshotText": "PHYS 114 is required"}]);
        let unbacked_expectation = protected_sequence_expectation_applies_for_test(
            &unbacked_snapshot_text,
            &expected_sets,
            &parser,
            std::path::Path::new("unused-source-root"),
        )
        .unwrap();
        assert_eq!(
            unbacked_expectation.get("reason").and_then(Value::as_str),
            Some("no explicit source exemption found")
        );

        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let source_root = std::env::temp_dir().join(format!(
            "gator-guide-protected-sequence-helper-{}-{unique}",
            std::process::id()
        ));
        let snapshot_directory = source_root.join("snapshots");
        std::fs::create_dir_all(&snapshot_directory).unwrap();
        std::fs::write(
            snapshot_directory.join("physics.txt"),
            "PHYS not required for this program",
        )
        .unwrap();
        let snapshot_blocks = json!([{
            "snapshotPath": "snapshots/physics.txt",
            "snapshotText": "PHYS 114 is required"
        }]);
        let snapshot_expectation = protected_sequence_expectation_applies_for_test(
            &snapshot_blocks,
            &expected_sets,
            &parser,
            &source_root,
        )
        .unwrap();
        assert_eq!(
            snapshot_expectation.get("applies").and_then(Value::as_bool),
            Some(false)
        );
        std::fs::remove_dir_all(source_root).unwrap();
    }

