    #[test]
    fn credit_category_shape_row_preserves_missing_and_null_properties() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let missing = build_credit_category_shape_audit_row(
            &json!({"owner": {}, "group": {}}),
            &course_parser,
        );
        assert!(!missing.as_object().unwrap().contains_key("ownerId"));
        assert!(
            !missing
                .as_object()
                .unwrap()
                .contains_key("generatedArtifact")
        );
        assert!(
            missing
                .get("copyOnlyDebugText")
                .and_then(Value::as_str)
                .unwrap()
                .contains("Owner id: undefined")
        );

        let explicit_null = build_credit_category_shape_audit_row(
            &json!({
                "owner": {"ownerId": null},
                "group": {},
                "generatedArtifact": null
            }),
            &course_parser,
        );
        assert_eq!(explicit_null.get("ownerId"), Some(&Value::Null));
        assert_eq!(explicit_null.get("generatedArtifact"), Some(&Value::Null));

        let plan = json!({
            "requirementGroups": [{"id": "group-a", "requirementType": "choose_credits"}]
        });
        let missing_artifact_rows = build_credit_category_shape_rows_for_plan(
            &json!({"owner": {}, "plan": plan.clone()}),
            &course_parser,
        );
        assert_eq!(missing_artifact_rows.len(), 1);
        assert!(
            !missing_artifact_rows[0]
                .as_object()
                .unwrap()
                .contains_key("generatedArtifact")
        );
        let null_artifact_rows = build_credit_category_shape_rows_for_plan(
            &json!({"owner": {}, "plan": plan, "generatedArtifact": null}),
            &course_parser,
        );
        assert_eq!(null_artifact_rows.len(), 1);
        assert_eq!(
            null_artifact_rows[0].get("generatedArtifact"),
            Some(&Value::Null)
        );

        let owner_rows = build_credit_category_shape_audit_rows_for_owner(
            &json!({
                "owner": {"ownerId": "plan-a"},
                "sourcePlan": plan.clone(),
                "runtimePlan": plan
            }),
            &course_parser,
        );
        assert_eq!(owner_rows.len(), 2);
        assert_eq!(
            owner_rows
                .iter()
                .map(|row| row.get("generatedArtifact").and_then(Value::as_str))
                .collect::<Vec<_>>(),
            [
                Some("source/constants/transfer-planner-source/generated-major-plans.ts"),
                Some("source/constants/transfer-planner-source/student-runtime.generated.ts")
            ]
        );
    }

