    #[test]
    fn generated_source_seed_rows_cover_checklists_and_scoped_course_list_watchlist() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let checklist_rows = build_generated_source_seed_audit_rows_for_owner(
            &json!({
                "owner": {"ownerId": "plan-a", "planId": "plan-a"},
                "runtimePlan": {"applicationChecklist": [{
                    "title": "Programming prerequisite",
                    "sourceUrl": "https://example.test/degree",
                    "sourceRole": "degree-requirements",
                    "requirementGroup": {"options": [{
                        "uwCourses": ["CSE 142"],
                        "grcMatches": ["MATH 141"]
                    }]}
                }]},
                "primarySource": {
                    "url": "https://example.test/degree",
                    "role": "degree-requirements"
                },
                "canonicalGrcCourseCodes": ["MATH 141"]
            }),
            &course_parser,
        );
        assert_eq!(checklist_rows.len(), 1);
        assert_eq!(
            checklist_rows[0].get("uwCourse").and_then(Value::as_str),
            Some("CSE 142")
        );
        assert_eq!(
            checklist_rows[0]
                .get("grcMappingPath")
                .and_then(Value::as_str),
            Some("MATH 141")
        );
        assert_eq!(
            checklist_rows[0].get("issue").and_then(Value::as_str),
            Some("none")
        );

        let watchlist_rows = build_generated_source_seed_audit_rows_for_owner(
            &json!({
                "owner": {
                    "ownerId": "uw-seattle-computer-science",
                    "planId": "uw-seattle-computer-science"
                },
                "runtimePlan": {"grcCourseList": ["MATH 240", "MATH 240 "]},
                "runtimeGrcCourseList": ["MATH 240", "MATH 240"],
                "primarySource": {
                    "url": "https://example.test/cs-degree",
                    "role": "degree-requirements",
                    "isPrimaryDegreeRequirementsLink": true
                },
                "parsedBlocks": [{
                    "sourceRole": "degree-requirements",
                    "parsedUwCourseCodes": ["CSE 142"]
                }],
                "equivalencyRules": [{
                    "sourceSchoolId": "grc",
                    "targetSchoolIds": ["uw-seattle"],
                    "targetCourseCodes": ["CSE 142"],
                    "sourceCourseSets": [["MATH 240"]],
                    "type": "direct-course"
                }],
                "canonicalGrcCourseCodes": ["MATH 240"]
            }),
            &course_parser,
        );
        assert_eq!(watchlist_rows.len(), 2);
        assert_eq!(
            watchlist_rows[0].get("uwCourse").and_then(Value::as_str),
            Some("CSE 142")
        );
        assert_eq!(
            watchlist_rows[0].get("sourceScope").and_then(Value::as_str),
            Some("primary-schedulable-course-list")
        );
        assert_eq!(
            watchlist_rows[0].get("issue").and_then(Value::as_str),
            Some("none")
        );

        let falsy_runtime_plan_rows = build_generated_source_seed_audit_rows_for_owner(
            &json!({
                "owner": {
                    "ownerId": "uw-seattle-computer-science",
                    "planId": "uw-seattle-computer-science"
                },
                "runtimePlan": false,
                "runtimeGrcCourseList": ["MATH 240"],
                "canonicalGrcCourseCodes": ["MATH 240"]
            }),
            &course_parser,
        );
        assert!(falsy_runtime_plan_rows.is_empty());
        let preserved_falsey_schedule_flag = build_generated_source_seed_audit_rows_for_owner(
            &json!({
                "owner": {"ownerId": "plan-a", "planId": "plan-a"},
                "runtimePlan": {"applicationChecklist": [{
                    "title": "MATH 141 prerequisite",
                    "grcCourses": ["MATH 141"],
                    "canCreateScheduleRow": 0
                }]}
            }),
            &course_parser,
        );
        assert_eq!(preserved_falsey_schedule_flag.len(), 1);
        assert_eq!(
            preserved_falsey_schedule_flag[0].get("canCreateScheduleRow"),
            Some(&json!(0))
        );
        assert!(
            preserved_falsey_schedule_flag[0]
                .get("copyOnlyDebugText")
                .and_then(Value::as_str)
                .unwrap()
                .contains("Can create schedule row: no")
        );
    }

