    #[test]
    fn uw_equivalency_resolution_prefers_direct_then_aligned_sequence_over_fallbacks() {
        let rules = vec![
            json!({
                "sourceSchoolId": "grc",
                "targetSchoolIds": ["uw-seattle"],
                "targetCourseCodes": ["CSE 142"],
                "sourceCourseSets": [["MATH 141"]],
                "type": "direct-course"
            }),
            json!({
                "sourceSchoolId": "grc",
                "targetSchoolIds": ["uw-seattle"],
                "targetCourseCodes": ["CSE 142", "CSE 143"],
                "sourceCourseSets": [["MATH 142", "MATH 143"]],
                "type": "sequence"
            }),
            json!({
                "sourceSchoolId": "grc",
                "targetSchoolIds": ["uw-seattle"],
                "targetCourseCodes": ["CSE 142", "CSE 143"],
                "sourceCourseSets": [["MATH 144", "MATH 145"]],
                "type": "elective-credit"
            }),
        ];
        let canonical = [
            "MATH 141".to_string(),
            "MATH 142".to_string(),
            "MATH 143".to_string(),
            "MATH 144".to_string(),
            "MATH 145".to_string(),
        ];
        assert_eq!(
            grc_equivalents_for_uw_course(&json!("CSE 142"), &rules, None, &canonical),
            vec!["MATH 141".to_string()]
        );
        assert_eq!(
            grc_equivalents_for_uw_course(&json!("CSE 143"), &rules[1..], None, &canonical),
            vec!["MATH 143".to_string()]
        );
        assert!(
            grc_equivalents_for_uw_course(
                &json!("CSE 142"),
                &rules,
                None,
                &["MATH 142".to_string(), "MATH 144".to_string()]
            )
            .is_empty(),
            "filtering a preferred direct rule must not fall through to sequence or fallback rules"
        );
    }

