    #[test]
    fn single_equivalency_audit_row_constructor_preserves_watchlist_fallbacks() {
        let input = json!({
            "grcCourse": "math 123",
            "uwEquivalent": "MATH 124",
            "watchlist": true,
            "usedByOwnerId": "owner-a",
            "usedByRequirement": "MATH 123",
            "mappedAs": "required"
        });
        let row = build_single_equivalency_audit_row(&input, &[], &[]);
        assert_eq!(
            row.as_object()
                .unwrap()
                .keys()
                .map(String::as_str)
                .collect::<Vec<_>>(),
            [
                "grcCourse",
                "uwEquivalent",
                "ruleType",
                "ruleId",
                "sourceKind",
                "sourceRow",
                "sourceUrl",
                "effectiveDateLabel",
                "warning",
                "usedByOwnerId",
                "usedByRequirement",
                "mappedAs",
                "issue",
                "copyOnlyDebugText"
            ]
        );

        assert_eq!(
            row.get("grcCourse").and_then(Value::as_str),
            Some("MATH 123")
        );
        assert_eq!(
            row.get("uwEquivalent").and_then(Value::as_str),
            Some("MATH 124")
        );
        assert_eq!(row.get("ruleType").and_then(Value::as_str), Some("single"));
        assert_eq!(row.get("ruleId"), Some(&Value::Null));
        assert_eq!(
            row.get("issue").and_then(Value::as_str),
            Some("missing-equivalency")
        );
        assert_eq!(
            row.get("usedByOwnerId").and_then(Value::as_str),
            Some("owner-a")
        );
        assert!(
            row.get("copyOnlyDebugText")
                .and_then(Value::as_str)
                .is_some_and(|text| text.contains("Issue: missing-equivalency"))
        );

        let missing_context = json!({
            "grcCourse": "MATH 123",
            "uwEquivalent": "MATH 124",
            "watchlist": true
        });
        let missing_context_row = build_single_equivalency_audit_row(&missing_context, &[], &[]);
        assert!(missing_context_row.get("usedByOwnerId").is_none());
        assert!(missing_context_row.get("usedByRequirement").is_none());
        assert!(missing_context_row.get("mappedAs").is_none());
        assert_eq!(
            missing_context_row
                .as_object()
                .unwrap()
                .keys()
                .map(String::as_str)
                .collect::<Vec<_>>(),
            [
                "grcCourse",
                "uwEquivalent",
                "ruleType",
                "ruleId",
                "sourceKind",
                "sourceRow",
                "sourceUrl",
                "effectiveDateLabel",
                "warning",
                "issue",
                "copyOnlyDebugText"
            ]
        );
        assert!(missing_context_row
            .get("copyOnlyDebugText")
            .and_then(Value::as_str)
            .is_some_and(|text| text.contains(
                "Used by owner id: undefined Used by requirement: undefined Mapped as required/option/hidden: undefined"
            )));

        let explicit_null_context = json!({
            "grcCourse": "MATH 123",
            "uwEquivalent": "MATH 124",
            "watchlist": true,
            "usedByOwnerId": null
        });
        let explicit_null_row =
            build_single_equivalency_audit_row(&explicit_null_context, &[], &[]);
        assert_eq!(explicit_null_row.get("usedByOwnerId"), Some(&Value::Null));
        assert!(
            explicit_null_row
                .get("copyOnlyDebugText")
                .and_then(Value::as_str)
                .is_some_and(|text| text.contains("Used by owner id: null"))
        );
    }

    #[test]
    fn grc_equivalence_matching_preserves_direct_and_aligned_sequence_precedence() {
        let rules = vec![
            json!({
                "sourceSchoolId": "grc",
                "targetSchoolIds": ["uw-seattle"],
                "targetCourseCodes": ["CSE 143"],
                "sourceCourseSets": [["MATH 250"]],
                "type": "course-list"
            }),
            json!({
                "sourceSchoolId": "grc",
                "targetSchoolIds": ["uw-seattle"],
                "targetCourseCodes": ["CSE 142", "CSE 143"],
                "sourceCourseSets": [["MATH 241", "MATH 242"]],
                "type": "sequence"
            }),
            json!({
                "sourceSchoolId": "grc",
                "targetSchoolIds": ["uw-seattle"],
                "targetCourseCodes": ["CSE 143"],
                "sourceCourseSets": [["MATH 243"]],
                "type": "direct-course"
            }),
            json!({
                "sourceSchoolId": "grc",
                "targetSchoolIds": ["uw-seattle"],
                "targetCourseCodes": ["CSE 160"],
                "sourceCourseSets": [["BIOL 180"]],
                "type": "direct-course"
            }),
        ];
        let canonical_grc_courses = vec![
            "MATH 241".to_string(),
            "MATH 242".to_string(),
            "MATH 243".to_string(),
            "MATH 250".to_string(),
            "BIOL 180".to_string(),
        ];
        assert_eq!(
            grc_equivalents_for_uw_course(&json!("CSE 143"), &rules, None, &canonical_grc_courses),
            vec!["MATH 243".to_string()]
        );
        let sequence_only = vec![rules[1].clone()];
        assert_eq!(
            grc_equivalents_for_uw_course(
                &json!("CSE 143"),
                &sequence_only,
                None,
                &canonical_grc_courses
            ),
            vec!["MATH 242".to_string()]
        );
        assert_eq!(
            grc_equivalents_for_uw_course(
                &json!("CSE 142"),
                &rules[2..],
                Some(&json!("CSE 143")),
                &canonical_grc_courses
            ),
            vec!["MATH 243".to_string()]
        );
        let alias_rows = vec![json!({
            "uwCourseCode": "CSE 142",
            "aliasTargetCourseCode": "CSE 143"
        })];
        assert_eq!(
            grc_equivalents_for_uw_courses(
                &[json!("CSE 142"), json!("CSE 143"), json!("CSE 143")],
                &rules,
                &alias_rows,
                &canonical_grc_courses
            ),
            vec!["MATH 243".to_string()]
        );
        assert_eq!(
            grc_equivalents_for_uw_courses(
                &[json!("CSE 160"), json!("CSE 143"), json!("CSE 160")],
                &rules,
                &[],
                &canonical_grc_courses
            ),
            vec!["BIOL 180".to_string(), "MATH 243".to_string()]
        );

        let parsed_blocks = vec![
            json!({
                "sourceRole": "degree-requirements",
                "parsedUwCourseCodes": ["CSE 142"],
                "parsedRequirementAtomCandidates": [{"uwCourseCode": "CSE 143"}],
                "parsedRequirementGroups": [{"options": [{"displayCourseCodes": ["CSE 144"]}]}]
            }),
            json!({
                "sourceRole": "approved-course-list",
                "parsedUwCourseCodes": ["CSE 145"]
            }),
        ];
        assert_eq!(
            schedulable_parsed_uw_course_codes(&parsed_blocks),
            vec![
                "CSE 142".to_string(),
                "CSE 143".to_string(),
                "CSE 144".to_string()
            ]
        );
    }

    #[test]
    fn checklist_course_codes_and_generated_seed_issue_classification_match_source_rules() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let group_item = json!({
            "title": "Fallback CSE 199",
            "requirementGroup": {"options": [{
                "uwCourses": ["cse 142"],
                "equivalentUwCourseCodes": ["CSE 143"],
                "displayCourseCodes": ["CSE 144"],
                "grcMatches": ["MATH 143"]
            }]},
            "grcCourses": ["MATH 141"],
            "alternatives": [["MATH 142"]]
        });
        assert_eq!(
            checklist_item_uw_course_codes(&group_item, &course_parser),
            vec![
                "CSE 142".to_string(),
                "CSE 143".to_string(),
                "CSE 144".to_string()
            ]
        );
        assert_eq!(
            checklist_item_grc_course_codes(&group_item, &course_parser),
            vec![
                "MATH 141".to_string(),
                "MATH 142".to_string(),
                "MATH 143".to_string()
            ]
        );
        assert!(checklist_item_creates_generated_schedule_row(
            &group_item,
            &course_parser
        ));
        let fallback_item = json!({"title": "Complete CSE 145", "note": "or CSE 146"});
        assert_eq!(
            checklist_item_uw_course_codes(&fallback_item, &course_parser),
            vec!["CSE 145".to_string(), "CSE 146".to_string()]
        );

        assert_eq!(
            classify_generated_seed_issue(&json!({
                "sourceRole": "approved-course-list",
                "generatedGrcCourseCodes": ["MATH 141"],
                "canCreateScheduleRow": true
            })),
            "approved-list-generated-required-row"
        );
        assert_eq!(
            classify_generated_seed_issue(&json!({
                "sourceRole": "degree-requirements",
                "sourceScope": "support-only",
                "sourceUrl": "https://example.test/support",
                "generatedGrcCourseCodes": ["MATH 141"],
                "canCreateScheduleRow": true
            })),
            "support-metadata-became-required"
        );
        assert_eq!(
            classify_generated_seed_issue(&json!({
                "sourceRole": "degree-requirements",
                "sourceScope": "primary-schedulable",
                "sourceUrl": "https://example.test/primary",
                "generatedGrcCourseCodes": ["MATH 141"],
                "canCreateScheduleRow": true
            })),
            "none"
        );
        assert_eq!(
            classify_generated_seed_issue(&json!({
                "sourceRole": "approved-course-list",
                "generatedGrcCourseCodes": ["MATH 141"],
                "canCreateScheduleRow": 0
            })),
            "approved-list-generated-required-row",
            "only the literal boolean false suppresses the CJS schedule surface"
        );
        assert_eq!(
            classify_generated_seed_issue(&json!({
                "sourceRole": "approved-course-list",
                "generatedGrcCourseCodes": ["MATH 141"],
                "canCreateScheduleRow": false
            })),
            "none"
        );
    }

