    #[test]
    fn runtime_coverage_helpers_include_generated_groups_and_match_context() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let plan = json!({
            "applicationChecklist": [{"title": "Application item"}],
            "requirementGroups": [{
                "id": "choice-1",
                "label": "Chemistry sequence",
                "requirementType": "choose_one",
                "options": [{
                    "id": "chem-a",
                    "displayCourseCodes": ["CHEM 142"],
                    "grcMatches": ["CHEM 142"]
                }, {
                    "id": "chem-b",
                    "uwCourses": ["CHEM 143"]
                }]
            }]
        });
        let items = runtime_checklist_items_for_coverage(&plan);
        assert_eq!(items.len(), 2);
        assert_eq!(
            items[1]
                .get("generatedFromRequirementGroup")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert!(runtime_requirement_group_represents_choice(
            items[1].get("requirementGroup").unwrap()
        ));
        assert_eq!(
            get_option_uw_course_codes_for_coverage(
                &json!({"displayCourseCodes": ["CSE 142"], "uwCourses": ["CSE 143"]})
            ),
            vec!["CSE 142".to_string(), "CSE 143".to_string()]
        );
        assert_eq!(
            get_option_grc_course_codes_for_coverage(
                &json!({"grcMatches": ["MATH 124 or CHEM 142"]}),
                &course_parser
            ),
            vec!["CHEM 142".to_string(), "MATH 124".to_string()]
        );
        assert!(runtime_item_matches_parsed_requirement_context(
            &items[1],
            Some(&Value::Null)
        ));
        assert!(runtime_item_matches_parsed_requirement_context(
            &items[1], None
        ));
        assert!(runtime_item_matches_parsed_requirement_context(
            &items[1],
            Some(&json!(""))
        ));
        assert!(runtime_item_matches_parsed_requirement_context(
            &items[1],
            Some(&json!("Chemistry requirement"))
        ));
        assert!(runtime_item_matches_parsed_requirement_context(
            &items[1],
            Some(&json!("course requirement"))
        ));
        assert!(visible_prompt_option_group_shows_option(
            &json!({
                "option": {"id": "chem-a", "displayCourseCodes": ["CHEM 142"]},
                "groupId": "choice-1",
                "visibleSelectionPromptOptionGroups": [{"id": "choice-1", "options": []}]
            }),
            &course_parser
        ));
        assert!(visible_prompt_option_group_shows_option(
            &json!({
                "option": {"displayCourseCodes": ["CHEM 142"]},
                "groupId": "other-group",
                "visibleSelectionPromptOptionGroups": [{
                    "id": "visible-choice",
                    "options": [{"uwCourses": ["CHEM 142"]}]
                }]
            }),
            &course_parser
        ));
    }

    #[test]
    fn visible_and_scheduled_course_sets_preserve_source_requirement_rules() {
        let quarter_plan = json!([
            {
                "phase": "planned",
                "courses": [{
                    "label": "CHEM 142",
                    "optionGroup": {"id": "required", "isSelectionPrompt": false}
                }, {
                    "label": "CHEM 143",
                    "satisfiesSourceBackedUwRequirement": false,
                    "optionGroup": {"id": "not-required"}
                }, {
                    "label": "CHEM 144",
                    "optionGroup": {"id": "prompt", "isSelectionPrompt": true}
                }, {
                    "label": "CHEM 145",
                    "optionGroup": {"id": ""}
                }, {
                    "label": "CHEM 146",
                    "optionGroup": {"id": "required-2"}
                }, {
                    "label": "CHEM 149",
                    "satisfiesSourceBackedUwRequirement": 0,
                    "optionGroup": {"id": "non-boolean-false"}
                }, {
                    "label": "CHEM 148",
                    "optionGroup": {"id": "truthy-prompt", "isSelectionPrompt": "yes"}
                }, {
                    "label": "CHEM 150",
                    "optionGroup": {"id": 0, "isSelectionPrompt": 0}
                }]
            }, {
                "phase": "completed",
                "courses": [{"label": "CHEM 147", "optionGroup": {"id": "completed"}}]
            }
        ]);
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        assert_eq!(
            visible_planned_course_codes(&quarter_plan, &course_parser),
            vec![
                "CHEM 142", "CHEM 143", "CHEM 144", "CHEM 145", "CHEM 146", "CHEM 148", "CHEM 149",
                "CHEM 150"
            ]
        );
        let mut scheduled = scheduled_course_codes_for_coverage(&quarter_plan, &course_parser)
            .into_iter()
            .collect::<Vec<_>>();
        scheduled.sort();
        assert_eq!(
            scheduled,
            vec!["CHEM 142", "CHEM 146", "CHEM 148", "CHEM 149"]
        );
        assert_eq!(
            visible_selection_prompt_option_groups_for_coverage(&quarter_plan),
            vec![
                json!({"id": "prompt", "isSelectionPrompt": true}),
                json!({"id": "truthy-prompt", "isSelectionPrompt": "yes"})
            ]
        );
        assert_eq!(
            visible_selection_prompt_option_group_ids(&[
                json!({"id": "prompt"}),
                json!({"id": "prompt"}),
                json!({"id": 0}),
                json!({"id": "0"}),
                json!({"id": 1}),
                json!({"id": "1"}),
                json!({"id": [1]}),
                json!({"id": [1]}),
                json!({})
            ]),
            vec![
                json!("prompt"),
                json!("0"),
                json!(1),
                json!("1"),
                json!([1]),
                json!([1])
            ]
        );

        let owner = json!({"ownerId": "plan-a", "planId": "plan-a"});
        let context = json!({
            "parsedBlocks": [{
                "sourceUrl": "https://example.test/math",
                "sourceRole": "degree-requirements",
                "parsedRequirementGroups": [{"id": "math", "label": "Math"}],
                "parsedRequirementCourses": [{
                    "requirementGroupId": "math",
                    "courseCode": "MATH 124"
                }]
            }],
            "runtimePlan": {
                "applicationChecklist": [{
                    "sourceUrl": "https://example.test/math",
                    "requirementGroup": {
                        "id": "prompt",
                        "options": [{"id": "unselected", "uwCourses": ["MATH 124"]}]
                    },
                    "selectedRequirementOptionIds": [],
                    "unselectedRequirementOptionIds": ["unselected"]
                }]
            },
            "quarterPlan": quarter_plan,
            "equivalencyRules": []
        });
        let coverage_rows = build_coverage_rows_for_owner(&owner, &context, &course_parser);
        assert_eq!(coverage_rows.len(), 1);
        assert_eq!(
            coverage_rows[0]
                .get("representedUnselectedRuntimeOption")
                .and_then(Value::as_bool),
            Some(true)
        );

        let mut explicit_empty_prompt_context = context.clone();
        let context_object = explicit_empty_prompt_context.as_object_mut().unwrap();
        context_object.insert("visibleSelectionPromptOptionGroups".to_string(), json!([]));
        context_object.insert(
            "visibleSelectionPromptOptionGroupIds".to_string(),
            json!([]),
        );
        let explicit_empty_rows =
            build_coverage_rows_for_owner(&owner, &explicit_empty_prompt_context, &course_parser);
        assert_eq!(
            explicit_empty_rows[0]
                .get("representedUnselectedRuntimeOption")
                .and_then(Value::as_bool),
            Some(false)
        );
    }

