    #[test]
    fn protected_requirement_rows_keep_pathway_and_schedule_regressions() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let context = json!({
            "primarySourceUrl": "https://example.test/math",
            "runtimePlan": {"title": "Mathematics pathway", "campusId": "uw-seattle"},
            "generatedRuntimeCourseCodes": ["ACCT 120", "ACCT 121"],
            "visibleCourseCodeSet": ["ACCT 120", "ACCT 121"],
            "scheduledCourseCodeSet": ["ACCT 120", "ACCT 121"]
        });
        let rows = build_protected_requirement_rows(
            &json!("plan-a"),
            Some(&json!("data")),
            &[json!([
                "Math choice",
                ["MATH 124"],
                ["ACCT 120", "ACCT 121"],
                "choose_one: 1 of 2"
            ])],
            &context,
            &course_parser,
        );
        assert_eq!(rows.len(), 1);
        assert_eq!(
            rows[0].get("ownerId").and_then(Value::as_str),
            Some("plan-a:pathway:data")
        );
        assert_eq!(
            rows[0].get("majorTitle").and_then(Value::as_str),
            Some("Mathematics pathway")
        );
        assert_eq!(
            rows[0].get("issueType").and_then(Value::as_str),
            Some("over-scheduled-alternatives")
        );
        assert_eq!(
            rows[0]
                .get("protectedRegressionRow")
                .and_then(Value::as_bool),
            Some(true)
        );
        assert!(
            rows[0]
                .get("hiddenInternalReason")
                .is_some_and(Value::is_null)
        );
        assert_eq!(
            rows[0].get("copyOnlyDebugText").and_then(Value::as_str),
            Some(
                "[copy-only requirement audit] UW requirement: Math choice GRC equivalent: ACCT 120, ACCT 121 Visible in plan: yes Hidden reason: none"
            )
        );

        let derived_context = json!({
            "runtimePlan": {
                "applicationChecklist": [{"grcCourses": ["ACCT 120", "ACCT 121"]}]
            },
            "quarterPlan": [{
                "phase": "planned",
                "courses": [{
                    "label": "ACCT 120",
                    "optionGroup": {
                        "id": "prompt-group",
                        "isSelectionPrompt": true,
                        "scheduledSatisfyingCourseCodes": ["ACCT 121"]
                    }
                }, {
                    "label": "ACCT 121",
                    "optionGroup": {"id": "selected-group", "isSelectionPrompt": false}
                }]
            }]
        });
        let derived_rows = build_protected_requirement_rows(
            &json!("plan-a"),
            None,
            &[json!([
                "Math choice",
                ["MATH 124"],
                ["ACCT 120", "ACCT 121"],
                "choose_one: 1 of 2"
            ])],
            &derived_context,
            &course_parser,
        );
        assert!(
            derived_rows[0]
                .get("generatedRuntimeRow")
                .and_then(Value::as_bool)
                == Some(true)
        );
        assert!(
            derived_rows[0]
                .get("visibleInTransferOnlyQuarterPlan")
                .and_then(Value::as_bool)
                == Some(true)
        );
        assert!(derived_rows[0].get("issueType").is_some_and(Value::is_null));
    }

    #[test]
    fn coverage_detects_unselected_options_and_selected_grouped_alternatives() {
        let course_parser = super::super::requirement_course_codes::CourseCodeParser::default();
        let input = json!({
            "sourceUrl": "https://example.test/chemistry",
            "runtimePlan": {
                "applicationChecklist": [{
                    "title": "Chemistry sequence",
                    "sourceUrl": "https://example.test/chemistry",
                    "grcCourses": ["CHEM 142"],
                    "selectedRequirementOptionIds": ["chem-a"],
                    "unselectedRequirementOptionIds": ["chem-b"],
                    "requirementGroup": {
                        "id": "chemistry-choice",
                        "requirementType": "choose_one",
                        "options": [{
                            "id": "chem-a",
                            "grcMatches": ["CHEM 142"]
                        }, {
                            "id": "chem-b",
                            "grcMatches": ["CHEM 143"]
                        }]
                    }
                }]
            },
            "parsedUwCourseCodes": ["CHEM 143"],
            "grcEquivalents": ["CHEM 143"],
            "visibleCourseCodeSet": ["CHEM 142"],
            "parsedRequirementContext": "Chemistry sequence",
            "visibleSelectionPromptOptionGroups": [],
            "visibleSelectionPromptOptionGroupIds": []
        });
        assert!(is_parsed_course_represented_by_unselected_runtime_option(
            &input,
            &course_parser
        ));

        let selected_alternative = json!({
            "sourceUrl": "https://example.test/chemistry",
            "runtimePlan": {
                "applicationChecklist": [{
                    "title": "Chemistry sequence",
                    "sourceUrl": "https://example.test/chemistry",
                    "grcCourses": ["CHEM 142"],
                    "alternatives": [["CHEM 143"]]
                }]
            },
            "groupedChoiceCardinality": "choose_one: 1 of 2",
            "grcEquivalents": ["CHEM 143"],
            "visibleCourseCodeSet": ["CHEM 142"],
            "parsedRequirementContext": "Chemistry sequence"
        });
        assert!(
            is_parsed_choice_represented_by_selected_runtime_alternative(
                &selected_alternative,
                &course_parser
            )
        );
        let wrong_context = json!({
            "sourceUrl": "https://example.test/chemistry",
            "runtimePlan": selected_alternative["runtimePlan"].clone(),
            "groupedChoiceCardinality": "choose_one: 1 of 2",
            "grcEquivalents": ["CHEM 143"],
            "visibleCourseCodeSet": ["CHEM 142"],
            "parsedRequirementContext": "Physics sequence"
        });
        assert!(
            !is_parsed_choice_represented_by_selected_runtime_alternative(
                &wrong_context,
                &course_parser
            )
        );
    }

    #[test]
    fn coverage_classification_preserves_grouped_and_contextual_rules() {
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("choose_one: 2-4 of 5"))),
            Some(2.0)
        );
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("sequence_choice: 1 of 3"))),
            None
        );
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("\u{feff}sequence_choice: 1 of 3"))),
            None
        );
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("choose_one:\u{feff}2\u{00a0}of 5"))),
            Some(2.0)
        );
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("choose_one:\u{0085}2\u{0085}of 5"))),
            None
        );
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("sequence_choiceX: 2 of 3"))),
            Some(2.0)
        );
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("\u{0085}sequence_choice: 1 of 3"))),
            Some(1.0)
        );
        assert_eq!(
            parse_grouped_choice_max(Some(&json!("choose_one: 2 ofx 5"))),
            None
        );
        assert_eq!(parse_grouped_choice_max(Some(&json!("not grouped"))), None);
        assert_eq!(
            parse_grouped_choice_max(Some(&json!(
                "choose_one: 9007199254740993 of 9007199254740994"
            ))),
            Some(9_007_199_254_740_992.0)
        );

        assert_eq!(
            classify_coverage_issue(&json!({
                "groupedChoiceMax": 2,
                "visibleCourseCodes": ["MATH 124"],
                "scheduledVisibleCourseCodes": ["MATH 124", "MATH 125", "MATH 126"],
                "grcEquivalents": ["MATH 124"],
                "generatedRuntimeRow": true,
                "visibleInTransferOnlyPlan": true
            })),
            Some("over-scheduled-alternatives")
        );
        assert_eq!(
            classify_coverage_issue(&json!({
                "groupedChoiceMax": 1,
                "visibleCourseCodes": ["MATH 124", "MATH 125"],
                "scheduledVisibleCourseCodes": [],
                "grcEquivalents": ["MATH 124"],
                "generatedRuntimeRow": true,
                "visibleInTransferOnlyPlan": true
            })),
            None
        );
        assert_eq!(
            classify_coverage_issue(&json!({
                "parsedUwCourseCodes": ["MATH 124"],
                "grcEquivalents": [],
                "visibleCourseCodes": []
            })),
            None
        );
        assert_eq!(
            classify_coverage_issue(&json!({
                "grcEquivalents": ["MATH 124"],
                "generatedRuntimeRow": true,
                "visibleInTransferOnlyPlan": false,
                "visibleCourseCodes": []
            })),
            Some("missing-detected-course")
        );
        assert_eq!(
            classify_coverage_issue(&json!({
                "representedUnselectedRuntimeOption": true,
                "grcEquivalents": ["MATH 124"],
                "generatedRuntimeRow": false,
                "visibleInTransferOnlyPlan": false
            })),
            None
        );
        assert_eq!(
            get_hidden_reason(&json!({
                "representedUnselectedRuntimeOption": true,
                "grcEquivalents": ["MATH 124"]
            }))
            .as_str(),
            Some(
                "Source course is represented as an unselected option in a generated runtime option group."
            )
        );
        assert!(is_non_schedulable_contextual_source_row(&json!({
            "uwRequirementLabel": "Relevant engineering electives",
            "sourceHeading": "These do not count toward the required credits."
        })));
        assert!(!is_non_schedulable_contextual_source_row(&json!({
            "uwRequirementLabel": "Exploratory\u{0085}engineering electives",
            "sourceHeading": "These do not count toward the required credits."
        })));
        assert!(is_non_schedulable_contextual_source_row(&json!({
            "uwRequirementLabel": "Relevant engineering electives",
            "sourceHeading": "These do not count toward\u{0085}required credits."
        })));
        let within_js_regex_limit = format!(
            "These do not count toward{}required credits.",
            "😀".repeat(40)
        );
        let beyond_js_regex_limit = format!(
            "These do not count toward{}required credits.",
            "😀".repeat(41)
        );
        assert!(is_non_schedulable_contextual_source_row(&json!({
            "uwRequirementLabel": "Relevant engineering electives",
            "sourceHeading": within_js_regex_limit
        })));
        assert!(!is_non_schedulable_contextual_source_row(&json!({
            "uwRequirementLabel": "Relevant engineering electives",
            "sourceHeading": beyond_js_regex_limit
        })));
    }

