    #[test]
    fn parser_prerequisite_filter_rows_flag_only_unbacked_emitted_courses() {
        let owner = json!({"ownerId": "plan-a", "planId": "plan-a"});
        let block = json!({
            "sourceUrl": "https://example.test/prerequisites",
            "parsedRequirementCourses": [
                {"optionRole": "required", "courseCode": "CHEM 120"},
                {"optionRole": "required", "courseCode": "MATH 122"},
                {"optionRole": "required", "courseCode": "CSE 142"}
            ],
            "sourceSectionFilterAuditRows": [
                {
                    "sectionTitle": "Prerequisite table",
                    "rawLine": "CHEM 120",
                    "courseCodesExtracted": ["CHEM 120"],
                    "detectedSectionRole": "upper-division-prerequisite-table",
                    "schedulable": false,
                    "reason": "non-schedulable table"
                },
                {
                    "sectionTitle": "Prerequisite table",
                    "rawLine": "MATH 122",
                    "courseCodesExtracted": ["MATH 122"],
                    "detectedSectionRole": "upper-division-prerequisite-table",
                    "schedulable": false,
                    "reason": "non-schedulable table"
                },
                {
                    "sectionTitle": "Primary requirements",
                    "rawLine": "CSE 142",
                    "courseCodesExtracted": ["CSE 142"],
                    "detectedSectionRole": "degree-requirements",
                    "schedulable": true,
                    "reason": "primary row"
                }
            ]
        });

        assert_eq!(
            build_source_scope_emission_kind(&block, &json!("CHEM 120")),
            "required-row"
        );
        let overlapping_support_evidence = json!({
            "sourceRole": "approved-course-list",
            "canCreateApprovedFilters": true,
            "approvedFilterUwCourseCodes": ["CSE 142"],
            "parsedRequirementGroups": [{
                "options": [{"uwCourses": ["CSE 142"]}]
            }]
        });
        assert_eq!(
            build_source_scope_emission_kind(&overlapping_support_evidence, &json!("CSE 142")),
            "option-group"
        );
        let rows = build_parser_prerequisite_filter_audit_rows_for_owner(&owner, &[block]);

        assert_eq!(rows.len(), 3);
        assert_eq!(
            rows[0].get("issue").and_then(Value::as_str),
            Some("prerequisite-table-emitted-requirement")
        );
        assert_eq!(rows[1].get("issue").and_then(Value::as_str), Some("none"));
        assert_eq!(rows[2].get("issue").and_then(Value::as_str), Some("none"));
        assert!(
            rows[0]
                .get("copyOnlyDebugText")
                .and_then(Value::as_str)
                .unwrap()
                .contains("Course codes extracted: CHEM 120")
        );
    }

