    #[test]
    fn hidden_unmapped_mapping_rows_respect_plan_presence_and_visibility() {
        let coverage = json!({
            "requirementType": "hidden-unmapped",
            "visibleInPlan": false,
            "mappedGrcEquivalentPath": []
        });
        let rows = build_hidden_unmapped_mapping_regression_rows(
            true,
            Some(&coverage),
            true,
            &["PHYS 301".to_string()],
        );

        assert_eq!(rows.len(), 2);
        assert_eq!(rows[0].get("eligible").and_then(Value::as_bool), Some(true));
        assert_eq!(rows[0].get("issue").and_then(Value::as_str), Some("none"));
        assert_eq!(
            rows[1].get("eligible").and_then(Value::as_bool),
            Some(false)
        );
        assert_eq!(
            rows[1].get("actualMapping").and_then(Value::as_str),
            Some("PHYS 301")
        );
        assert_eq!(
            rows[1].get("issue").and_then(Value::as_str),
            Some("fake-equivalency")
        );

        let missing_row = build_hidden_unmapped_mapping_regression_rows(true, None, false, &[]);
        assert_eq!(missing_row.len(), 1);
        assert_eq!(
            missing_row[0].get("actualMapping").and_then(Value::as_str),
            Some("missing coverage row")
        );
        assert_eq!(
            missing_row[0].get("issue").and_then(Value::as_str),
            Some("fake-equivalency")
        );
        assert!(build_hidden_unmapped_mapping_regression_rows(false, None, false, &[]).is_empty());
    }

