    #[test]
    fn audit_failure_diagnostics_preserve_modes_caps_and_regression_details() {
        let mapping_rows = (0..121)
            .map(|index| {
                json!({
                    "issue": "missing-equivalency",
                    "copyOnlyDebugText": format!("mapping-{index}")
                })
            })
            .collect::<Vec<_>>();
        let mapping_report = json!({"mappingRegressionRows": mapping_rows});
        let mapping_lines = build_source_backed_audit_failure_diagnostic_lines(
            SourceBackedAuditMode::Mapping,
            false,
            &mapping_report,
        );
        assert_eq!(mapping_lines.len(), 240);
        assert_eq!(
            mapping_lines[0],
            "Mapping regression failed: missing-equivalency"
        );
        assert_eq!(mapping_lines[1], "- mapping-0");
        assert_eq!(mapping_lines[239], "- mapping-119");
        assert!(
            build_source_backed_audit_failure_diagnostic_lines(
                SourceBackedAuditMode::Mapping,
                true,
                &mapping_report
            )
            .is_empty()
        );
        let coercion_report = json!({
            "mappingRegressionRows": [{
                "issue": {"code": "missing-equivalency"},
                "copyOnlyDebugText": ["first", "second"]
            }]
        });
        assert_eq!(
            build_source_backed_audit_failure_diagnostic_lines(
                SourceBackedAuditMode::Mapping,
                false,
                &coercion_report,
            ),
            vec![
                "Mapping regression failed: [object Object]",
                "- first,second"
            ]
        );

        let generated_registry_rows = (0..82)
            .map(|index| {
                let issue = match index {
                    0 => json!(0),
                    1 => json!("none"),
                    _ => json!("missing-row"),
                };
                json!({
                    "issue": issue,
                    "copyOnlyDebugText": format!("registry-{index}")
                })
            })
            .collect::<Vec<_>>();
        let generated_registry_report = json!({
            "generatedRegistryRegressionRows": generated_registry_rows,
            "requirementShapeAuditRows": [{"issue": "requirement", "copyOnlyDebugText": "requirement-detail"}],
            "electiveApprovedListShapeAuditRows": [{"issue": "elective", "copyOnlyDebugText": "elective-detail"}],
            "creditCategoryShapeAuditRows": [{"issue": "credit", "copyOnlyDebugText": "credit-detail"}],
            "sequencePathwayShapeAuditRows": [{"issue": "sequence", "copyOnlyDebugText": "sequence-detail"}],
            "singleEquivalencyAuditRows": [{"issue": "equivalency", "copyOnlyDebugText": "equivalency-detail"}]
        });
        let generated_registry_lines = build_source_backed_audit_failure_diagnostic_lines(
            SourceBackedAuditMode::GeneratedRegistry,
            false,
            &generated_registry_report,
        );
        assert_eq!(generated_registry_lines.len(), 170);
        assert_eq!(
            generated_registry_lines[0],
            "Generated registry regression failed: missing-row"
        );
        assert_eq!(generated_registry_lines[1], "- registry-2");
        assert_eq!(generated_registry_lines[159], "- registry-81");
        assert_eq!(
            generated_registry_lines[160],
            "Requirement shape audit failed: requirement"
        );
        assert_eq!(
            generated_registry_lines[168],
            "Single equivalency audit failed: equivalency"
        );

        let coverage_report = json!({
            "requirementCoverageRows": [
                {"issueType": "missing-detected-course", "copyOnlyDebugText": "coverage"},
                {"issueType": "none", "copyOnlyDebugText": "coverage-none"}
            ],
            "sourceScopeAuditRows": [{"issue": "parser-source-scope-violation", "copyOnlyDebugText": "scope"}],
            "regressionChecks": [
                {"label": "passing check", "status": "passed", "details": ["must not print"]},
                {"label": "failed check", "status": "failed", "details": ["detail-a", "detail-b"]},
                {"label": "second failure", "status": "failed", "details": []},
                {"label": "string details", "status": "failed", "details": "x🦖"}
            ]
        });
        let coverage_lines = build_source_backed_audit_failure_diagnostic_lines(
            SourceBackedAuditMode::Coverage,
            false,
            &coverage_report,
        );
        assert_eq!(
            coverage_lines[0],
            "Requirement coverage audit failed: missing-detected-course"
        );
        assert_eq!(coverage_lines[2], "Requirement coverage audit failed: none");
        assert_eq!(coverage_lines[3], "- coverage-none");
        assert_eq!(
            coverage_lines[4],
            "Source scope audit failed: parser-source-scope-violation"
        );
        assert_eq!(
            coverage_lines[6],
            "Coverage regression failed: failed check"
        );
        assert_eq!(coverage_lines[8], "- detail-b");
        assert_eq!(
            coverage_lines[9],
            "Coverage regression failed: second failure"
        );
        assert_eq!(
            coverage_lines[10],
            "Coverage regression failed: string details"
        );
        assert_eq!(coverage_lines[11], "- x");
        assert_eq!(coverage_lines[12], "- 🦖");
        assert!(
            !coverage_lines
                .iter()
                .any(|line| line.contains("passing check"))
        );

        let coverage_cap_rows = (0..42)
            .map(|index| {
                let issue_type = if index == 0 {
                    json!(0)
                } else {
                    json!("missing-course")
                };
                json!({
                    "issueType": issue_type,
                    "copyOnlyDebugText": format!("coverage-{index}")
                })
            })
            .collect::<Vec<_>>();
        let coverage_cap_lines = build_source_backed_audit_failure_diagnostic_lines(
            SourceBackedAuditMode::Coverage,
            false,
            &json!({"requirementCoverageRows": coverage_cap_rows}),
        );
        assert_eq!(coverage_cap_lines.len(), 80);
        assert_eq!(coverage_cap_lines[1], "- coverage-1");
        assert_eq!(coverage_cap_lines[79], "- coverage-40");
    }

    #[test]
    fn coverage_failure_diagnostics_keep_all_cjs_collection_order() {
        let collections = [
            (
                "requirementCoverageRows",
                "issueType",
                "Requirement coverage audit failed",
            ),
            ("sourceScopeAuditRows", "issue", "Source scope audit failed"),
            (
                "generatedSourceSeedAuditRows",
                "issue",
                "Generated source seed audit failed",
            ),
            (
                "generatedShapeAuditRows",
                "issue",
                "Generated shape audit failed",
            ),
            (
                "requirementShapeAuditRows",
                "issue",
                "Requirement shape audit failed",
            ),
            (
                "electiveApprovedListShapeAuditRows",
                "issue",
                "Elective/approved list shape audit failed",
            ),
            (
                "creditCategoryShapeAuditRows",
                "issue",
                "Credit/category shape audit failed",
            ),
            (
                "categoryMappingAuditRows",
                "issue",
                "Category mapping audit failed",
            ),
            (
                "programApprovedFilterAuditRows",
                "issue",
                "Program approved filter audit failed",
            ),
            (
                "sequencePathwayShapeAuditRows",
                "issue",
                "Sequence/pathway shape audit failed",
            ),
            (
                "singleEquivalencyAuditRows",
                "issue",
                "Single equivalency audit failed",
            ),
            (
                "runtimeOptionResolutionAuditRows",
                "issue",
                "Runtime option resolution audit failed",
            ),
            (
                "runtimeCompoundSequenceAuditRows",
                "issue",
                "Runtime compound sequence audit failed",
            ),
            (
                "requiredCoverageSequenceSuppressionAuditRows",
                "issue",
                "Required coverage sequence suppression audit failed",
            ),
            (
                "runtimeCompoundSchedulingAuditRows",
                "issue",
                "Runtime compound scheduling audit failed",
            ),
            (
                "parserOptionExtractionAuditRows",
                "issue",
                "Parser option extraction audit failed",
            ),
            (
                "parserCreditBucketAuditRows",
                "issue",
                "Parser credit bucket audit failed",
            ),
            (
                "parserCategoryOptionAuditRows",
                "issue",
                "Parser category option audit failed",
            ),
            (
                "parserPrerequisiteFilterAuditRows",
                "issue",
                "Parser prerequisite filter audit failed",
            ),
            (
                "parserSequenceChoiceAuditRows",
                "issue",
                "Parser sequence-choice audit failed",
            ),
            (
                "parserExtractionRegressionRows",
                "issue",
                "Parser extraction regression failed",
            ),
        ];
        let mut report = serde_json::Value::Object(serde_json::Map::new());
        let mut expected_labels = Vec::new();
        for (index, (collection, issue_field, label)) in collections.iter().enumerate() {
            let issue = format!("issue-{index}");
            let mut row = json!({"copyOnlyDebugText": format!("detail-{index}")});
            row[*issue_field] = json!(issue);
            report[*collection] = json!([row]);
            expected_labels.push(format!("{label}: issue-{index}"));
        }
        report["regressionChecks"] = json!([{
            "label": "terminal check",
            "status": "failed",
            "details": []
        }]);
        expected_labels.push("Coverage regression failed: terminal check".to_string());

        let lines = build_source_backed_audit_failure_diagnostic_lines(
            SourceBackedAuditMode::Coverage,
            false,
            &report,
        );
        assert_eq!(
            lines
                .iter()
                .step_by(2)
                .map(String::as_str)
                .collect::<Vec<_>>(),
            expected_labels
                .iter()
                .map(String::as_str)
                .collect::<Vec<_>>()
        );
    }

    #[test]
    fn summary_lines_preserve_mode_labels_paths_and_missing_value_semantics() {
        let report = json!({
            "outcome": "failed",
            "summary": {
                "mappingRegressionRowCount": 3,
                "mappingRegressionIssueCount": 1,
                "ownerCount": 2,
                "blockingGate": "source-backed-runtime-coverage",
                "blockingGateIssueCount": 5,
                "issueCountsBySuspectedLayer": {"z-layer": 1, "a-layer": 2},
                "failedRegressionCheckCount": 4
            }
        });
        let mapping_lines = build_source_backed_audit_summary_lines(
            SourceBackedAuditMode::Mapping,
            &report,
            "mapping.json",
            "mapping.md",
        );
        assert_eq!(
            mapping_lines,
            vec![
                "Mapping regression audit outcome: failed".to_string(),
                "Mapping regression rows: 3".to_string(),
                "Mapping regression issues: 1".to_string(),
                "JSON report: mapping.json".to_string(),
                "Markdown report: mapping.md".to_string(),
            ]
        );

        let registry_lines = build_source_backed_audit_summary_lines(
            SourceBackedAuditMode::GeneratedRegistry,
            &report,
            "registry.json",
            "registry.md",
        );
        assert_eq!(
            registry_lines[0],
            "Generated registry regression audit outcome: failed"
        );
        assert_eq!(registry_lines[1], "Owners audited: 2");
        assert_eq!(registry_lines[16], "Protected owner rows: undefined");
        assert_eq!(registry_lines[17], "JSON report: registry.json");

        let coverage_lines = build_source_backed_audit_summary_lines(
            SourceBackedAuditMode::Coverage,
            &report,
            "coverage.json",
            "coverage.md",
        );
        assert_eq!(coverage_lines[0], "coverage audit outcome: failed");
        assert_eq!(
            coverage_lines[1],
            "Blocking gate: source-backed-runtime-coverage"
        );
        assert_eq!(coverage_lines[2], "Blocking gate issues: 5");
        assert_eq!(
            coverage_lines[3],
            "Issues by suspected layer: {\"z-layer\":1,\"a-layer\":2}"
        );
        assert_eq!(coverage_lines[4], "UW owners audited: 2");
        assert!(coverage_lines.contains(&"Source scope audit rows: undefined".to_string()));
        assert_eq!(
            coverage_lines[coverage_lines.len() - 2],
            "JSON report: coverage.json"
        );
        assert_eq!(
            coverage_lines[coverage_lines.len() - 1],
            "Markdown report: coverage.md"
        );
    }

    #[test]
    fn snapshot_hydration_reads_only_targeted_protected_sequence_blocks() {
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let source_root = std::env::temp_dir().join(format!(
            "gator-guide-source-backed-audit-snapshot-{}-{unique}",
            std::process::id()
        ));
        let snapshot_directory = source_root.join("snapshots");
        std::fs::create_dir_all(&snapshot_directory).unwrap();
        std::fs::write(
            snapshot_directory.join("biology.txt"),
            "PHYS 114 not required in other contexts",
        )
        .unwrap();
        std::fs::write(
            snapshot_directory.join("invalid-utf8.txt"),
            &[0xf0, 0x28, 0x8c, 0x28],
        )
        .unwrap();
        let context = json!({
            "targetPlanId": "uw-seattle-biology",
            "parsedBlocksByOwner": {
                "uw-seattle-biology": [
                    {
                        "snapshotPath": "snapshots/biology.txt",
                        "snapshotText": "stale snapshot text"
                    },
                    {
                        "snapshotPath": "snapshots/missing.txt",
                        "snapshotText": "stale missing-file text"
                    },
                    {
                        "snapshotPath": "snapshots/invalid-utf8.txt",
                        "snapshotText": "stale invalid-encoding text"
                    },
                    {
                        "snapshotPath": 0,
                        "snapshotText": "stale falsy-path text"
                    }
                ],
                "uw-seattle-chemistry": [{
                    "snapshotPath": {"not": "a path"},
                    "snapshotText": "not targeted"
                }]
            }
        });

        let hydrated = hydrate_source_backed_audit_snapshot_text(&context, &source_root).unwrap();
        let biology = hydrated
            .pointer("/parsedBlocksByOwner/uw-seattle-biology")
            .and_then(Value::as_array)
            .unwrap();
        assert_eq!(
            biology[0].get("snapshotText").and_then(Value::as_str),
            Some("PHYS 114 not required in other contexts")
        );
        assert_eq!(biology[1].get("snapshotText"), None);
        assert_eq!(
            biology[2].get("snapshotText").and_then(Value::as_str),
            Some("�(�(")
        );
        assert_eq!(biology[3].get("snapshotText"), None);
        assert_eq!(
            hydrated
                .pointer("/parsedBlocksByOwner/uw-seattle-chemistry/0/snapshotText")
                .and_then(Value::as_str),
            Some("not targeted")
        );
        assert_eq!(
            context
                .pointer("/parsedBlocksByOwner/uw-seattle-biology/0/snapshotText")
                .and_then(Value::as_str),
            Some("stale snapshot text")
        );
        let invalid_path = json!({
            "targetPlanId": "uw-seattle-biology",
            "parsedBlocksByOwner": {
                "uw-seattle-biology": [{"snapshotPath": {"unexpected": true}}]
            }
        });
        assert!(hydrate_source_backed_audit_snapshot_text(&invalid_path, &source_root).is_err());
        std::fs::remove_dir_all(source_root).unwrap();
    }

    #[test]
    fn report_paths_match_the_planner_tmp_report_filenames_for_each_mode() {
        let source_root = std::path::Path::new("source-root");
        for (mode, json_name, markdown_name) in [
            (
                SourceBackedAuditMode::Mapping,
                "transfer-planner-mapping-audit.json",
                "transfer-planner-mapping-audit.md",
            ),
            (
                SourceBackedAuditMode::GeneratedRegistry,
                "transfer-planner-generated-registry-audit.json",
                "transfer-planner-generated-registry-audit.md",
            ),
            (
                SourceBackedAuditMode::Coverage,
                "transfer-planner-source-backed-coverage-audit.json",
                "transfer-planner-source-backed-coverage-audit.md",
            ),
        ] {
            let paths = source_backed_audit_report_paths(source_root, mode);
            assert_eq!(
                std::path::PathBuf::from(paths.json_report_path),
                source_root.join(".tmp").join("reports").join(json_name)
            );
            assert_eq!(
                std::path::PathBuf::from(paths.markdown_report_path),
                source_root.join(".tmp").join("reports").join(markdown_name)
            );
        }
    }

