    #[test]
    fn rendered_artifact_writer_keeps_json_before_markdown_on_io_failure() {
        let unique = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let output_root = std::env::temp_dir().join(format!(
            "gator-guide-source-backed-audit-write-{}-{unique}",
            std::process::id()
        ));
        std::fs::create_dir_all(&output_root).unwrap();
        let blocked_parent = output_root.join("not-a-directory");
        std::fs::write(&blocked_parent, "file blocks markdown parent").unwrap();
        let artifacts = SourceBackedAuditRenderedArtifacts {
            mode: SourceBackedAuditMode::Mapping,
            json_report_path: output_root.join("report.json"),
            markdown_report_path: blocked_parent.join("report.md"),
            report_json: "{\"outcome\":\"passed\"}\n".to_string(),
            markdown: "# Report\n".to_string(),
            summary_lines: Vec::new(),
            diagnostic_lines: Vec::new(),
            exit_code: 0,
        };

        assert!(write_source_backed_audit_rendered_artifacts(&artifacts).is_err());
        assert_eq!(
            std::fs::read_to_string(&artifacts.json_report_path).unwrap(),
            artifacts.report_json
        );
        assert!(!artifacts.markdown_report_path.exists());
        std::fs::remove_dir_all(output_root).unwrap();
    }

    #[test]
    fn execution_renderer_serializes_reports_and_collects_display_output_in_memory() {
        let execution = assemble_source_backed_audit_execution_artifacts(
            SourceBackedAuditMode::Mapping,
            false,
            json!({
                "outcome": "failed",
                "summary": {"mappingRegressionRowCount": 1, "mappingRegressionIssueCount": 1},
                "mappingRegressionRows": [{
                    "issue": "missing-equivalency",
                    "copyOnlyDebugText": "mapping detail"
                }]
            }),
            "# Mapping audit".to_string(),
        );
        let source_root = std::path::Path::new("source-root");
        let rendered =
            render_source_backed_audit_execution_artifacts_for_source_root(&execution, source_root)
                .unwrap();
        let report_directory = source_root.join(".tmp").join("reports");
        let json_report_path = report_directory
            .join("transfer-planner-mapping-audit.json")
            .display()
            .to_string();
        let markdown_report_path = report_directory
            .join("transfer-planner-mapping-audit.md")
            .display()
            .to_string();

        assert_eq!(rendered.mode, SourceBackedAuditMode::Mapping);
        assert!(rendered.report_json.ends_with('\n'));
        assert_eq!(
            serde_json::from_str::<Value>(&rendered.report_json).unwrap(),
            execution.report
        );
        assert_eq!(rendered.markdown, "# Mapping audit\n");
        assert_eq!(
            rendered.summary_lines[3],
            format!("JSON report: {json_report_path}")
        );
        assert_eq!(
            rendered.summary_lines[4],
            format!("Markdown report: {markdown_report_path}")
        );
        assert_eq!(
            rendered.diagnostic_lines[0],
            "Mapping regression failed: missing-equivalency"
        );
        assert_eq!(rendered.exit_code, 1);
    }

    #[test]
    fn report_only_mode_suppresses_audit_failure_exit_code() {
        let failed = json!({"outcome": "failed"});
        let passed = json!({"outcome": "passed"});
        assert_eq!(source_backed_audit_failure_exit_code(false, &failed), 1);
        assert_eq!(source_backed_audit_failure_exit_code(true, &failed), 0);
        assert_eq!(source_backed_audit_failure_exit_code(false, &passed), 0);
        assert_eq!(source_backed_audit_failure_exit_code(false, &json!({})), 0);
        assert_eq!(
            source_backed_audit_failure_exit_code_for_mode(
                SourceBackedAuditMode::Mapping,
                false,
                &json!({
                    "outcome": "passed",
                    "mappingRegressionRows": [{"issue": "missing-equivalency"}]
                })
            ),
            1
        );
        assert_eq!(
            source_backed_audit_failure_exit_code_for_mode(
                SourceBackedAuditMode::Mapping,
                false,
                &json!({
                    "outcome": "failed",
                    "mappingRegressionRows": [{"issue": "none"}]
                })
            ),
            0
        );
        assert_eq!(
            source_backed_audit_failure_exit_code_for_mode(
                SourceBackedAuditMode::GeneratedRegistry,
                false,
                &json!({
                    "outcome": "passed",
                    "requirementShapeAuditRows": [{"issue": "invalid-shape"}]
                })
            ),
            1
        );
        assert_eq!(
            source_backed_audit_failure_exit_code_for_mode(
                SourceBackedAuditMode::Coverage,
                false,
                &json!({
                    "outcome": "passed",
                    "requirementCoverageRows": [{"issueType": "missing-course"}]
                })
            ),
            1
        );

        let artifacts = assemble_source_backed_audit_execution_artifacts(
            SourceBackedAuditMode::Mapping,
            false,
            json!({
                "outcome": "failed",
                "mappingRegressionRows": [{
                    "issue": "missing-equivalency",
                    "copyOnlyDebugText": "mapping detail"
                }]
            }),
            "# mapping report\n".to_string(),
        );
        assert_eq!(artifacts.mode, SourceBackedAuditMode::Mapping);
        assert_eq!(artifacts.exit_code, 1);
        assert_eq!(artifacts.markdown, "# mapping report\n");
        assert_eq!(
            artifacts.diagnostic_lines,
            vec![
                "Mapping regression failed: missing-equivalency",
                "- mapping detail"
            ]
        );
        let report_only_artifacts = assemble_source_backed_audit_execution_artifacts(
            SourceBackedAuditMode::Mapping,
            true,
            artifacts.report.clone(),
            artifacts.markdown.clone(),
        );
        assert_eq!(report_only_artifacts.exit_code, 0);
        assert!(report_only_artifacts.diagnostic_lines.is_empty());
        assert_eq!(report_only_artifacts.report, artifacts.report);
        assert_eq!(report_only_artifacts.markdown, artifacts.markdown);

        let issue_rows_override_outcome = assemble_source_backed_audit_execution_artifacts(
            SourceBackedAuditMode::Mapping,
            false,
            json!({
                "outcome": "passed",
                "mappingRegressionRows": [{"issue": "missing-equivalency"}]
            }),
            String::new(),
        );
        assert_eq!(issue_rows_override_outcome.exit_code, 1);
        let none_issue_does_not_fail = assemble_source_backed_audit_execution_artifacts(
            SourceBackedAuditMode::Mapping,
            false,
            json!({
                "outcome": "failed",
                "mappingRegressionRows": [{"issue": "none"}]
            }),
            String::new(),
        );
        assert_eq!(none_issue_does_not_fail.exit_code, 0);
    }

    #[test]
    fn audit_cli_options_match_script_harness_flag_and_value_rules() {
        let args = [
            "--mapping-only",
            "--generated-registry-only",
            "--report-only",
            "--protected-only",
            "--target-plan-id",
            "\u{feff} plan-a \u{feff}",
        ]
        .map(String::from);
        assert_eq!(
            parse_source_backed_audit_cli_options(&args),
            SourceBackedAuditCliOptions {
                mapping_only: true,
                generated_registry_only: true,
                report_only: true,
                target_plan_id: Some("plan-a".to_string()),
                protected_only: true,
            }
        );

        let direct_empty_wins = [
            "--target-plan-id= ",
            "--target-plan-id",
            "plan-b",
            "--mapping-only=1",
        ]
        .map(String::from);
        assert_eq!(
            parse_source_backed_audit_cli_options(&direct_empty_wins),
            SourceBackedAuditCliOptions::default()
        );

        let direct_value_wins =
            ["--target-plan-id= plan-a ", "--target-plan-id", "plan-b"].map(String::from);
        assert_eq!(
            parse_source_backed_audit_cli_options(&direct_value_wins).target_plan_id,
            Some("plan-a".to_string())
        );

        let missing_target_value = ["--target-plan-id", "--report-only"].map(String::from);
        let options = parse_source_backed_audit_cli_options(&missing_target_value);
        assert_eq!(options.target_plan_id, None);
        assert!(options.report_only);
    }

