    #[test]
    fn serialized_coverage_artifacts_follow_shared_report_format() {
        let report = json!({"generatedAt": "2026-01-01T00:00:00Z", "outcome": "passed"});
        let source_markdown = "# Transfer Planner Coverage Audit\n";
        let (report_json, markdown) =
            serialize_source_backed_coverage_artifacts(&report, source_markdown).unwrap();

        assert_eq!(
            report_json,
            "{\n  \"generatedAt\": \"2026-01-01T00:00:00Z\",\n  \"outcome\": \"passed\"\n}\n"
        );
        assert_eq!(markdown, "# Transfer Planner Coverage Audit\n");
        assert_eq!(
            serialize_source_backed_audit_artifacts(&report, source_markdown).unwrap(),
            (report_json, markdown)
        );
        let numeric_report: Value = serde_json::from_str(r#"{"10":1.0,"2":2.0,"x":3.0}"#).unwrap();
        assert_eq!(
            serialize_source_backed_json(&numeric_report).unwrap(),
            "{\n  \"2\": 2,\n  \"10\": 1,\n  \"x\": 3\n}\n"
        );
        let js_numeric_report: Value = serde_json::from_str(
            r#"{"small":0.000001,"tiny":1e-7,"large":1e21,"negativeZero":-0.0}"#,
        )
        .unwrap();
        assert_eq!(
            serialize_source_backed_json(&js_numeric_report).unwrap(),
            "{\n  \"small\": 0.000001,\n  \"tiny\": 1e-7,\n  \"large\": 1e+21,\n  \"negativeZero\": 0\n}\n"
        );
        let rounded_js_number: Value =
            serde_json::from_str(r#"{"value":9007199254740993}"#).unwrap();
        assert_eq!(
            serialize_source_backed_json(&rounded_js_number).unwrap(),
            "{\n  \"value\": 9007199254740992\n}\n"
        );
        let property_order_report: Value =
            serde_json::from_str(r#"{"z":0,"4294967295":1,"2":2,"4294967294":3}"#).unwrap();
        assert_eq!(
            serialize_source_backed_json(&property_order_report).unwrap(),
            "{\n  \"2\": 2,\n  \"4294967294\": 3,\n  \"z\": 0,\n  \"4294967295\": 1\n}\n"
        );
        let nested_numeric_report: Value =
            serde_json::from_str(r#"{"items":[1.0,{"10":10,"2":2,"negativeZero":-0.0}]}"#).unwrap();
        assert_eq!(
            serialize_source_backed_json(&nested_numeric_report).unwrap(),
            "{\n  \"items\": [\n    1,\n    {\n      \"2\": 2,\n      \"10\": 10,\n      \"negativeZero\": 0\n    }\n  ]\n}\n"
        );
        assert_eq!(
            serialize_source_backed_json(&json!({"text": "quote \" slash \\ newline\n"})).unwrap(),
            "{\n  \"text\": \"quote \\\" slash \\\\ newline\\n\"\n}\n"
        );
    }

